(function(){
  var KB = window.KB_PRESETS || (window.KB_PRESETS = {});
  var a = KB["guimi"] || (KB["guimi"] = []);
  var add = [{"title":"七大教会与隐秘组织","content":"七大正统教会：黑夜女神教会（鲁恩国教）、风暴之主教会（海上，海祭传统）、蒸汽与机械之神教会（工业国，机械之心部队）、知识与智慧之神教会（白塔，图书馆与学院）、永恒烈阳教会、大地母神教会、战神教会。各有非凡者部队与地盘。隐秘组织（危险与机遇并存）：心理炼金会（实验狂人，人体实验）、夜之隐修会（异端邪教）、生命学派（神秘学学术，亦正亦邪）、摩斯苦修会、秘密教团（拜旧日的疯子）。生态：教会官僚庇护+隐秘组织诱惑陷阱+黑市魔药交易——玩家在三者间行走，每一步都是立场选择题。","category":"组织","tags":["教会","隐秘组织"],"alwaysInclude":false,"priority":"medium"},{"title":"鲁恩·廷根（开局舞台）","content":"鲁恩王国北部小城，故事开局地：黑荆棘安保公司（值夜者掩护据点）、教堂区的钟楼与雪夜弥撒、煤气灯与马拉车的街道、契克斯图书馆。案件生态：表面是市井治安案，底下常藏着走私魔药、隐秘组织渗透、失控者伤人。入门级案件范例：仓库区灵异失踪（灵界生物作祟）、码头魔药原材料走私（黑市线）、疯人院的\"妄想症\"（实为失控前兆）。物价锚点：普通职员月薪1-2金镑，一顿好饭几个先令，情报一条几便士到几镑不等。主持要点：廷根的味道是\"小城安静表皮下的暗流\"，案件小而真，人情味浓。","category":"设定","tags":["鲁恩","廷根"],"alwaysInclude":false,"priority":"medium"},{"title":"贝克兰德雾都","content":"鲁恩之都、世界最大城市：皇后区（贵族宅邸与沙龙）、桥区（金融与报馆）、贝克街一带（中产与侦探事务所）、贫民窟（雾夜无名尸的最佳案发地）。中教堂（圣塞巴斯蒂安教堂）坐镇黑夜女神教区，教会分会、隐秘组织据点、黑市（索伦区后巷）密布。超常生态：此地的非凡事件密度远超廷根——价值更高的魔药配方、更大的隐秘组织网、更深的教会政治。机会与危险都翻倍：一条情报可能换来序列晋升材料，也可能引来心理炼金会的\"邀请\"。主持要点：贝克兰德的味道是\"雾都的浮华与深渊一体两面\"，写雾、写报童的号外、写马车夫的抱怨，用市井衬非凡。","category":"设定","tags":["贝克兰德","雾都"],"alwaysInclude":false,"priority":"medium"},{"title":"灵界与灵性法则","content":"灵界：精神与象征的海洋，与现实世界重叠——同一片空间，另一套法则。灵界有原住民（灵界生物，形态诡异）、历史残留的碎片场景、被高序列存在盘踞的领域。灵性：非凡者的\"燃料\"，施法、占卜、入梦都消耗灵性，耗尽则虚弱甚至昏迷；恢复靠冥想、灵性材料、祈祷。铁律：(1)注视是双向的——你凝视灵界，灵界也凝视你，窥探高层次存在会被污染；(2)高序列可标记凡人的灵性，被标记者无处遁形；(3)灵界行走要\"遮蔽自身\"，善用灰雾、符号、仪式护屏。主持要点：灵界描写走\"象征与几何错乱\"路线，少写实多写\"不合常理的构图\"。","category":"设定","tags":["灵界","灵性"],"alwaysInclude":false,"priority":"medium"},{"title":"仪式魔法与献祭","content":"仪式魔法：以符文、材料、咒文构筑\"接口\"，向灵界或存在借力——低序列撬动高效果的杠杆。要素：祭坛（符号与方位）、祭品（与所求对应的象征物，血祭效果强但污染重）、咒文（古赫密斯语等，念错即反噬）。献祭：向存在（神、天使、灵界生物）献上祭品换取回应——回应者不可控，可能来得不是你要的那位。纪律：(1)仪式必留痕迹，事后要清理或遮蔽；(2)重大仪式前先布防（遮蔽仪式、警告咒）；(3)对不熟悉的存在开仪式等于敲陌生人的门——开门的可能是任何东西。主持要点：仪式戏要写出\"程序感与压迫感\"，每一步都不能省，出错要有后果。","category":"设定","tags":["仪式","献祭"],"alwaysInclude":false,"priority":"medium"},{"title":"克莱恩详录","content":"穿越者周明瑞，附身鲁恩青年克莱恩·莫雷蒂。性格：谨慎到近乎怂（每次行动先想退路）、聪明爱自嘲（内心吐槽是原著灵魂）、对同伴重情重义。命运线：占卜家序列9（黑荆棘安保）→灰雾之上苏醒，扮演\"愚者先生\"创立塔罗会→值夜者历练（廷根小队）→调任贝克兰德（无面人、秘偶大师）→海上远行（与风暴教会周旋）→高序列博弈（卷入诸神棋局）→神弃之世终局。他的战斗风格：占卜预判+纸人替身+火焰炸弹+诈死逃跑，\"苟\"出风格\"苟\"出水平。共世模式下按原著成长；他写给玩家的相处方式：可信任但不轻信，可结盟但留后手。","category":"人物","tags":["克莱恩"],"alwaysInclude":false,"priority":"medium"},{"title":"值夜者同僚（廷根小队群像）","content":"邓恩·史密斯：队长，午夜诗人，灰发温和，办公室里挂着队内历任牺牲者画像——\"值夜者的宿命\"是他的口头禅，护短到可以为队员抗命。老尼尔：占卜家序列9，税务官做派的唠叨中年人，做饭难吃，对新人极其照顾。罗尔丹：沉默的战斗担当。波尔卡·蒂姆：机械之心借调的爆破手。莱昂纳德·米切尔：与克莱恩同期的新人，嘴上轻浮（总泡在酒馆）实际观察力敏锐，身负夜之隐修会相关的秘密身份。主持要点：这支队伍的日常是\"案件+饭桌+互损\"，感情线要像老照片一样慢慢显影；原著中廷根小队的结局（雪山任务）是悲剧锚点，主持可选择保留或让玩家改写。","category":"人物","tags":["值夜者","廷根小队"],"alwaysInclude":false,"priority":"medium"},{"title":"塔罗会成员详录","content":"正义/奥黛丽·霍尔：贝克兰德霍尔伯爵家千金，观众途径，金发碧眼气质明媚，好奇心驱动一切，梦想成为\"愚蠢的漂亮女士\"的反面——真正的智者；她的成长线是从旁观者到心理医生级的存在。倒吊人/阿尔杰·威尔逊：风暴教派出身的水手头目，冷面务实，情报贩子，口头禅是谈价码；他忠诚的对象是\"愚者\"这个符号而非任何个人。太阳/德里克·伯格：从\"神弃之地\"逃出的纯真少年，被假神抛弃的真信徒，塔罗会最柔软的部分；他的委屈与重建信仰是长线感情戏。月亮/埃姆林·怀特：被迫转化的吸血鬼，想活下去的普通人。主持要点：塔罗会集会戏写\"各怀心思的扮演感\"，散会后写\"他们在人间的真实处境\"，两相对照出味道。","category":"人物","tags":["塔罗会","正义","倒吊人","太阳"],"alwaysInclude":false,"priority":"medium"},{"title":"天使与旧日（深层存在）","content":"天使：序列2与序列1的存在，各自承载神话与规则（如黑夜女神麾下的天使、风暴之主的化身），注视凡人即可降下祝福或污染；天使也有自己的疯狂与宿命。旧日支配者：第二纪的古老存在——堕落母神、原初魔女、被缚之神等，它们被囚禁、沉眠或以更诡异的方式存在，名字本身就是力量，接触即有污染风险。第四纪末的大灾变与诸神的崛起都系于此。主持纪律：凡人视角的故事止步于\"知道名字\"，玩家角色最高只能触及天使层面的边缘互动；旧日层面只作传闻、梦境碎片与疯狂呓语，永远不要让玩家\"面对面\"。","category":"设定","tags":["天使","旧日"],"alwaysInclude":false,"priority":"low"},{"title":"时代风貌·蒸汽与煤气灯","content":"十九世纪末锚点细节库：照明——煤气灯（街道）、蜡烛与煤油灯（室内）；交通——马拉轨道车、蒸汽火车（票价按舱等）、四轮马车；通讯——信件（邮资按重量）、电报（按字计费，昂贵）、报纸晚报（便士报）；货币——金镑/先令/便士（1镑=20先令=240便士，职员月薪1-2镑，女工月薪不足1镑，一杯酒几个便士）；饮食——茶与吐司（早餐标配）、炖菜与黑面包（平民）、下午茶与晚宴（体面人家）；衣着——礼帽、马甲、怀表链、长裙与束腰、雨伞是体面标配；娱乐——酒馆、剧院、沙龙、海德公园散步。主持要点：这些细节按场景密度撒入正文，是\"诡秘味\"的最大来源。","category":"设定","tags":["时代风貌"],"alwaysInclude":false,"priority":"low"},{"title":"文风圣经·爱潜水的乌贼","content":"六条总纲：(1)冷叙述+内心吐槽：外部叙事冷静克制（约九分），穿插主角的内心吐槽（约一分），吐槽是人物魅力与读者喘息口；(2)非凡场面写流程感：占卜、仪式、晋升都要有庄重的\"工作流程\"——笔直的步骤反而衬出超常的力量；(3)雾都质感反复点缀：煤气灯、雾、马蹄声、报纸油墨味，环境细节按密度撒但别堆砌；(4)每章末留\"不对劲\"：一个细节、一句对话、一个数字的偏差，让人脊背发凉；(5)装腔与翻脸要干脆：塔罗会里的威严装腔和现实的狼狈逃命之间的落差是喜剧与惊悚的双重来源；(6)非凡者之间用代号与敬称，距离感即神秘感。","category":"文风","tags":["文风","乌贼"],"alwaysInclude":false,"priority":"medium"},{"title":"大事年表框架","content":"主线时间轴（按原著推进大势，玩家嵌在其中）：1349年初克莱恩穿越廷根→加入黑荆棘安保→灰雾之上苏醒、塔罗会初立（正义、倒吊人入场）→廷根系列案（失踪案、魔药走私案）→雪山任务与廷根小队之殇→调任贝克兰德（无面人晋升、初入雾都非凡圈）→贝克兰德系列案（连环案、教会政治）→海上远行（风暴教会、殖民地航线）→序列晋升与诸神棋局渐深→神弃之世（旧日苏醒、终局之战）。玩家可在任意段落嵌入，但大事件时序与结果按原著，玩家只改自己份内。","category":"年表","tags":["年表"],"alwaysInclude":false,"priority":"medium"},{"title":"封印物与危险物品（收容与借用）","content":"封印物：教会收容的危险非凡物品，按危险性分级（0级封印物最危险，如涉及旧日的存在残骸）。特征：物品自带\"负面效应\"——强大力量必伴随诅咒或侵蚀（如能实现愿望的灯会索取等价代价、能看到过去的怀表会让人沉迷过往）。使用纪律：借用需审批，使用需付出代价，长期接触会污染持有者。民间危险物品：黑市流通的残缺魔药、非凡生物制品（眼珠、血肉）、被诅咒的传家物——它们是案件的最佳火种。主持要点：给玩家的每一件\"宝物\"都该带刺——力量与代价明码标价，让\"要不要用\"成为真正的抉择，这是诡秘世界的核心质感之一。","category":"设定","tags":["封印物","收容","危险物品"],"alwaysInclude":false,"priority":"medium"},{"title":"占卜与灵性仪式流程（常用操作手册）","content":"常用非凡操作流程（主持非凡案件时的标准件）：(1)占卜——占卜家以灵性材料（如占卜铜币、灵性粉末）配合手势咒文问询，答案以象征呈现（画面、数字、方位），需要\"灵性之眼\"解读；被反占卜屏蔽则得到模糊结果。(2)灵性视觉——开启灵眼观察环境残留的灵性痕迹（情绪、死亡、非凡波动），代价是灵性消耗与被注视风险。(3)遮蔽仪式——出行或行动前布置，防止被高序列占卜定位。(4)梦境占卜——入梦问询，深入者有去无回。(5)驱邪与净化——对灵界污染的现场用圣水、符号、祷言处理，流程不完整则污染残留。主持要点：写这些操作时严格给\"材料+步骤+代价\"三件套，占卜结果保持象征性而非直给答案。","category":"设定","tags":["占卜","仪式","灵性视觉","流程"],"alwaysInclude":false,"priority":"medium"},{"title":"序列9起步：各途径低序列能力速查（给玩家选路用）","content":"玩家可选途径的低序列（序列9-8）能力速查：占卜家（占卜、灵性视觉）/小丑（身体控制、纸人替身、面容微调）；观众（读情绪、暗示）/窃梦者（入梦窥探）；睡眠者（梦境感知、安眠）/午夜诗人（夜视、黑暗中的敏锐）；读者（速读、记忆宫殿）/博学者（知识检索、仪式速学）；猎人（追踪、枪械精通）/挑衅者（激怒控制）；掘墓人（感知死亡、骸骨操纵基础）/殡葬人（尸体防腐、亡者低语）；水手（航海、风感）/海怒（风浪祈唤）；驯兽师（兽群感应、驯化）等。规则：每条途径给两个低序列足矣，玩家晋升到序列8再解锁细节；不同途径能力不得混用；扮演法的要求写进晋升提示。","category":"设定","tags":["序列9","低序列","选路"],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘之主·非凡特性守恒与高序列规则","content":"高序列世界的硬规则，中期起逐步向玩家揭示。非凡特性守恒与不灭：每条途径的非凡特性总量固定，不增不减；非凡者死亡后特性析出，成为制作魔药的核心材料——猎杀高序列者即是收割材料，这构成高序列博弈的底层逻辑。晋升序列0的三要件：集齐对应途径的唯一性、加三份序列1非凡特性；同途径同一时间只能存在一位序列0，故同途径强者必然敌对。半神门槛：序列4起神性渐强、人性被吞噬，高序列强者发生质变、近乎神灵，故有半神半人与神话生物之称。锚：半神以锚稳定人性、对抗神性侵蚀，最常见的锚是凡人的信仰与信徒的祈祷；序列0真神必须依靠足够的锚维持理智与存在——这正是教会在中低序列慷慨分享配方、高序列只供成品魔药的隐秘原因（罗塞尔日记之问的答案方向）。相邻途径互换：如不眠者与收尸人途径、通识者与窥秘人途径可在序列4起互相替代。主持要点：这些规则在凡人视角阶段只是传闻，透露节奏随剧情推进。","category":"规则","tags":["非凡特性","守恒","唯一性","半神","锚","序列0"],"alwaysInclude":false,"priority":"top"},{"title":"诡秘之主·因蒂斯与南大陆风貌","content":"北大陆之外的世界版图。因蒂斯共和国（后为帝国）：罗塞尔的发迹之地，法兰西风味最浓——白枫宫（罗塞尔遇刺处）、索伦家族（原因蒂斯王族，参与弑帝）、与工匠之神教会的深度绑定皆在此；罗塞尔治下伦堡等国被纳入保护，北大陆强国相继低头。南大陆：分东拜朗与西拜朗，是死神教会的发源地，也是灵教团、玫瑰学派等隐秘组织的大本营，常年战乱、超凡事件频发，秩序远比北大陆脆弱。神弃之地：位于大陆之外的绝境，被众神遗弃，天地间充满疯狂低语，生存着上古遗留的怪物与白银城、月城等人类遗民，藏着世界起源的终极秘密——白银城少年德里克·伯格即从那里逃出，被假神抛弃的真信徒。殖民地与航线：列强的殖民网络与苏尼亚海等海域构成出海线，海盗、私掠与商路交织。主持要点：其一，南大陆写乱世感——军阀、教派、瘟疫与废墟；其二，神弃之地前期只作传闻与遗民证词，切勿让玩家轻易抵达；其三，出海是序列晋升材料的经典来源。","category":"地理","tags":["因蒂斯","南大陆","神弃之地","白银城","殖民地"],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘之主·八卷脉络与终局方向（防剧透版）","content":"全书八卷对应克莱恩的晋升阶梯，作为大势框架使用：第一卷小丑（廷根，真实造物主事件，序列9至8）；第二卷无面人（贝克兰德侦探时代与大雾霾，序列8至6）；第三卷旅行家（出海与神弃之地，序列6至4）；第四卷至第八卷逐步走向更高序列的博弈——诸神棋局、塔罗会扩张为跨阵营网络、神弃之世的末日危机渐次展开，克莱恩最终以凡人之躯登顶序列0愚者，融合相邻途径权柄成就半旧日诡秘之主，以自身为锚对抗上古意识复苏与外神入侵，为人类守住生机后陷入沉睡。主题线索：世界起源于最初造物主，精神分裂出两大对立人格；外神是来自星空的旧日支配者，世界屏障破损、污染不断渗透；非凡体系的本质是上古遗留。主持纪律：凡人视角时代只执行前两至三卷的节奏，后续大势仅作伏笔与传闻；终局真相永不提前抖出，涉及星空与旧日的话题一律以疯狂呓语和档案残页呈现。","category":"年表","tags":["八卷","大势","终局","防剧透","愚者"],"alwaysInclude":false,"priority":"low"},{"title":"诡秘之主·第三纪灾变纪元与远古太阳神","content":"第三纪在官方叙事中称光辉纪元，被隐瞒的真实历史则称灾变纪元。光辉年代：远古太阳神统治大地，光照诸国，是旧日之后世界难得的秩序时代。转折源于堕落——太阳神麾下的几位天使之王被引诱背叛，酿成大灾变；真实造物主（太阳神的人性部分）随之现世，神弃之地与其他大陆的联系被彻底割裂，世界坠入灾难年代。真相的骨架是：救赎蔷薇组织设计弑神，杀死远古太阳神；其身躯被纯白、智、风三位天使之王分食，三者借非凡特性晋升为真神——即后来的永恒烈阳、知识与智慧之神、风暴之主；而太阳神的神性在亚当（隐秘之主侧）身上苏醒，人性化为真实造物主，成为贯穿后世千年阴谋的暗线。本纪末尾出现了第二块亵渎石板。白银城保存着这段被官方抹去的历史，是玩家追索真相的关键线索源。要点：写第三纪故事时，太阳神之死是万恶之源也是万光之源——此后诸神的合法性、教会的世仇、亚当的千年布局，全部回溯到这场弑神。","category":"年表","tags":[],"alwaysInclude":false,"priority":"top"},{"title":"诡秘之主·黑夜途径全序列细则","content":"黑夜途径对应塔罗牌「星星」，序列0为「黑暗」，是黑夜女神教会的正统途径，主打阴影操控、入梦与灵体镇压。全序列为：序列9不眠者——无需睡眠、夜间感官锐利，是值夜者的常见出身；序列8午夜诗人——夜间能力增幅，掌握低语式精神影响；序列7梦魇——可潜入梦境、以梦杀人；序列6安魂师——安抚亡魂、净化灵异；序列5灵巫——役使灵体、沟通幽界；序列4守夜人（半神）——黑夜领域的具象化，可折叠阴影、放逐邪祟；序列3恐惧主教——编织恐惧、辐射心灵威压；序列2隐秘之仆——行于隐秘、近乎不可侦知；序列1厄难骑士——灾难与厄运的具现者；序列0黑暗——黑夜权柄本体。机制要点：黑夜与死亡（收尸人途径）、战争（战士途径）同属永暗之河阵营，序列3以上可互换途径，跨阵营强行晋升会神性暴走；该途径低序列战力平平而夜战无解，消化魔药的核心「扮演」是成为黑暗中的守望者——这正是值夜者小队的精神原型。","category":"规则","tags":[],"alwaysInclude":false,"priority":"top"},{"title":"诡秘之主·占卜家途径全序列细则","content":"占卜家途径对应塔罗牌「愚者」，序列0为「愚者」，属源堡阵营，是克莱恩的本命路线，主打占卜、幻术、人偶操控与回溯历史。全序列：序列9占卜家——以灵摆、占卜棒等借助灵性预判吉凶；序列8小丑——身体控制与近战特化，侥幸与滑稽是其守护；序列7魔术师——纸人替身、火焰吐息等十种戏法，实战骗术大师；序列6无面人——可改变容貌身形，易容之极；序列5秘偶大师——以灵性丝线操控人偶傀儡，收尸制偶；序列4诡法师（半神）——幻术成域、真实与虚假混淆；序列3古代学者——可短暂回溯至古代历史片段、借古之力；序列2奇迹师——操弄概率、制造「奇迹」；序列1诡秘侍者——诡秘之主的近侍，执掌隐秘；序列0愚者——源堡之主、灰雾之上的权柄。机制要点：占卜家低序列看似文弱，实则每一步都补足上一环的短板（易容、傀儡、回溯），越往后越接近「欺瞒世界」的本质；扮演核心是「在未知面前保持敬畏与幽默」，这正是愚者神格的底色。","category":"规则","tags":[],"alwaysInclude":false,"priority":"top"},{"title":"诡秘之主·塔罗会成员序列晋升轨迹","content":"塔罗会成员的晋升轨迹是全书的一条隐形进度条。克莱恩（愚者）：占卜家→小丑→魔术师→无面人→秘偶大师→诡法师→古代学者→奇迹师→诡秘侍者→序列0愚者，从偷听者一路成为神明。奥黛丽（正义）：观众途径，观众→读心者→心理医生→催眠师→梦境行者→操纵师→织梦人→洞察者→作家，朝空想家进发，终成半神并离家人远行。阿尔杰（倒吊人）：走与风暴侧相关的途径，从水手系一路攀升至半神级「海王」层次，老谋深算、忠诚于利益而非信仰。休（审判）：仲裁人途径，仲裁人→治安官→审讯者→法官，一路以官方秩序非凡者身份成长。弗尔思（月亮）：走歌颂者侧的途径，以歌咏之力修行。加德纳·马丁（太阳）、Derrick·伯格（世界，太阳神官侧的「太阳」 Junior）亦各有攀升。细则是：成员间的魔药材料互助、神秘学知识交换与灰雾加持是火箭式晋升的引擎——在灰雾中交换配方、举行晋升仪式，可获得近乎无污染的稳定消化。主持要点：让每名成员有一条可查的序列进度线，是维护长线代入感的关键。","category":"人物","tags":[],"alwaysInclude":false,"priority":"top"},{"title":"诡秘之主·外神与星空格局","content":"旧日之上还有外神与星空的至高层格局。「最初造物主」沉睡后分裂出的诸多人格与产物中，旧日（堕落母神、混沌之子、命运编织者、宿命之环、超星主宰、高维俯视者、不熄的呓语、原初饥饿、衰败君王等）是可直接干涉现实的存在；外神则是宇宙深处的更古老者，最初曾从三位外神身上撕裂部分用于自身的分裂，可见其位格之高。星空在此世界观里不是浪漫的天文，而是危险本身：窥秘人途径的描述「星空是伟大的又是危险的」即是明旨，直视星空会招致污染，占星类非凡者皆受训规避星空的注视。这一格局的叙事功能有三：其一，为「序列之上仍有天花板」的敬畏感提供终极背景；其二，解释灵界、星界与现实三层世界的联动机制——星灵体是凡人与灵界星空沟通的桥梁，占卜即借道于此；其三，为终局层面的大阴谋（真实造物主、旧日复苏）提供纵深。主持要点：外神与星空只宜作为远景与污染源头出现，一旦具象登场须保持「不可名状」的克制笔法。","category":"设定","tags":[],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘之主·愚者信仰的神化进程","content":"愚者信仰是全书最独特的「凡人造神」样本，其进程分五步。第一步，灰雾之上偶然成位：克莱恩借源堡成为灰雾之主，以「愚者先生」身份主持集会。第二步，成员自发造神：奥黛丽等人基于敬畏与感激，自行脑补出「不属于这个时代的愚者先生」的教义、祷文与尊名，信仰在极小范围成形。第三步，仪式与神职的完善：灰雾中交换配方、举行晋升仪式、远程净化污染，使愚者具备了「回应祈祷、赐福信徒」的功能性神迹，信仰闭环成立。第四步，外部扩散：随着成员活动与口耳相传，愚者之名流入值夜者档案、地下组织与民间神秘学圈，「愚者教会」的雏形——由完全不知神明真身的信徒组成的网络——开始运转，克莱恩本人反而成了自己信仰的第一位「信徒」。第五步，序列与神格合一：克莱恩沿占卜家途径攀升至诡秘侍者，最终以愚者之名登临序列0，凡人造神完成闭环。要点：这一进程的引擎是「信息差」与「集体想象」，写信仰戏时要突出信徒脑补的庄严与克莱恩本人的窘迫之间的错位喜剧与深沉孤独。","category":"设定","tags":[],"alwaysInclude":false,"priority":"top"},{"title":"诡秘之主·阿蒙与偷盗者途径","content":"阿蒙是「错误」途径的天使级存在，也是全书塑造最成功的反派之一。偷盗者途径全序列：序列9偷盗者、序列8诈骗师、序列7解密学者、序列6盗火人（可窃取权柄之力）、序列5窃梦家、序列4寄生者、序列3欺瞒导师、序列2命运木马（篡改命运）、序列1时之虫（窃取时间与历史）、序列0错误——阿蒙以此为根基攀升至天使王层次，其「欺诈」与「偷盗」的能力几乎无物不可窃：偷物品、偷能力、偷身份、偷命运，甚至能与目标交换存在。他的标志性手段是「分身」与「扮演」：以无数分身潜伏于历史与现实，冠以不同姓名身份，读者与角色永远无法确定眼前的「某个路人」是否就是阿蒙——他是最早混入克莱恩生活的暗影之一，无数悬疑桥段的元凶。其本质欲望是窃取源堡与灰雾的权柄，向「旧日」位格攀升。要点：写阿蒙只可写其痕迹与后果，不写其全貌；他的可怕不在于战力，而在于「你无法证明你是你」。","category":"人物","tags":[],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘之主·第五纪黑铁纪元时代背景","content":"第五纪称黑铁纪元，即故事发生的「当下」，大体对应十八至十九世纪的蒸汽文明。纪元内分期：初期与战争年代，北大陆诸国在四皇之战遗产上重新洗牌，鲁恩、因蒂斯、弗萨克、伦堡、塞卡玛霍恩等国的边界与教会格局定型；罗塞尔时代是本纪的转折——穿越者罗塞尔·古斯塔夫以因蒂斯为基业推动工业与神秘学的双重革命，留下用汉字写就、无人能解的罗塞尔日记，其死因成为百年悬案；随后是贝克兰德为代表的雾都时代：煤气灯、地铁、蒸汽机械与报纸舆论并存，人口爆炸、雾霭蔽日，非死者与非凡事件的隐秘管理成为七神教会的日常。时代规则：教会以封印物分级（0至3级）管理危险物品；非凡者的人数被严格控制，序列5以上即半神，视作战略威慑；列国博弈在大战（克莱恩时代的世界战争）中总爆发，皇后与半神登台。要点：黑铁纪元的质感是「蒸汽与神秘共生」——写场景先写雾、灯、报纸与绅士礼帽，再让非凡者在其中侧身而行。","category":"年表","tags":[],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘之主·第五纪日常与物价（雾都生活考）","content":"贝克兰德的日常是被煤烟熏黑的：东区贫民窟一家四口挤一间屋，一周工钱约十苏勒上下，黑面包一便士一条，劣质茶几便士一磅；中产住西区砖房，有女仆与壁炉，一顿正餐有肉有汤；报纸三便士一份，地铁与公共马车按里程计费，煤气灯每晚由点灯人逐盏点亮。营生：工厂工、码头搬运、裁缝、洗衣妇、报童、店主、公务员；非凡者另有门路——值夜者、代罚者、机械之心的雇佣，但都隐在教会与组织的幕布之后。主持要点：物价随时间（贝克兰德大雾霾前后）与地区（鲁恩/因蒂斯/弗萨克）浮动；写日常要让「非凡」从生活的缝隙里渗出来——邻居忽然不见了、报纸角落的诡异讣告、当铺里多出一件不该存在的封印物。日常越扎实，恐怖越有重量。","category":"设定","tags":["日常","市井","物价","雾都"],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘之主·源质与唯一性全谱","content":"诡秘体系顶层的硬骨架：最初造物主分裂出九大源质（混沌海、源堡、永暗之河、灾祸之城、知识荒野、光之钥等，合计九种），二十二条神之途径在地球聚拢，每一条途径对应一份源质与序列0唯一性；序列0真神需集齐对应途径的唯一性加三份序列1非凡特性方能登临，且同途径同一时间只能存在一位序列0，故同途径高位强者必然敌对、互相猎杀收割特性。源堡对应占卜家途径（序列0愚者），永暗之河对应黑夜途径（序列0黑暗），其余源质各归其途径。铁律：源质是唯一性的容器，唯一性聚合本能驱动同途径高层次互相靠近甚至吞噬——这正是高序列博弈与旧日之争的根。主持要点：源质与唯一性在凡人视角阶段只作传闻与档案残页，逐段投放，严禁提前解谜。","category":"设定","tags":["源质","唯一性","序列0","九大源质"],"alwaysInclude":false,"priority":"top"},{"title":"诡秘之主·非凡特性聚合定律","content":"除守恒与不灭外，非凡特性另有一条聚合定律：同一条途径的非凡特性会无意识地向高位存在（序列1及以上、持唯一性者）聚合靠拢，表现为低序列者莫名被吸引至高位者身边、同途径强者天然敌对、持唯一性者身边不断汇集同途径特性——这是同途径只能有一位序列0的动力学原因，也是高序列猎杀低序列收割材料的隐性引力。聚合的后果：被盯上的低序列往往死于巧合（高位者路过、随手清理、或特性被强行抽取）；反之，低序列借助高位者庇护可加速消化。主持要点：写高序列博弈时，聚合定律是无形的手——不要写高位者专门追杀某人，而要写特性自己流向他，偶然与必然在此合一；玩家若为低序列，靠近高位既是机遇也是绞索。","category":"规则","tags":["聚合定律","唯一性","高序列","猎杀"],"alwaysInclude":false,"priority":"top"},{"title":"诡秘之主·黑市与魔药走私网络","content":"第五纪台面下的经济暗流：廷根仓库区、贝克兰德索伦区后巷皆有黑市，流通残缺魔药配方、非凡生物制品（眼珠、血肉）、被诅咒的传家物与封印物碎片；走私线连接码头、殖民航线与隐秘组织，价格高昂且真伪难辨——一条情报几便士到几镑，一份低序列配方可抵平民数年工钱。黑市规矩：匿名、现款、不追问来历，买错货比买贵货更致命；心理炼金会、极光会长期在黑市物色实验体与材料。主持要点：写黑市先写灯下黑——最危险的东西藏在最平常的巷子里，卖报童、当铺老板、酒馆醉汉都可能是节点；玩家交易要算清来源与代价，一件来路不明的宝物往往引来原主的追杀。","category":"设定","tags":["黑市","魔药","走私","封印物"],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘之主·报纸舆论与雾都市井","content":"第五纪黑铁纪元的市井靠报纸与舆论运转：便士报、晚报、号外是信息主渠道，报社与报童构成城市神经，一则讣告、一条地铁事故、一篇影射皇室的专栏，都是雾都的日常与暗战；舆论本身是被各方势力争夺的武器——教会、隐秘组织、王室皆通过报纸放风、污名化对手、掩盖非凡事件（把异常写成事故、把失踪写成搬家）。市井质感：煤气灯、点灯人、马拉轨道车、酒馆与剧院、海德公园散步，报童的号外声是雾都的背景音。主持要点：写舆论先写谁在发声——同一件事，教会版、平民版、黑市版各不相同；报纸角落的诡异讣告与异常天气报道，是玩家嗅到非凡的最佳入口，让非凡从生活缝隙里渗出来。","category":"设定","tags":["报纸","舆论","雾都","市井"],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘·夏洛克·莫里亚蒂","content":"克莱恩·莫雷蒂在贝克兰德使用的侦探身份，塔罗会之外最广为人面的伪装之一。以落魄绅士、私家侦探的面目活动于贝克街一带，借黑荆棘安保的旧人脉与塔罗会资源查案、猎魔药线索。该身份沉稳细致、推理缜密，是克莱恩「苟」字诀的集大成者——以凡人之智周旋于非凡漩涡。后于贝克兰德大雾霾等事件中积累声望，又在化名轮换中被克莱恩逐步弃用。此身份承载他与休·迪尔查、佛尔思等人的初遇，是读者认识「贝克街侦探」的起点。","category":"人物","tags":["克莱恩","夏洛克","侦探身份","贝克兰德"],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘·格尔曼·斯帕罗","content":"克莱恩出海远行时使用的猎人身份，以偏执、冷酷、迷信且极度谨慎的海上赏金猎者面目示人。该身份常戴礼帽与金边眼镜，随身携带左轮与符咒，信奉「先下手为强、能跑绝不刚」，遇神弃之地怪物、海盗与半神皆以诡诈脱身。格尔曼之名令诸多海盗闻风，其背后是秘偶大师级的操纵与灰雾之上的推演。这一身份是克莱恩从「廷根小职员」蜕变为「海上传奇」的桥梁，也是他远离亲友、独自背负秘密的写照。","category":"人物","tags":["克莱恩","格尔曼","猎人身份","出海"],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘·道恩·唐泰斯","content":"克莱恩在贝克兰德上层社交圈使用的富商身份，以乐善好施、出手阔绰的南大陆归国富翁面目活动于皇后区沙龙。该身份用于接近贵族、教会高层与隐秘组织，借慈善与收藏之名搜集魔药配方与封印物情报，并暗中庇护塔罗会成员。道恩·唐泰斯富而低调、礼数周全，是克莱恩「体面人」面具的极致，与格尔曼·斯帕罗的亡命形成鲜明对照，体现他在不同阶层间自如切换的伪装天赋。","category":"人物","tags":["克莱恩","道恩","富商身份","沙龙"],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘·梅林·赫尔墨斯","content":"克莱恩在贝克兰德以「魔术师」为名的公开非凡者身份，借表演魔术之便合理化其戏法般的占卜家能力。该身份游走于市井与神秘学圈，以滑稽、神秘的气质吸引关注又保持距离，常与佛尔思·沃尔等圈内人互动。梅林之名呼应古老神秘学家赫尔墨斯，是克莱恩向更高序列「魔术师」晋升时的公开掩护，亦是其「在未知面前保持幽默」这一愚者神格底色的外显。","category":"人物","tags":["克莱恩","梅林","魔术师身份","伪装"],"alwaysInclude":false,"priority":"medium"},{"title":"班森·莫雷蒂","content":"克莱恩·莫雷蒂的兄长，莫雷蒂家的长子。性格开朗、有担当，在父亲早逝后承担养家责任，于贝克兰德谋得公司文员职位，后逐步晋升。他是克莱恩穿越后最先维系的家庭羁绊之一，与妹妹梅丽莎共同构成主角「平凡而珍贵」的凡人锚点。班森不通非凡，却以兄长的朴素关怀为克莱恩提供回归日常的港湾；其求职、升迁与婚恋线是黑铁纪元普通职员的典型写照。","category":"人物","tags":["班森","莫雷蒂家","兄长","凡人锚点"],"alwaysInclude":false,"priority":"medium"},{"title":"梅丽莎·莫雷蒂","content":"克莱恩·莫雷蒂的妹妹，莫雷蒂家的幼女，聪慧节俭、务实要强，于技工学校就读，痴迷机械与蒸汽技术，是典型黑铁纪元新女性。她对兄长的关怀笨拙而真挚，是克莱恩人性锚的重要一角。梅丽莎不通非凡之事，却以对技术与生活的认真，映照出平凡人在蒸汽文明中的尊严；其成长与独立也是主角身后「要守护的日常」的象征。","category":"人物","tags":["梅丽莎","莫雷蒂家","妹妹","机械"],"alwaysInclude":false,"priority":"medium"},{"title":"佛尔思·沃尔（魔术师）","content":"塔罗会「魔术师」号牌，贝克兰德女作家、神秘学爱好者，与休·迪尔查同居，走门途径相关的占卜家侧或学徒侧非凡线。她文风跳脱、脑洞清奇，以写作为生却屡被非凡事件缠身，是塔罗会中最具喜剧色彩的一员。佛尔思借灰雾交流突破创作瓶颈与生存困境，其「作家」式的想象力恰与空想家途径遥相呼应，是愚者信仰中「平凡而幸运」的样本。","category":"人物","tags":["佛尔思","魔术师","作家","塔罗会"],"alwaysInclude":false,"priority":"medium"},{"title":"埃姆林·怀特（月亮）","content":"塔罗会「月亮」号牌，被强制转化的吸血鬼（血族），异种途径非凡者，原服务于血族内部势力，后被克莱恩纳入灰雾。他虚荣、啰嗦却心软，执着于血族荣耀与自身血统，是塔罗会中最具「活着的普通人」质感的成员。埃姆林以月亮之名联结血族秘辛与异种途径知识，其成长折射出非人种族在诸神棋局中的身不由己。","category":"人物","tags":["埃姆林","月亮","吸血鬼","异种途径"],"alwaysInclude":false,"priority":"medium"},{"title":"嘉德丽雅（星星）","content":"塔罗会「星星」号牌，神秘学组织「隐者」的领袖，强大非凡者，原为罗塞尔大帝之女贝尔纳黛的部下与学生，走窥秘人/隐者途径。她博学冷峻、经验老到，统御海上神秘学网络，是塔罗会中实力最深厚者之一。嘉德丽雅以星星之名为克莱恩提供远洋与隐秘组织情报，其背后牵连贝尔纳黛与罗塞尔日记的千年谜团。","category":"人物","tags":["嘉德丽雅","星星","隐者","贝尔纳黛"],"alwaysInclude":false,"priority":"medium"},{"title":"蕾妮特·提尼科尔","content":"灵界生物、位格极高的信使灵体，原为嘉德丽雅的契约信使，后长期服务于克莱恩（以一枚枚金币与头颅为酬）。她缺失头颅、以四个捧头婴儿形象出现，语声重叠诡异，却忠诚可靠，能在灵界穿行传递物品与情报。蕾妮特是克莱恩海上与灰雾之外最重要的联络纽带，其来历牵涉古老死灵秘辛，是全书最令人心悸又安心的存在。","category":"人物","tags":["蕾妮特","信使","灵界","灵体"],"alwaysInclude":false,"priority":"medium"},{"title":"戴莉·西蒙妮","content":"廷根市值夜者，收尸人途径安魂师层次（序列6），美艳成熟，与队长邓恩·史密斯情愫深厚。她灵性敏锐、作风大胆，在真实造物主事件后幸存并继续于教会效力。戴莉代表值夜者中「与死亡共舞却热爱生命」的一类，其与邓恩、伦纳德的羁绊，是廷根小队人情味的核心来源。","category":"人物","tags":["戴莉","值夜者","收尸人","廷根"],"alwaysInclude":false,"priority":"medium"},{"title":"罗尔丹（Seal）","content":"廷根市值夜者队员，沉默可靠的战斗担当，黑夜途径非凡者，常与邓恩、克莱恩等人搭档出警。他话少、执行力强，是队伍中稳定的力量支点。在真实造物主降临事件中，罗尔丹与多名同袍一同殉职，其沉默的牺牲印证了值夜者「无名守望」的宿命，是廷根小队群像中不可或缺的暗色注脚。","category":"人物","tags":["罗尔丹","值夜者","廷根","战斗担当"],"alwaysInclude":false,"priority":"low"},{"title":"娜娅","content":"廷根市值夜者队员，在故事开篇的转运仪式意外中罹难的非凡者。她的死是克莱恩穿越后直面「非凡即危险」的第一课，也揭开了安提哥努斯家族笔记与源堡觉醒的序幕。娜娅戏份虽短，却是全书悲剧感的先声——无名者在禁忌边缘的脆弱，正是诡秘世界冷酷法则的缩影。","category":"人物","tags":["娜娅","值夜者","廷根","开篇"],"alwaysInclude":false,"priority":"low"},{"title":"韦尔奇·麦格文","content":"克莱恩在廷根大学时期的同学，将一本来历不明的安提哥努斯家族笔记带入克莱恩住所，间接诱发了那场导致克莱恩（周明瑞）穿越与源堡觉醒的转运仪式。韦尔奇本人并不通非凡，只是被笔记吸引的凡人，其轻率之举成为搅动整个世界的蝴蝶翅膀。他是「普通人偶然触及禁忌」的典型，也是全书因果链条最初的一环。","category":"人物","tags":["韦尔奇","同学","安提哥努斯笔记","穿越诱因"],"alwaysInclude":false,"priority":"medium"},{"title":"圣堂·斯诺","content":"廷根市值夜者成员之一，在真实造物主降临事件中随小队一同殉职的普通队员。其名载于黑荆棘安保公司与教会牺牲者名录，是廷根小队之殇中被铭记的众多无名守望者之一。圣堂·斯诺的存在提醒读者：值夜者的牺牲从不是主角独享的悲壮，而是一整支队伍共同扛下的黑暗宿命。","category":"人物","tags":["圣堂斯诺","值夜者","廷根","殉职"],"alwaysInclude":false,"priority":"low"},{"title":"特莉丝·奇克","content":"魔女教派成员，原初魔女途径非凡者，本为男性经由魔女途径转化为女性，与罗塞尔大帝及贝尔纳黛一脉有深切纠葛。她曾卷入魔女教派对鲁恩王室的渗透，是贝克兰德上层隐秘网络的一环。特莉丝的命运折射出魔女途径「以性别转换换取力量」的残酷本质，也是罗塞尔日记中那段被刻意隐去的情感旧账的当事人。","category":"人物","tags":["特莉丝","魔女教派","原初魔女","罗塞尔"],"alwaysInclude":false,"priority":"medium"},{"title":"乔治娜","content":"魔女教派高层、原初魔女途径高位非凡者，以鲁恩贵族女子「乔治娜」身份活动，深度参与贝克兰德大雾霾等上层阴谋，是魔女教派与王室、极光会联手祸乱的推手之一。她美艳危险、心思深邃，代表魔女途径「以美色与阴谋编织权柄」的侧面。乔治娜与克莱恩多次博弈，是雾都浮华之下深渊意志的具象。","category":"人物","tags":["乔治娜","魔女教派","原初魔女","贝克兰德"],"alwaysInclude":false,"priority":"medium"},{"title":"魔女教派（原初魔女途径组织）","content":"信奉原初魔女（魔女途径旧日）的隐秘组织，以女性化身为核心，成员多经刺客→魔女途径转化，擅长美色、阴谋与诅咒。教派渗透各国上层，与王室、极光会时有勾结，是贝克兰德大雾霾等惨案的幕后黑手之一。魔女教派体现「力量以代价换取」的诡秘铁律——序列转换伴随性别与人格的根本改写，其高位者皆是被旧日意志浸染的危险存在。","category":"人物","tags":["魔女教派","原初魔女","隐秘组织","阴谋"],"alwaysInclude":false,"priority":"medium"},{"title":"乌洛琉斯","content":"阿蒙的孪生兄弟，同为远古太阳神（负光明神）神子，错误途径的高序列天使（序列1层次）。他曾作为真实造物主阵营的重要战力，以命运与时间的诡秘能力著称，与阿蒙既同源又博弈。乌洛琉斯的存在揭示「神子」一脉在诸神棋局中的复杂站位——既是旧日复苏的钥匙，也是彼此猎杀的对手。","category":"人物","tags":["乌洛琉斯","阿蒙之弟","错误途径","神子"],"alwaysInclude":false,"priority":"medium"},{"title":"梅迪奇","content":"红祭司途径序列1天使，远古太阳神麾下的「战争」天使之王，于第三纪弑神后陨落，化为不灭恶灵依附他人。他效忠真实造物主阵营，冷酷好战、精通战争与杀戮规则，是克莱恩等高序列博弈中的凶险敌手。梅迪奇的「死而不灭」折射出天使之王在神战中的悲惨宿命，也是红祭司权柄在后世的残响。","category":"人物","tags":["梅迪奇","战争天使","红祭司","恶灵"],"alwaysInclude":false,"priority":"medium"},{"title":"萨斯利尔","content":"远古太阳神的「暗天使」，首席天使之王，倒吊人途径序列1。第三纪弑神后他守护神弃之地与混沌海封印，是连接远古太阳神遗骸与后世棋局的关键守卫。萨斯利尔位格极高、沉默如渊，其存在标示着倒吊人途径的顶层权柄，也是神弃之地疯狂低语背后的秩序残留。","category":"人物","tags":["萨斯利尔","暗天使","倒吊人途径","神弃之地"],"alwaysInclude":false,"priority":"medium"},{"title":"科林·伊利亚特","content":"神弃之地白银城 chief（城主），猎人途径半神（铁血骑士及以上），戴里克·伯格的导师与精神领袖。他数千年来带领白银城遗民在城墙内抵御怪物与疯狂低语，矢志寻找走出神弃之地的生路。科林代表绝境中不退缩的「猎手」意志，是人类遗民在诸神遗弃之地坚守文明的象征。","category":"人物","tags":["科林","白银城","猎人途径","神弃之地"],"alwaysInclude":false,"priority":"medium"},{"title":"洛薇雅","content":"神弃之地白银城的高序列非凡者（收尸人／死灵途径半神），城中最强战力之一，却暗中信奉真实造物主，是埋藏于白银城内部的隐患。她复杂而矛盾，既守护城池又伺机推动邪神意志。洛薇雅折射出神弃之地被污染现实的深层撕裂——连最可信的守护者亦可能是伪神的耳目。","category":"人物","tags":["洛薇雅","白银城","死灵途径","真实造物主"],"alwaysInclude":false,"priority":"low"},{"title":"赫尔墨斯","content":"远古空想家途径序列1「作家」层次的半神，神秘学体系的奠基者之一，确立了二十二途径与序列命名的框架（包括占卜家途径各序列之名）。他创立以自身为名的神秘学传承，影响后世诸多组织。赫尔墨斯代表「以空想与命名秩序化超凡」的智识传统，是连接古代神秘学与第五纪知识的桥梁人物。","category":"人物","tags":["赫尔墨斯","空想家","神秘学","序列命名"],"alwaysInclude":false,"priority":"medium"},{"title":"查拉图","content":"空想家途径序列1天使，心理炼金会的幕后支柱与操盘者，精于以空想与心智布局操纵现实。他深沉诡谲，是亚当棋局之外另一股以「人心」为棋的暗势力，曾对克莱恩构成严重威胁。查拉图体现空想家途径「织梦成真、以念改实」的顶端能力，也警示高位空想者对人性锚的极度渴求。","category":"人物","tags":["查拉图","空想家","心理炼金会","布局"],"alwaysInclude":false,"priority":"medium"},{"title":"安德森·胡德","content":"猎人途径半神，绰号「倒霉」的海上冒险家与赏金猎人，于克莱恩出海期间结伴同行。他毒舌、自恋却身手不凡，屡屡在绝境中逢凶化「险」，是海上线的喜剧担当与可靠战力。安德森代表猎人途径「追踪、埋伏、猎杀」的野性智慧，也以旁观者视角映照克莱恩「格尔曼」面具下的孤独。","category":"人物","tags":["安德森","猎人途径","冒险家","出海"],"alwaysInclude":false,"priority":"low"},{"title":"卡维图瓦","content":"罗思德群岛原住民信奉的「海神」，实为非凡生物／灵界存在，与暴君途径及海洋权柄相关，被殖民者与教会长期压制利用。它借土著信仰汇聚力量，是克莱恩出海阶段遭遇的重要灵界势力。卡维图瓦揭示「被殖民者崇拜的本土神祇」往往只是更高存在的投影，是南大陆秩序脆弱性的缩影。","category":"人物","tags":["卡维图瓦","海神","罗思德群岛","灵界"],"alwaysInclude":false,"priority":"low"},{"title":"齐林格斯","content":"海上海盗将军之一，错误途径序列4「寄生者」层次的非凡者，以寄生与窃取能力著称，曾持有高危封印物。他是克莱恩（格尔曼·斯帕罗）海上猎杀的对象之一，代表错误途径「窃物窃身」的诡谲战法。齐林格斯的败亡印证了阿蒙一脉能力在凡人手中的危险与局限。","category":"人物","tags":["齐林格斯","海盗将军","错误途径","寄生者"],"alwaysInclude":false,"priority":"low"},{"title":"塞尼奥尔","content":"海上海盗将军之一，以灵体化与法师类能力见长的半神级非凡者，纵横苏尼亚海。他与齐林格斯等并称大海盗，是克莱恩出海阶段的重要对手与素材来源。塞尼奥尔体现海上非凡者「以舰炮与灵体并重」的混合作战风格，其存在勾勒出殖民航线之上的法外秩序。","category":"人物","tags":["塞尼奥尔","海盗将军","灵体","苏尼亚海"],"alwaysInclude":false,"priority":"low"},{"title":"艾尔·蒂奇","content":"海上海盗将军之一，血族／异种途径高位非凡者，号「血之上将」，以嗜血与再生能力令航海者闻风。他是南大陆与殖民海域法外秩序的象征性人物，也是克莱恩海上征途的敌手之一。艾尔·蒂奇折射出异种途径「以血与暴食换取力量」的残酷本质，以及海盗世界的丛林法则。","category":"人物","tags":["艾尔蒂奇","血之上将","异种途径","海盗"],"alwaysInclude":false,"priority":"low"},{"title":"弗兰克·李","content":"海上非凡者，母亲途径半神，以培育与操控植物、真菌类生物见长，绰号与「植物」相关，是海上少见的另类强者。他痴迷于以生命改造世界，曾与克莱恩合作又保持距离。弗兰克体现母亲途径「孕育、生长、寄生」的生命法则，也以荒诞的科研狂热映照诡秘世界的奇异多样性。","category":"人物","tags":["弗兰克李","母亲途径","植物","半神"],"alwaysInclude":false,"priority":"low"},{"title":"奥古斯都家族","content":"鲁恩王国的统治王族，与战神教会深度绑定，世代走战士／战神相关途径以巩固王权。家族成员多具军人气质与尚武传统，是北大陆最强世俗权力之一。奥古斯都家族与索伦、卡斯蒂亚等家族共同塑造了第五纪列强格局，其王权与神权的微妙博弈贯穿全书政治暗线。","category":"人物","tags":["奥古斯都","鲁恩王族","战神","世俗权力"],"alwaysInclude":false,"priority":"medium"},{"title":"索伦家族","content":"因蒂斯王国（后帝国）的王族，与永恒烈阳教会结盟，曾参与刺杀罗塞尔大帝的弑帝阴谋。索伦家族是南大陆强国因蒂斯的政治核心，与鲁恩的奥古斯都家族长期对峙。其名号承载罗塞尔时代之后的因蒂斯国运，也是第五纪列强教派政治的关键棋子。","category":"人物","tags":["索伦","因蒂斯王族","永恒烈阳","弑帝"],"alwaysInclude":false,"priority":"medium"},{"title":"心理炼金会","content":"隐秘组织，以空想家途径序列1查拉图为幕后支柱，由古代神秘学家赫尔墨斯一脉演化而来。会员多出身贵族沙龙与学界，热衷人体实验与心智操纵研究，是贝克兰德上层隐秘网络的危险策源地。心理炼金会体现「以理智探求超凡却滑向疯狂」的悖论，后期在塔罗会布局下逐步被策反瓦解。","category":"人物","tags":["心理炼金会","空想家","人体实验","隐秘组织"],"alwaysInclude":false,"priority":"medium"},{"title":"玫瑰学派与灵教团","content":"围绕异种／死灵途径运转的隐秘结社，与血族、死神遗脉及被缚之神信仰牵连，分支林立、诉求各异。其中以卡特琳娜·佩莱为首的派系擅长死灵与寄生类秘术，长期在黑市与殖民地活动。玫瑰学派与灵教团代表「被正神秩序排斥的超凡血脉」的抱团，是南大陆与神弃之地暗流的重要一环。","category":"人物","tags":["玫瑰学派","灵教团","异种","死灵"],"alwaysInclude":false,"priority":"medium"},{"title":"摩斯苦修会","content":"摩斯苦修会是历史悠久的苦修型隐秘结社，与工匠之神（蒸汽与机械之神）渊源深厚，其创建者之一即第四纪登临神位的工匠斯蒂亚诺。会众以苦修、禁欲与技艺磨炼自身，兼具信仰与神秘学传承。规则要点：摩斯苦修会属半独立结社，亦正亦邪，与教会的技艺传承有交集；其苦修气质区别于极光会等疯狂异端。主持要点：写摩斯苦修会突出「以苦行换权柄」的肃穆与工匠世家的手艺感。","category":"势力","tags":["摩斯苦修会","工匠之神","苦修","结社"],"alwaysInclude":false,"priority":"medium"},{"title":"生命学派","content":"围绕母亲途径运转的神秘学学术结社，研习生命、孕育与滋养之道，亦正亦邪，与玫瑰学派、教会皆有纠葛。学派重视知识与传承，常以学者面目活动于大学与殖民地。生命学派体现母亲途径「生长与丰饶」的温和侧面，也是第五纪民间超凡学术网络的代表。","category":"人物","tags":["生命学派","母亲途径","学术结社","神秘学"],"alwaysInclude":false,"priority":"low"},{"title":"莎伦夫人","content":"收尸人／死灵途径半神，伦纳德·米切尔的旧情人与精神羁绊，统御一张以风月场所为掩护的情报网络。她深沉、危险又对伦纳德留有真情，在廷根及后续事件中数次牵动官方与隐秘势力的平衡。莎伦夫人代表收尸人途径「与亡灵和秘密共舞」的暗面，也是伦纳德身世谜团的重要拼图。","category":"人物","tags":["莎伦夫人","收尸人","伦纳德","情报网络"],"alwaysInclude":false,"priority":"medium"},{"title":"卡特琳娜·佩莱","content":"玫瑰学派／灵教团的重要领袖，死灵途径高位非凡者，以寄生与亡灵秘术著称，统领一派在南大陆与黑市活动的势力。她野心勃勃、手段狠辣，是克莱恩涉足死灵线索时的强敌之一。卡特琳娜折射出非正神阵营中「以血脉与秘术自立」的生存逻辑，也是异种／死灵途径政治的典型代表。","category":"人物","tags":["卡特琳娜","玫瑰学派","死灵途径","灵教团"],"alwaysInclude":false,"priority":"low"},{"title":"霍尔伯爵","content":"贝克兰德贵族，奥黛丽·霍尔之父，家世显赫、跻身皇后区沙龙核心。他代表鲁恩上层「体面而脆弱」的世俗权力，对女儿涉足神秘学懵然不知。霍尔家族是奥黛丽观众之道展开的舞台，也是塔罗会「正义」得以俯瞰雾都权贵圈的窗口，映照出非凡暗流在贵族日常下的潜伏。","category":"人物","tags":["霍尔伯爵","贵族","奥黛丽之父","贝克兰德"],"alwaysInclude":false,"priority":"low"},{"title":"堕落母神（外神）","content":"来自星空的旧日级外神，母亲途径的序列0，最初造物主第二日所诞之「堕落」人格。她象征繁衍、扭曲与寄生，是地球屏障外最危险的入侵者之一，借母亲途径渗透现世。堕落母神代表「不可名状的星空污染」的具象，其注视即污染，是终局外神入侵大阴谋的核心威胁。","category":"人物","tags":["堕落母神","外神","母亲途径","星空"],"alwaysInclude":false,"priority":"medium"},{"title":"原初魔女（旧日）","content":"魔女途径的序列0旧日，魔女教派信奉的终极存在，象征诱惑、变形与不灭。她以女性化身与扭曲之美为标志，是刺客→魔女途径顶端权柄的执掌者。原初魔女体现「以性别与人格的彻底改写换取神性」的诡异本质，其意志浸染教派高位者，是雾都上层阴谋的幕后旧日阴影。","category":"人物","tags":["原初魔女","魔女途径","旧日","变形"],"alwaysInclude":false,"priority":"medium"},{"title":"被缚之神（旧日）","content":"异种途径的序列0旧日，与吸血鬼、异种血脉渊源深厚，曾被束缚或封印于特定领域。他是血族始祖莉莉丝一脉的更高位存在，象征束缚、渴血与异变。被缚之神的遗脉构成玫瑰学派与灵教团等组织的信仰根基，也是南大陆非正神超凡血脉的终极依归。","category":"人物","tags":["被缚之神","异种途径","旧日","血族"],"alwaysInclude":false,"priority":"low"},{"title":"空想之龙（古神）","content":"第二纪古神之一，知识与智慧之神赫拉伯根的前身主宰，象征空想、知识与龙族权柄。它统御精灵与龙类阵营，于古神时代强盛一时，其遗产深刻影响白塔途径与后世神秘学。空想之龙是「历史由胜利者书写」主题的样本，其陨落与知识传承的断裂，是第二纪黑暗纪元旧账的一环。","category":"人物","tags":["空想之龙","古神","白塔","知识"],"alwaysInclude":false,"priority":"medium"},{"title":"毁灭魔狼（古神）","content":"第二纪古神之一，巨狼形态的灭世存在，黑夜女神阿曼妮西斯（厄运女神）曾为其从神。它象征毁灭与黑暗，是泛人类阵营抵御的非人古神代表。毁灭魔狼的陨落促成黑夜权柄的转移，也标志着古神时代向诸神时代的过渡，是理解黑夜女神来历的关键旧账。","category":"人物","tags":["毁灭魔狼","古神","黑夜女神","第二纪"],"alwaysInclude":false,"priority":"medium"},{"title":"巨人王（古神）","content":"第二纪古神，巨人种族之主，统御火之初耀与双生年代的巨人阵营，战神巴德海尔与大地母神皆曾为其从神。巨人王因背叛与交恶而衰落，其遗产（巨人王庭）成为神弃之地高位非凡者的猎场。巨人王代表古神时代「种族即神权」的秩序，其兴衰是第二纪阵营旧账的核心。","category":"人物","tags":["巨人王","古神","巨人","神弃之地"],"alwaysInclude":false,"priority":"medium"},{"title":"精灵王（古神）","content":"第二纪古神，精灵种族之主，空想之龙阵营的重要盟友，于双生年代后期与巨人王交恶。精灵王象征海洋、风与精灵权柄，其文明辉煌而短命。精灵王一脉的遗产与第三纪之后被抹去的历史相关，是白银城保存的被隐瞒真相中反复出现的古神身影。","category":"人物","tags":["精灵王","古神","精灵","第二纪"],"alwaysInclude":false,"priority":"low"},{"title":"血族始祖莉莉丝","content":"第二纪古神，异种／吸血鬼途径序列0，血族与异种血脉的始祖，象征异变、渴血与不朽。她与月之权柄渊源深厚，是埃姆林等吸血鬼一脉的终极源头，亦关联被缚之神。莉莉丝代表「非人种族亦可成神」的古神旧秩序，其遗脉在第五纪仍是隐秘组织争夺的宝藏。","category":"人物","tags":["莉莉丝","血族始祖","异种途径","古神"],"alwaysInclude":false,"priority":"medium"},{"title":"死神（古神）","content":"第二、三纪之交的古神，死灵途径序列0，建立拜朗等死神信仰文明，掌死亡、亡灵与门户权柄。他陨落后其特性与遗骸成为后世死灵途径非凡者争夺的核心，阿兹克·艾格斯的信使宿命即源于此。死神代表「死亡亦有秩序」的古老法则，其遗留是神弃之地与南大陆一切死灵秘辛的总根。","category":"人物","tags":["死神","古神","死灵途径","拜朗"],"alwaysInclude":false,"priority":"medium"},{"title":"风天使列奥德罗（风暴之主本源）","content":"远古太阳神麾下的「风」天使之王，第三纪弑神后分食神躯晋升为风暴之主（暴君途径序列0），尊号空之王、海之皇、天灾君主。他象征风暴、海洋与天灾，是鲁恩之外海上诸国的主要信仰。列奥德罗由天使晋神的过程，是诸神合法性源于弑神这一真相的明证。","category":"人物","tags":["列奥德罗","风天使","风暴之主","暴君"],"alwaysInclude":false,"priority":"medium"},{"title":"纯白天使奥赛库斯（永恒烈阳本源）","content":"远古太阳神麾下的「纯白」天使之王，第三纪弑神后分食神躯晋升为永恒烈阳（太阳途径序列0），尊号永恒烈阳、不灭之光、秩序化身、契约之神。他象征光明、秩序与契约，是商业与律法的守护者。奥赛库斯的晋神同样印证「神以弑神而立」的第三纪真相。","category":"人物","tags":["奥赛库斯","纯白天使","永恒烈阳","太阳"],"alwaysInclude":false,"priority":"medium"},{"title":"智慧之龙赫拉伯根（知识与智慧之神本源）","content":"空想之龙的从神「智慧之龙」，第三纪后晋升为知识与智慧之神（白塔途径序列0），尊号对应白塔。他象征知识、智慧与学术，其教会以图书馆与学院为根基。赫拉伯根由古神从神晋神，体现第二纪古神遗产向第五纪正神的转型，也是白塔途径权柄的当代执掌者。","category":"人物","tags":["赫拉伯根","智慧之龙","知识与智慧之神","白塔"],"alwaysInclude":false,"priority":"medium"},{"title":"克莱恩与乔治娜（博弈宿敌）","content":"克莱恩（经道恩·唐泰斯等身份）与魔女教派高层乔治娜于贝克兰德上层多次博弈。乔治娜代表魔女教派与王室、极光会联手祸乱的阴谋面，克莱恩则以伪装与塔罗会之力周旋、破坏其图谋。二人关系是对等的智斗与试探，映照雾都浮华之下正邪势力借凡人躯体交锋的暗战。","category":"关系","tags":["克莱恩","乔治娜","魔女教派","博弈"],"alwaysInclude":false,"priority":"medium"},{"title":"邓恩与戴莉（同袍恋人）","content":"廷根值夜者队长邓恩·史密斯与队员戴莉·西蒙妮是多年同袍与恋人，彼此以性命相托。邓恩护短到可为戴莉抗命，戴莉则在邓恩殉职后承其遗志继续守望。二人的感情是廷根小队人情味的核心，其生离死别将「值夜者的宿命」这一主题推向最沉重的情感顶点。","category":"关系","tags":["邓恩","戴莉","值夜者","恋人"],"alwaysInclude":false,"priority":"medium"},{"title":"克莱恩与蕾妮特（信使契约）","content":"克莱恩与灵界信使蕾妮特·提尼科尔以金币与头颅为酬缔结长期契约，由她于灵界穿行传递物品与情报。蕾妮特缺失头颅、语声重叠却忠诚可靠，是克莱恩海上与灰雾之外最重要的联络纽带。这一契约关系以「诡异却安心」的质感，成为全书最具辨识度的互助羁绊。","category":"关系","tags":["克莱恩","蕾妮特","信使","契约"],"alwaysInclude":false,"priority":"medium"},{"title":"伦纳德与莎伦夫人（旧情）","content":"伦纳德·米切尔与收尸人半神莎伦夫人曾有深厚旧情，莎伦更因其与0-08的牵连而牵动官方与隐秘势力的平衡。这段关系埋于伦纳德身世谜团深处，既有青春爱恋的残温，也有高位存在操控下的无奈，是收尸人途径暗线与值夜者往事交汇的情感注脚。","category":"关系","tags":["伦纳德","莎伦夫人","旧情","收尸人"],"alwaysInclude":false,"priority":"medium"},{"title":"阿兹克与死神（信使宿命）","content":"阿兹克·艾格斯作为「死神信使」，与死神（死灵途径古神）有深刻而宿命的羁绊：他被死神诅咒而轮回转世、记忆断续，又受托传递死神遗留的权柄与真相。这一关系驱动阿兹克千年追寻自我，也令死灵途径的高位秘密借他之手逐步揭开，是死神遗产线的核心枢纽。","category":"关系","tags":["阿兹克","死神","信使","死灵途径"],"alwaysInclude":false,"priority":"medium"},{"title":"因斯·赞格威尔与0-08（寄生）","content":"叛徒因斯·赞格威尔以封印物0-08（命运之笔）为工具亦为枷锁：他借其书写命运之力策划廷根惨案、谋求半神晋升，却也被这件高位封印物的意志反噬、命途受其牵引。0-08与持有者的寄生关系是「力量必带代价」的铁律范本，也揭示真实造物主阵营借器物操控棋子的暗线。","category":"关系","tags":["因斯","0-08","寄生","封印物"],"alwaysInclude":false,"priority":"medium"},{"title":"奥黛丽与霍尔家族（贵族千金）","content":"奥黛丽·霍尔是贝克兰德霍尔伯爵之女，以贵族千金的身份与财富为观众之道提供舞台。家族的体面沙龙是她俯瞰雾都权贵圈的窗口，也令她初涉神秘学而不自知危险。这一关系既赋予奥黛丽资源与视野，又构成她「走出温室、成为真正智者」的成长张力。","category":"关系","tags":["奥黛丽","霍尔家族","贵族","观众"],"alwaysInclude":false,"priority":"medium"},{"title":"阿尔杰与风暴教会（出身羁绊）","content":"阿尔杰·威尔逊出身风暴之主教会水手体系，深谙海上教派的等级与规矩，后游走于海盗与教会之间。这一出身既赋予他暴君途径的修行根基与海洋人脉，也令他对教会既利用又提防。阿尔杰与风暴教会的羁绊，是塔罗会「倒吊人」能在海上棋局中游刃的根本。","category":"关系","tags":["阿尔杰","风暴教会","暴君途径","水手"],"alwaysInclude":false,"priority":"medium"},{"title":"戴里克与白银城（逃出的少年）","content":"戴里克·伯格是神弃之地白银城逃出的少年，作为「太阳」被克莱恩拉入塔罗会，成为城内遗民与灰雾之间的桥梁。他既承载白银城对光明的渴望，又以自身证词向塔罗会揭示神弃之地的真相。这一关系令绝境孤城得以借塔罗会之力寻找出路，也是戴里克重建信仰的起点。","category":"关系","tags":["戴里克","白银城","太阳","神弃之地"],"alwaysInclude":false,"priority":"medium"},{"title":"埃姆林与血族（吸血鬼身份）","content":"埃姆林·怀特是被强制转化的吸血鬼，背负血族（异种途径）的血脉荣耀与生存困境。他既渴望血族认同，又因被转化而对自身处境抱有怨怼。这一身份令「月亮」成为塔罗会中连接血族秘辛、异种途径知识与南大陆隐秘势力的节点，也折射非人种族在诸神棋局中的身不由己。","category":"关系","tags":["埃姆林","血族","异种途径","吸血鬼"],"alwaysInclude":false,"priority":"medium"},{"title":"阿蒙与乌洛琉斯（孪生兄弟）","content":"阿蒙与乌洛琉斯是远古太阳神（负光明神）的孪生神子，同为错误途径高位天使，既同源血脉又彼此博弈。乌洛琉斯曾效力真实造物主阵营，与阿蒙在旧日复苏棋局中立场交错。兄弟关系是「神子」一脉内部猎杀与联合的缩影，也是错误途径权柄之争的家族化呈现。","category":"关系","tags":["阿蒙","乌洛琉斯","孪生","错误途径"],"alwaysInclude":false,"priority":"medium"},{"title":"古斯塔夫皇族血脉","content":"古斯塔夫是罗塞尔大帝（黄涛）一脉的姓氏，其女贝尔纳黛承袭穿越者血脉与非凡天赋，于海上以「神秘女王」之姿统御隐者组织。这一血脉因罗塞尔的工业与神秘学双重革命而特殊，既背负父辈未竟真相，也因穿越者渊源而能解读罗塞尔日记、触及源堡相关秘辛。","category":"血脉","tags":["古斯塔夫","罗塞尔","贝尔纳黛","穿越者血脉"],"alwaysInclude":false,"priority":"medium"},{"title":"亚伯拉罕家族（门途径）","content":"亚伯拉罕家族是门途径（学徒途径）的传承世家，先祖为门途径序列1天使「门先生」伯特利·亚伯拉罕。家族因伯特利被星空污染、封印于门后而千年流亡，族人世代受诅咒、被迫散居避祸。亚伯拉罕血脉是门权柄的人间载体，其兴衰直接映射「窥探星空者必受反噬」的铁律。","category":"血脉","tags":["亚伯拉罕","门途径","伯特利","流亡"],"alwaysInclude":false,"priority":"medium"},{"title":"艾格斯家族（死神信使）","content":"艾格斯一脉与死神信使阿兹克绑定，是被死神诅咒、轮回转世的特殊血脉。家族成员承袭死灵途径的高位资质，却也背负记忆断续、一次次死而复生的宿命。艾格斯血脉是死神遗留权柄的人间信使线，其存续本身即是死灵途径与古神遗产纠缠的活标本。","category":"血脉","tags":["艾格斯","死神信使","死灵途径","轮回"],"alwaysInclude":false,"priority":"medium"},{"title":"吸血鬼血脉（血族）","content":"吸血鬼（异种途径）血脉源自血族始祖莉莉丝，以渴血、异变与不朽为特征，经被缚之神一脉延续。埃姆林·怀特等血族承袭此血脉，既获异种途径的非凡资质，也受血族内部等级与生存法则约束。吸血鬼血脉是南大陆与非正神超凡社会中「非人亦可成神」的旧神遗秩序代表。","category":"血脉","tags":["吸血鬼","血族","异种途径","莉莉丝"],"alwaysInclude":false,"priority":"medium"},{"title":"巨人血脉（白银城）","content":"白银城遗民承袭上古巨人王时代残留的血脉特质，城主科林·伊利亚特等走猎人途径并具巨人般的体魄与意志。这一血脉是神弃之地人类在诸神遗弃下，借古神时代遗存艰难存续的证明，也是巨人王庭遗迹权柄在人间最后的呼应。","category":"血脉","tags":["巨人血脉","白银城","猎人途径","神弃之地"],"alwaysInclude":false,"priority":"low"},{"title":"图铎皇族血脉（血皇帝）","content":"图铎是第四纪血皇帝一脉的皇族姓氏，承袭猎人途径（红祭司）的权柄传统。血皇帝图铎因强转途径半疯而陨落，其血脉与荣耀在四皇之战后沦为历史暗影。图铎皇族血脉象征「以战争登顶却为代价反噬」的狂暴神权旧梦。","category":"血脉","tags":["图铎","血皇帝","红祭司","皇族"],"alwaysInclude":false,"priority":"low"},{"title":"所罗门皇族血脉（黑皇帝）","content":"所罗门是第四纪黑皇帝一脉的皇族姓氏，承袭律师途径（黑皇帝）的律法与复活权柄。黑皇帝所罗门两度立国两度陨落，其血脉成为鲁恩、因蒂斯诸国前史的暗线根源，亦是「黑皇帝即将复活」这一千年恐惧的载体。所罗门皇族血脉是律令神权的活化石。","category":"血脉","tags":["所罗门","黑皇帝","律师途径","皇族"],"alwaysInclude":false,"priority":"low"},{"title":"空想之龙血脉","content":"空想之龙一脉是第二纪古神的知识与空想权柄传承，其从神智慧之龙赫拉伯根晋神为知识与智慧之神。这一血脉以「知识即权柄」为内核，影响白塔途径与后世学院、图书馆体系。空想之龙血脉是古神遗产向第五纪正神转型的关键链环。","category":"血脉","tags":["空想之龙","白塔","知识与智慧之神","古神"],"alwaysInclude":false,"priority":"low"},{"title":"奥古斯都王族血脉（鲁恩）","content":"奥古斯都家族是鲁恩王国的统治王族，与战神教会结盟，世代走战士／战神相关途径以巩固王权。其血脉承载着北大陆最强世俗权力，也因乔治三世强转黑皇帝的图谋而卷入神权政治的惊涛。奥古斯都王族血脉是第五纪列强格局的人间支柱。","category":"血脉","tags":["奥古斯都","鲁恩","战神","王族"],"alwaysInclude":false,"priority":"medium"},{"title":"外神位格","content":"外神是来自星空、位格高于旧日的古老存在（如堕落母神），最初造物主曾从其身上撕裂部分用于自身分裂。外神本质为「不可名状的污染源头」——直视或接触即遭侵蚀，窥探星空者必被标记。其位格凌驾于序列体系之上，是地球屏障外的最终威胁，终局入侵大阴谋的核心。","category":"体质","tags":["外神","星空","污染","位格"],"alwaysInclude":false,"priority":"medium"},{"title":"纸人替身（小丑）","content":"小丑（占卜家序列8）的标志天赋：以灵性制作纸人作为替身承受致命伤，配合身体控制与面容微调实现近乎滑稽的闪避与诈死。它是克莱恩「苟」字诀的具象——用戏法般的骗术化解杀机。纸人替身将「侥幸与滑稽是其守护」的小丑神格写进了实战，是中低序列最实用的保命天赋之一。","category":"天赋","tags":["纸人替身","小丑","占卜家","保命"],"alwaysInclude":false,"priority":"medium"},{"title":"灵性丝线（秘偶大师）","content":"秘偶大师（占卜家序列5）的天赋，以灵性丝线操控人偶傀儡、将活人制得为偶，实现远程操纵与分身作战。它是克莱恩从「单体欺诈」迈向「群控棋手」的转折，亦是其「世界」代号掌控力的来源。灵性丝线令持有者能以偶代身、以偶窥探，是诡秘侍者权柄的雏形。","category":"天赋","tags":["灵性丝线","秘偶大师","人偶","操纵"],"alwaysInclude":false,"priority":"medium"},{"title":"门之传送（门途径）","content":"门途径（学徒途径顶端，伯特利一脉）的天赋为空间传送与灵界穿梭——可开「门」瞬移、穿行灵界与星界、连通异地。它是海上与逃亡者的终极机动，却因触及星空而招致外神污染。门之传送的代价警示：自由的门后，往往站着不可名状的注视。","category":"天赋","tags":["门途径","传送","灵界","星空"],"alwaysInclude":false,"priority":"medium"},{"title":"航海风感（水手途径）","content":"水手途径（暴君序列9水手）的天赋为航海亲和、风感预判与水中适应，低位即能御风识浪、海上如履平地，高位可祈唤风浪、主掌天灾。它是阿尔杰等海上者的根基，亦是暴君权柄「海之皇」的雏形。水手天赋写尽海洋文明的生存智慧与敬畏。","category":"天赋","tags":["水手","航海","暴君途径","风感"],"alwaysInclude":false,"priority":"medium"},{"title":"魔女变形（刺客/魔女途径）","content":"刺客→魔女途径的天赋以「变形」为标志：男性非凡者晋升魔女后转化为女性，获得美色、诅咒与阴谋类能力。它是原初魔女权柄的残酷本质——以性别与人格的根本改写为代价换取力量。特莉丝、乔治娜皆为此途，魔女变形折射诡秘世界「力量必带畸变」的铁律。","category":"天赋","tags":["魔女","变形","刺客途径","原初魔女"],"alwaysInclude":false,"priority":"medium"},{"title":"契约律令（律师途径）","content":"律师途径（黑皇帝序列9律师）的天赋为以言辞与契约影响现实——可借律令约束他人行为、制造规则漏洞、以诡辩扭曲事态。它是黑皇帝「以律法支配现实」权柄的雏形，亦是所罗门皇族血脉的力量根基。律师天赋写「话语即枷锁」的诡秘法则，越是讲究程序越显力量。","category":"天赋","tags":["律师","契约","黑皇帝","律令"],"alwaysInclude":false,"priority":"medium"},{"title":"秩序仲裁（仲裁人途径）","content":"仲裁人途径（审判者序列9仲裁人）的天赋为以秩序与规则仲裁现实——可制定局部律法、强制平静、以审判约束敌我。它是夜皇「审判者」权柄的雏形，与律师途径相邻互换。仲裁人天赋写「以律法统御混乱」的秩序美学，亦隐喻神权对世俗的规训。","category":"天赋","tags":["仲裁人","秩序","审判者","夜皇"],"alwaysInclude":false,"priority":"medium"},{"title":"光明颂赞（歌颂者途径）","content":"歌颂者途径（太阳序列9歌颂者）的天赋为以颂赞与光明术见长——低位即能净化、治愈与驱散黑暗，高位可立下不可违背的契约、以烈阳焚尽邪祟。它是永恒烈阳与太阳权柄的民间根基，亦对应太阳途径「光与誓约」的本质。光明颂赞写尽信仰之力的温暖与不可违抗。","category":"天赋","tags":["歌颂者","太阳途径","光明","净化"],"alwaysInclude":false,"priority":"medium"},{"title":"普利兹港","content":"鲁恩王国东海岸的重要港口城市，蒸汽与远洋贸易的节点之一。克莱恩曾在此一带活动，港口常年停泊着往来苏尼亚海与殖民地的商船与客轮。这里既是普通人谋生的码头，也是黑市、走私线与水手非凡者交汇的暗面——出海者在此采购补给、打探航线，隐秘组织也借港口的人流掩藏行迹。主持要点：写普利兹港先写咸腥的海风、蒸汽与帆缆、搬运工的号子，再让非凡从码头仓库与酒馆的阴影里渗出。","category":"地点","tags":["普利兹港","鲁恩","港口","海运"],"alwaysInclude":false,"priority":"medium"},{"title":"圣赛缪尔教堂","content":"贝克兰德城中黑夜女神教会的核心教堂之一，尖顶与彩窗在雾气中肃穆矗立，是值夜者与教区信众的礼拜与公务中枢。教堂地下设有收容封印物的密室与处理非凡事件的设施，高阶神职人员在此主持净化与祷告。它既是信仰的灯塔，也是官方非凡力量的据点——异常事件的汇报、封印物的存放、值夜者的调度常在此交汇。主持要点：写教堂戏要写出石壁的冷、蜡与香的气味、神像注视下的压迫感，以及信仰与职责交织的庄重。","category":"地点","tags":["圣赛缪尔","黑夜女神","教堂","贝克兰德"],"alwaysInclude":false,"priority":"medium"},{"title":"黑荆棘安保公司","content":"廷根市一处不起眼的安保公司门面，实则是黑夜女神教会值夜者小队的公开掩护据点。公司内部分布着伪装成办公室的作战室、档案间与祈祷室，值夜者以文职、保安等身份挂职其间，处理灵异案件与失控者事件。黑荆棘的木质招牌与阴郁氛围是廷根小队日常的底色，克莱恩正是在此处完成从普通人到非凡者的转变。主持要点：写此处突出'平凡门面下的机密'——茶水间里的闲谈与档案柜后的真相只有一墙之隔。","category":"地点","tags":["黑荆棘","值夜者","廷根","掩护据点"],"alwaysInclude":false,"priority":"medium"},{"title":"星界","content":"与现实、灵界并列的更高层存在之海，是真神与星灵体的居所。星界之上悬有被旧日占据的诸行星与绯红之月，是占星与窥秘类非凡者感应命运与远方的源头。它既远又近，直视星空会招致污染，占星者皆受训规避星空的注视。星界与灵界、现实三层世界彼此联动，是终局层面阴谋的纵深背景。主持要点：星界只宜作为远景与污染源头出现，一旦具象登场须保持'不可名状'的克制笔法。","category":"地图","tags":["星界","真神居所","星空","占星"],"alwaysInclude":false,"priority":"medium"},{"title":"绯红之月","content":"悬于夜空的红色月亮，是黑夜女神权柄的象征之一，也是诡秘世界夜空的异常天象。红月常被非凡者用作仪式的时间坐标与力量的隐喻，月亮的盈亏与颜色变化往往预示着非凡层面的扰动。它既是诗意的背景，也是神秘学意义上的'注视'——某些存在借由月光投下影响。主持要点：写红月不写其科学解释，只写它如何为雾都的夜晚染上不祥的暖红，以及非凡者对它的本能忌惮。","category":"地点","tags":["绯红之月","红月","黑夜女神","天象"],"alwaysInclude":false,"priority":"low"},{"title":"红剧场","content":"贝克兰德城中的一处剧院，曾是魔女教派相关人物特莉丝栖身与活动的场所，表面歌舞升平，暗里交织着魔女途径非凡者与隐秘组织的纠葛。剧场后台与包厢是情报交换与隐秘仪式的温床，雾都的浮华与深渊在此一体两面。主持要点：写红剧场写出幕布后的另一种戏——台上是表演，台下是交易与谋算；它是贝克兰德非凡暗网的缩影，也是玩家触碰魔女教派边缘的入口。","category":"地点","tags":["红剧场","贝克兰德","魔女教派","剧院"],"alwaysInclude":false,"priority":"low"},{"title":"弗萨克帝国","content":"北大陆北部的强国，皇室为艾因霍恩家族，国民多带巨人血脉，身材高大、民风剽悍，信奉战神。首都为圣密隆。弗萨克以军事力量与尚武传统闻名，与鲁恩长期对峙，是世界大战中的主要参战国之一。其战神教会拥有\"猎魔者\"等武装非凡者。主持要点：写弗萨克突出蛮力与军国气质——冰原、巨兵、战鼓，与鲁恩的精致秩序形成冷硬对照，是北大陆博弈的硬筹码。","category":"地点","tags":["弗萨克","艾因霍恩","战神","圣密隆"],"alwaysInclude":false,"priority":"medium"},{"title":"伦堡王国","content":"北大陆南方的小国，与马锡、塞加尔等同为从费内波特分裂出的自由城邦式国家，以信仰知识与智慧之神为主，掌握白塔体系。首都艾萨拉是知识与智慧之神教会总部\"知识圣殿\"所在地，学术与神秘学氛围浓厚。伦堡民风保守刚硬，货币为萨森金。主持要点：写伦堡突出学院与图书馆的冷静理性——这里是读书换力量的白塔途径大本营，也是对神明来历追索的学术前线。","category":"地点","tags":["伦堡","知识与智慧之神","艾萨拉","白塔"],"alwaysInclude":false,"priority":"low"},{"title":"费内波特王国","content":"北大陆南部的强国，王室为卡斯蒂亚家族，信奉大地母神，掌握审判者、母亲与月亮体系，通用语为高原语，货币金里索，首都费内波特城位于高原之上。费内波特与因蒂斯在最西面接壤、与鲁恩在迪西湾相邻，是南大陆殖民与信仰争夺的关键一方。主持要点：写费内波特突出高原的辽阔与大地母神的丰饶—死亡双重神性，以及它作为审判者与母亲途径交汇处的复杂生态。","category":"地点","tags":["费内波特","卡斯蒂亚","大地母神","高原"],"alwaysInclude":false,"priority":"low"},{"title":"精灵王庭","content":"精灵古神的神国，位于西大陆，是精灵一族的故乡，存在于神话传说之中。精灵王庭与巨人王庭分属不同源质阵营，是第二纪古神时代的遗留。西大陆被天尊借源堡封印了除混沌海之外的其余源质，精灵王庭因此笼罩在谜团与禁忌之中。主持要点：写精灵王庭只作神话与传闻——它是\"西大陆尽头\"的浪漫化想象，凡人视角下不可抵达，可作为古老血脉与失落文明的伏笔。","category":"地点","tags":["精灵王庭","西大陆","精灵","古神"],"alwaysInclude":false,"priority":"low"},{"title":"死者之国","content":"又称冥界，是死神格蕾嘉莉在灵界内开辟出的特殊领域，被描述为\"所有死亡的归宿，深藏灵界的地狱，万物终朽的见证，独属于死神的国度\"。它是收尸人途径与死神权柄的核心场域，亡灵、摆渡与死亡规则皆源于此。主持要点：写死者之国走\"灵界深处的寂静\"路线——无上下左右之分，过去与未来在此交汇，唯有死神途径高位者可真正涉足，凡人至多触及其边缘的低语。","category":"地点","tags":["死者之国","冥界","死神","灵界"],"alwaysInclude":false,"priority":"medium"},{"title":"罗思德群岛","content":"位于中苏尼亚海域的群岛，是鲁恩王国在该海域的统治支点，也是风暴教会的关键教区，长期有一位能参与枢机会议的高级执事驻守。克莱恩在廷根事变后曾流落于此一带，群岛是连接北大陆与殖民航线的中转要冲。主持要点：写罗思德群岛突出殖民据点的喧嚣与风暴教会的影响力，海风、炮台与教会钟声交织，是出海线的第一道关口。","category":"地点","tags":["罗思德群岛","苏尼亚海","鲁恩","风暴教会"],"alwaysInclude":false,"priority":"low"},{"title":"拜亚姆","content":"南大陆的重要港口城市，是鲁恩等国殖民统治的支点之一，也是各方势力与隐秘组织交汇的混乱之地。月城遗民离开神弃之地后曾定居于此。拜亚姆港帆樯林立，殖民官员、海盗、赏金猎人与神秘学贩子在此进进出出，是出海线与南大陆剧情的枢纽。主持要点：写拜亚姆突出殖民地的杂糅与无序——不同语言、信仰与利益在此碰撞，每一间酒馆都可能坐着一条情报线的节点。","category":"地点","tags":["拜亚姆","南大陆","港口","殖民地"],"alwaysInclude":false,"priority":"low"},{"title":"霍纳奇斯山脉","content":"北大陆的庞大山脉，是真实造物主与相关隐秘势力的古老源头之一，夜之国即位于其主峰。山脉深处潜藏着与\"夜的主宰\"信仰及安提哥努斯相关的遗迹与低语，是高序列博弈与疯狂污染的险地。主持要点：写霍纳奇斯走\"群山深处的禁忌\"路线——雪线之上的废弃神国、风中夹杂的呓语，让攀登者分不清是寒冷还是被注视的战栗。","category":"地点","tags":["霍纳奇斯","真实造物主","夜之国","山脉"],"alwaysInclude":false,"priority":"medium"},{"title":"狂暴海","content":"分隔北大陆与南大陆的辽阔海洋，以天灾众多、险流无数闻名，常年电闪雷鸣、磁场紊乱、风暴肆虐，只有少数几条航道可以通行。传说它由死神在逃回南大陆的过程中所创造，分隔了南北两个世界。海盗、私掠与殖民航线皆在此搏命。主持要点：写狂暴海突出自然的暴虐——它不是背景，而是角色，每一场出海都是与天灾的对赌，是水手途径非凡者真正的试炼场。","category":"地图","tags":["狂暴海","五海","风暴","航线"],"alwaysInclude":false,"priority":"medium"},{"title":"迷雾海","content":"位于北大陆与南大陆西边的海洋，其尽头可能存在西大陆、精灵的故乡。迷雾海常年被厚重雾气笼罩，能见度极低，传说与失落大陆和精灵王庭相连，是航海者既向往又恐惧的未知之海。主持要点：写迷雾海突出\"雾的另一边是什么\"的悬念——它是地图边缘的留白，承载西大陆与精灵神话的伏笔，凡人船队极少真正穿越。","category":"地图","tags":["迷雾海","五海","西大陆","雾"],"alwaysInclude":false,"priority":"low"},{"title":"苏尼亚海","content":"位于北大陆与南大陆东边的海洋，天气变化剧烈，其尽头可能存在东大陆（神弃之地）。罗思德群岛是鲁恩在此的统治支点，海域内航线繁忙又危机四伏。苏尼亚海是连接列强本土与殖民地的命脉，也是风暴教会影响力辐射的核心水域。主持要点：写苏尼亚海写出\"变幻\"二字——晴雨转瞬、巨浪与商机同在，是出海线剧情最密集的水域。","category":"地图","tags":["苏尼亚海","五海","罗思德","航线"],"alwaysInclude":false,"priority":"medium"},{"title":"帕伦克岛","content":"南大陆附近海域的岛屿，邻近班西港，曾因一场涉及教会与隐秘组织的惨烈事件而载入非凡史。岛屿与周围水域是殖民航线与海盗活动交织之处，岛上的遗迹与封印物残痕暗示着更深层的秘密。主持要点：写帕伦克岛突出\"美丽而致命\"——椰林与白沙之下埋着非凡者的尸骨与未解的仪轨，是玩家探索南海域时触碰大事件的入口。","category":"地点","tags":["帕伦克岛","南大陆","海域","遗迹"],"alwaysInclude":false,"priority":"low"},{"title":"班西港","content":"南大陆附近的重要港口，曾因一场骇人的集体异变与教会高层事件而成为非凡史上的警示案例。班西港的惨剧牵扯到封印物、失控与高序列存在的干涉，是\"非凡无小事\"的残酷注解。主持要点：写班西港可作为案件范本——一夜之间全港陷入疯狂或寂灭，事后只剩教会封锁的废墟与无人敢提的禁忌，让玩家体会失控的尺度。","category":"地点","tags":["班西港","南大陆","港口","惨剧"],"alwaysInclude":false,"priority":"low"},{"title":"草原","content":"北大陆北部靠近弗萨克与极地的辽阔草原地带，是尚武游牧部族与战士途径相关血脉的活跃区域。草原上骏马、帐篷与部族征伐并存，崇拜力量与战争的传统与战神教会隐隐呼应。主持要点：写草原突出苍茫与剽悍——风、马蹄与号角，是不同于鲁恩绅士秩序的另一极，可作为战士途径或巨人血脉故事的舞台。","category":"地点","tags":["草原","战士途径","游牧","北大陆"],"alwaysInclude":false,"priority":"low"},{"title":"神战废墟","content":"又称神战遗迹，是神弃之地与外界联系的节点之一（与巨人王庭并列），留存着古神时代毁灭战役的残骸与规则裂痕。废墟中散落着高位非凡特性、源质碎片与不可名状的污染，是半神级以上强者才敢涉足的猎场。主持要点：写神战废墟走\"破碎的法则\"路线——石柱半悬于虚空、时间在此错乱，每一处残骸都可能是一位古神的遗蜕，触碰即招灾。","category":"地点","tags":["神战废墟","神弃之地","古神","遗迹"],"alwaysInclude":false,"priority":"medium"},{"title":"切尔诺贝利","content":"远古太阳神苏醒之地，旧世界的一处研究所，内部的研究员曾遭到过来自地底的污染，隐藏有通往混沌海的通道。它是第三纪之前远古秘密的物理遗存，与\"最初\"和源质的起源紧密相连，是高序列存在与旧日博弈的终极伏笔之一。主持要点：写切尔诺贝利只作深渊级传闻与遗迹——它不在凡人行走的版图内，是\"世界起源\"话题的具象锚点，永远保持不可直视的克制。","category":"地点","tags":["切尔诺贝利","远古太阳神","混沌海","研究所"],"alwaysInclude":false,"priority":"low"},{"title":"夜之国","content":"第四纪的国家，位于霍纳奇斯主峰，由\"半个愚者\"安提哥努斯和他的姐姐共同创建，信仰\"夜的主宰，天之母亲\"。夜之国最终被黑夜女神教会灭国，其遗留的神性与\"愚者\"权柄之谜缠绕在一起，是安提哥努斯笔记与地下城市梦境的源头。主持要点：写夜之国走\"被抹去的国度\"路线——它只存在于笔记、梦境与少数知情者的低语中，是愚者途径历史孔隙里最幽深的伤痕。","category":"地点","tags":["夜之国","安提哥努斯","霍纳奇斯","愚者途径"],"alwaysInclude":false,"priority":"medium"},{"title":"地下城市","content":"愚者途径非凡者（尤其接触安提哥努斯遗留者）反复梦见的虚幻城池，是与夜之国、安提哥努斯家族相关的潜意识空间。它在梦境与历史孔隙中显现，城中回荡着不属于现世的呓语与眼睛的注视，是愚者途径高位权柄的隐喻性封印。主持要点：写地下城市走\"梦境里的古城\"路线——石板、烛火与无数窥视的瞳孔，踏入者须分清这是梦、是历史还是陷阱，污染常由此渗入。","category":"地点","tags":["地下城市","愚者途径","安提哥努斯","梦境"],"alwaysInclude":false,"priority":"medium"},{"title":"帕斯河谷","content":"位于南大陆，处于因蒂斯共和国与鲁恩王国的争夺之中，两国分别在河谷左岸与右岸建立殖民政权，覆灭了原本的帕斯王国。河谷附近还有星星高原，是殖民扩张与隐秘资源争夺的前沿。主持要点：写帕斯河谷突出\"夹缝中的战场\"——两岸旗帜各异、炮口相对，原住民的古老信仰与列强的蒸汽机械在此碰撞，是玩家参与南大陆博弈的入口。","category":"地点","tags":["帕斯河谷","南大陆","因蒂斯","鲁恩"],"alwaysInclude":false,"priority":"low"},{"title":"拜朗","content":"南大陆的核心区域，原由第四纪的\"冥皇\"\"死神\"萨林格尔建立拜朗帝国，信仰死神，发展较为原始，崇尚血祭与死亡。如今被弗萨克、鲁恩、因蒂斯三方占领殖民，分为相对安定的东拜朗与军阀割据的西拜朗，高地王国曾是其分支。主持要点：写拜朗突出\"死神故土的废墟感\"——神庙、枯骨与殖民炮台并立，是死灵途径与不死特性的源头活水，也是最易遭遇失控与疯狂之地。","category":"地点","tags":["拜朗","死神","南大陆","殖民地"],"alwaysInclude":false,"priority":"medium"},{"title":"西大陆","content":"传说位于迷雾海的尽头，是精灵们的故乡，存在于神话之中。天尊曾借助源堡将除混沌海之外的其余七份源质封印于此，使西大陆成为失落与禁忌的代名词。凡人视角下它不可抵达，只在古神传说与高层博弈中被提及。主持要点：写西大陆只作远景与谜底——它是地图最远端的留白，精灵、源质与封印之谜都指向这里，永远保持\"近在咫尺却遥不可及\"的克制。","category":"地图","tags":["西大陆","精灵","源质","迷雾海"],"alwaysInclude":false,"priority":"low"},{"title":"北海","content":"位于北大陆北边的海洋，由北冰洋演化而来，是鲁恩与弗萨克之间渔业、航运与军事对峙的水域。北海的寒冷与极昼极夜影响沿岸非凡者的活动节律，也是极地探索与隐秘航线的起点。主持要点：写北海突出凛冽与边境感——浮冰、渔火与巡逻炮舰，是北大陆列强正面博弈的冰冷前线，亦藏着通往极地海的古老航道。","category":"地图","tags":["北海","五海","北大陆","极地"],"alwaysInclude":false,"priority":"low"},{"title":"极地海","content":"位于南大陆南边的海洋，由南冰洋演化而来，终年严寒、冰山密布，是通往世界最南端与未知秘境的水域。极地海的边缘常出现超越常理的地理与生物，是探索者与高序列存在涉足的危险前沿。主持要点：写极地海走\"世界的尽头\"路线——白茫、寂静与莫名的坐标错乱，让航行者怀疑自己是否还身在现实，是绝佳的诡秘式绝境舞台。","category":"地图","tags":["极地海","五海","南大陆","绝境"],"alwaysInclude":false,"priority":"low"},{"title":"星星高原","content":"位于帕斯河谷附近的南大陆高原，与拜朗、帕斯王国的古老历史相连，是殖民争夺与隐秘资源（包括某些古老特性与遗迹）交叠的区域。高原气候与地形塑造了尚武而封闭的部族文化。主持要点：写星星高原突出\"高处的不详\"——稀薄空气、星夜与孤悬的祭坛，是玩家深入南大陆腹地、触碰死神与古神遗留的阶梯。","category":"地点","tags":["星星高原","帕斯河谷","南大陆","高原"],"alwaysInclude":false,"priority":"low"},{"title":"圣密隆","content":"弗萨克帝国的首都，皇室艾因霍恩家族的居城，是北大陆北部军事与尚武文明的中心。圣密隆的城防、军械与战神教会设施构成弗萨克国力的硬核，亦是世界大战中各方谋算的要点。主持要点：写圣密隆突出要塞气质——石墙、铁甲与战神雕像，是鲁恩视角下\"北方巨人之国\"的权力心脏，谈判与刀兵皆由此发端。","category":"地点","tags":["圣密隆","弗萨克","首都","战神"],"alwaysInclude":false,"priority":"low"},{"title":"特里尔","content":"因蒂斯共和国（及历史上的图铎帝国）的核心城市，罗塞尔大帝的发迹与改革中心，工业与神秘学革命在此交汇。白枫宫即位于此，是罗塞尔遇刺之地。特里尔兼具法兰西风味与蒸汽喧嚣，是南方法律、艺术与阴谋的熔炉。主持要点：写特里尔突出\"革命之城\"的气质——沙龙、工厂与街垒并存，罗塞尔的遗产与刺杀疑云在此盘绕，是玩家触碰穿越者谜题的南方枢纽。","category":"地点","tags":["特里尔","因蒂斯","罗塞尔","白枫宫"],"alwaysInclude":false,"priority":"medium"},{"title":"费内波特城","content":"费内波特王国的首都，位于高原之上，气候温和，是卡斯蒂亚王室的居城与大地母神教会的核心区域。城市依高原地势而建，麦穗、泉水与神殿的意象彰显母亲途径的丰饶神性。主持要点：写费内波特城突出高原都城的静谧与丰饶——不同于鲁恩的雾与贝克兰德的喧嚣，这里有另一种缓慢而深沉的信仰节奏。","category":"地点","tags":["费内波特城","费内波特","大地母神","首都"],"alwaysInclude":false,"priority":"low"},{"title":"艾萨拉","content":"伦堡王国的首都，也是知识与智慧之神教会总部\"知识圣殿\"所在地。艾萨拉以学院、图书馆与学术传统闻名，是白塔途径非凡者与神秘学研究的中心，汇聚着来自各国的学者与抄本。主持要点：写艾萨拉突出书卷与穹顶的冷静——这里是\"知识即权柄\"的具象地，也是追索亵渎石板、源质与古神真相的学术前线。","category":"地点","tags":["艾萨拉","伦堡","知识圣殿","白塔"],"alwaysInclude":false,"priority":"low"},{"title":"迪西湾","content":"北大陆东南部的海湾，鲁恩王国与费内波特王国在此接壤，是两国贸易、殖民与边界博弈的水域。迪西湾的港口与航道承载着南北大陆之间的物资与情报流动，也是教派势力渗透的软腹部。主持要点：写迪西湾突出\"两强夹缝\"——灯塔、税关与走私船并存，一份货物的去向就能牵动两国外交，是玩家周旋于列强之间的天然舞台。","category":"地点","tags":["迪西湾","鲁恩","费内波特","边界"],"alwaysInclude":false,"priority":"low"},{"title":"霍伊大学","content":"鲁恩王国的高等学府，阿兹克·艾格斯（死神之子、第四纪拜朗帝国死亡执政官）曾在此任历史系教员，并以\"提醒\"克莱恩而与之结缘。霍伊大学的图书馆与历史系藏着关于第四纪、死神与古代学者途径的线索。主持要点：写霍伊大学突出学术表象下的秘辛——安静的讲堂与尘封档案之间，可能就坐着一位每隔六十年复活一次的古老存在，是玩家追索死神真相的起点。","category":"地点","tags":["霍伊大学","阿兹克","鲁恩","学府"],"alwaysInclude":false,"priority":"low"},{"title":"封印物0-36·荆棘冠冕","content":"0级封印物，归属鲁恩王室所有。它能燃起黎明光辉守护全城、释放净化火焰瞬杀同阶强者，并可让持有者短暂拥有序列1\"纯白天使\"的实力。但释放光芒越多，自身血肉越容易枯竭至死——代价明码标价。它是王室镇国级的底牌，也是\"以命换力\"这一封印物铁律的写照。主持要点：写荆棘冠冕突出王权的沉重，每一道黎明光辉都以君王的血肉为薪。","category":"物品","tags":["0-36","荆棘冠冕","封印物","鲁恩王室"],"alwaysInclude":false,"priority":"medium"},{"title":"封印物0-01·神陨之旗","content":"0级封印物，是被\"灾祸之城\"与\"永暗之河\"双重污染的红祭司唯一性，外形为烧焦的血旗。其能力作用不可描述、不可窥探，疑似关联灭世级灾难，连真神都难以承受其副作用，由百万尸骸墓园与十万人城市共同镇压。它是封印物体系里\"国家级灾难\"的代名词。主持要点：写神陨之旗只作\"不可名状\"的远景威胁，切勿正面铺陈其能力，保持敬畏感。","category":"物品","tags":["0-01","神陨之旗","封印物","红祭司"],"alwaysInclude":false,"priority":"medium"},{"title":"封印物0-13·最后的盛宴","content":"0级封印物，源于远古太阳神特性。它能将周围化为永不结束的宴会，持有者可操控宴会众人、看穿其想法。但过度使用会导致身体异变，甚至被污染为\"灾难本身\"。它隐喻着真实造物主一脉\"吞噬与宴飨\"的混乱本质。主持要点：写最后的盛宴突出\"温柔的囚笼\"——欢宴之下人人皆为祭品，是极光会与真实造物主侧危险的缩影。","category":"物品","tags":["0-13","最后的盛宴","封印物","远古太阳神"],"alwaysInclude":false,"priority":"low"},{"title":"封印物0-61·旧日之盒","content":"0级封印物，外表为华丽首饰盒，分三层。第一层可将城池玩具化，第二层支持跨大陆远距离传送，更高层则牵连旧日层面的规则。它是\"玩具化现实\"与\"空间跨越\"的可怕结合，每一层开启都伴随着难以预料的反噬。主持要点：写旧日之盒突出\"孩童般的残忍\"——把城市当积木摆弄的力量背后，是旧日权柄的冰冷注视。","category":"物品","tags":["0-61","旧日之盒","封印物","旧日"],"alwaysInclude":false,"priority":"low"},{"title":"蠕动的饥饿","content":"克莱恩持有的封印物手套，苍白、看似普通，却能吞食灵体与非凡者的特性与能力，是占卜家途径高位者收集力量的利器。它每次吞噬都会带来短暂的增益与不可逆的污染，佩戴者需以意志压制其食欲。主持要点：写蠕动的饥饿突出\"饥饿即贪婪\"——它永远想再吃一口，每一次使用都是与失控的讨价还价，是诡秘式宝物\"带刺\"的典型。","category":"物品","tags":["蠕动的饥饿","封印物","手套","吞噬"],"alwaysInclude":false,"priority":"medium"},{"title":"无暗十字","content":"克莱恩持有的封印物，一枚能释放纯净光明的十字架，可驱散黑暗、净化污染、克制亡灵与邪祟，是太阳途径规则的微缩体现。它在雾都与灵异战场中是可靠的护身符，但频繁使用同样消耗持有者的灵性与生命。主持要点：写无暗十字突出\"光本身的代价\"——最温和的净化也需献祭，是教会对抗污染的日常兵器之一。","category":"物品","tags":["无暗十字","封印物","净化","光明"],"alwaysInclude":false,"priority":"medium"},{"title":"星之杖","content":"克莱恩持有的封印物权杖，蕴含星空与占卜家途径的规则，可借星象之力施行远程打击、定位与占卜，是\"愚者\"权柄在器物上的延伸。它召唤的星芒既是攻击也是指引，使用时会引来星界的注视。主持要点：写星之杖突出\"以星为矢\"的庄重——每一次挥动都像在夜空拨动一根弦，威力与污染同行。","category":"物品","tags":["星之杖","封印物","权杖","星空"],"alwaysInclude":false,"priority":"medium"},{"title":"水银之镜","content":"一面具有自我意识的神秘镜子（与\"阿罗德丝\"相关的会说话之镜），能回答持有者的问题，却常以恭维与试探的方式交流，并借机窥探秘密。它每日只回应有限次，是窥秘人与占卜家乐于交易、又须警惕的信息源。主持要点：写水银之镜突出\"镜中另一个你\"——它比你更懂你，也随时可能把你的秘密卖给第三方，是诡秘式情报关系的缩影。","category":"物品","tags":["水银之镜","镜子","封印物","窥秘"],"alwaysInclude":false,"priority":"medium"},{"title":"特莉丝的镜子","content":"魔女教派相关人物特莉丝赠予克莱恩的镜子，是一件兼具通讯、观测与防护意味的神秘道具，可借镜面映照异常、传递讯息，并与魔女一脉的隐秘网络相连。它承载着特莉丝在贝克兰德大雾霾后的复杂情感与未竟之志。主持要点：写此镜突出\"礼物亦是纽带\"——它既是实用道具，也是玩家与魔女教派、与一段悲剧命运相连的扣子。","category":"道具","tags":["特莉丝的镜子","魔女教派","道具","通讯"],"alwaysInclude":false,"priority":"low"},{"title":"海神权杖","content":"源于海神（暴君途径相关）的权杖，掌控海洋、风暴与潮汐的规则，可在海上呼风唤雨、号令水族，是水手与风暴教会一脉争夺的至高圣物。它既是力量的象征，也承载着信仰的锚——海神的神性借信徒祈祷稳固。主持要点：写海神权杖突出\"海的主人\"的威压，以及它如何把持有者推向与风暴之主权柄的微妙冲突。","category":"物品","tags":["海神权杖","海神","权杖","暴君途径"],"alwaysInclude":false,"priority":"medium"},{"title":"门钥匙","content":"与\"门\"途径（学徒途径）相关的空间道具，可开启短距或跨界的传送之门，是亚伯拉罕家族等空间系非凡者传承与逃亡的关键。使用门钥匙需承担空间乱流与\"门先生\"注视的风险，开启不当会引来不可名状的来客。主持要点：写门钥匙突出\"门后未必是你想去的地方\"——每一次传送都是与空间规则的赌约，也是与放逐之门的擦肩。","category":"道具","tags":["门钥匙","门途径","传送","学徒"],"alwaysInclude":false,"priority":"medium"},{"title":"阿兹克铜哨","content":"阿兹克·艾格斯持有的铜哨，吹响可召唤他那具骷髅信使跨越灵界往来送信，是沟通生死两界、连结阿兹克不死特性的信物。铜哨承载着第四纪死神之子跨越千年的记忆与羁绊，也是克莱恩与阿兹克友谊的见证。主持要点：写铜哨突出\"来自亡者的回音\"——每一次哨响，都可能是沉睡千年的古老存在在回应你。","category":"道具","tags":["阿兹克铜哨","阿兹克","信使","死神"],"alwaysInclude":false,"priority":"medium"},{"title":"通晓语","content":"神秘学仪式中使用的超越性语言，据称万物生灵皆可借其彼此理解，常用于召唤、献祭与跨物种交流。它不同于日常的鲁恩语或古赫密斯语，更近于\"世界屏障\"本身的语法，念诵即是在向灵界与星空发出可被听见的信号。主持要点：写通晓语突出\"语言的代价\"——你被听懂的同时，也可能被不该听见的存在听见，召唤从来不是单向的。","category":"物品","tags":["通晓语","语言","召唤","仪式"],"alwaysInclude":false,"priority":"medium"},{"title":"神血","content":"源于真神或高序列神话生物的血肉材料，蕴含着对应途径的纯粹权柄与规则，是制作高位魔药、仪式与封印物的顶级素材。神血既是无价之宝，也是致命污染源——凡人直接接触极易被神性侵蚀而失控。主持要点：写神血突出\"神性的重量\"——一滴血便足以重塑一个人，也足以毁掉一个人，是高位博弈中最硬的通货。","category":"物品","tags":["神血","材料","高序列","污染"],"alwaysInclude":false,"priority":"medium"},{"title":"圣膏","content":"教会配制与祝圣的膏油，用于仪式祝祷、净化与封印物的初步安定，是黑夜女神等正统教会处理非凡事件的常规耗材。圣膏以特定配方调和，可暂时压制灵性波动、遮蔽污染，代价轻微却不可或缺。主持要点：写圣膏突出\"秩序的日常兵器\"——它不耀眼，却是每一次净化仪式里最不起眼也最必要的那一道防线。","category":"道具","tags":["圣膏","教会","净化","仪式"],"alwaysInclude":false,"priority":"low"},{"title":"灵性燃料","content":"用于灵界行走灯具的高效能灵性材料，点燃后可在灵界与现实的夹缝中照亮路径、维持行者不被灵界同化。它是穿越灵界、进行远程降临与历史孔隙探索的必备补给，耗尽则行者容易迷失于象征的海洋。主持要点：写灵性燃料突出\"在疯海中点一盏灯\"的意象——灯灭之处，便是你被灵界吞没之处。","category":"道具","tags":["灵性燃料","灵界","灯具","补给"],"alwaysInclude":false,"priority":"medium"},{"title":"时之虫","content":"阿蒙（错误途径天使）所掌控的蠕虫状非凡造物，象征着\"时之虫\"序列的权柄，可用于寄生、窃取、篡改细微的时间与存在。阿蒙借无数时之虫的分身潜伏于历史与现实，几乎无物不可窃。主持要点：写时之虫突出\"你无法确定你是你\"的恐怖——一只不起眼的虫子，可能正悄悄替换你的身份、记忆与命运。","category":"物品","tags":["时之虫","阿蒙","寄生","错误途径"],"alwaysInclude":false,"priority":"medium"},{"title":"空想之龙","content":"即\"噩梦之龙\"安格尔威德，是空想家途径相关的古龙，其遗留特性凝结出阿勒苏霍德之笔（0-08），并与格罗塞尔游记深层相连，是空想之龙复活的后手。它象征\"空想成真\"这一权柄的源头，凡触及者皆在想象与现实之间游走。主持要点：写空想之龙只作神话与后手——它是\"想象即现实\"的古老注脚，凡人至多窥见其鳞片，正面登场即是旧日级事件。","category":"物品","tags":["空想之龙","安格尔威德","空想家","古龙"],"alwaysInclude":false,"priority":"medium"},{"title":"格罗塞尔游记","content":"一本与阿勒苏霍德之笔（0-08）存在深层次联系的奇异书籍，书中封印着\"负面自我\"与通往混沌海的侧门。一旦与0-08相遇，后者便会\"苏醒\"、降格为复活后的空想之龙安格尔威德。它是高序列博弈中被多方争夺与忌惮的钥匙性物品。主持要点：写游记突出\"书中另有世界\"——它读起来是冒险故事，实为一场足以唤醒古龙的仪式容器。","category":"物品","tags":["格罗塞尔游记","0-08","空想之龙","混沌海"],"alwaysInclude":false,"priority":"medium"},{"title":"邪神脐带","content":"源于梅高欧丝腹中邪神子嗣、来自真实造物主的诡异脐带，是真实造物主降临事件的关键媒介。它能在绝境中将被困者强行拉回现实，却也带来邪神子嗣无法降生的怨恨与污染。因斯·赞格威尔曾借此摆脱未知存在的禁锢。主持要点：写邪神脐带突出\"来自神的脐带也是枷锁\"——它救你一次，便在你身上种下一份无法偿还的债。","category":"物品","tags":["邪神脐带","真实造物主","降临","污染"],"alwaysInclude":false,"priority":"medium"},{"title":"圣赛琳娜骨灰","content":"黑夜女神教会的圣徒遗骸，作为强力圣物被教会珍藏，却因叛徒因斯·赞格威尔的阴谋而被谋取，成为真实造物主降临事件的导火索之一。它凝聚着圣徒的信仰与权能，是高序列仪式渴求的素材。主持要点：写圣赛琳娜骨灰突出\"圣物失窃即灾祸开端\"——一件圣物的流向，足以倾覆一城之安，是廷根悲剧的物化原点。","category":"物品","tags":["圣赛琳娜骨灰","黑夜女神","圣物","廷根"],"alwaysInclude":false,"priority":"medium"},{"title":"黄金梦想号","content":"知识与智慧之神教会相关、由\"冰山中将\"艾德雯娜·爱德华兹统领的帆船，以宝藏猎人式的作风航行于各大海域。船上纪律严明、文化课强制，是出海线中兼具学术与冒险气质的据点。主持要点：写黄金梦想号突出\"漂流的学院\"——甲板上的地图、藏书与炮位并存，是玩家在狂暴海上可靠的盟友与情报源。","category":"道具","tags":["黄金梦想号","艾德雯娜","帆船","出海"],"alwaysInclude":false,"priority":"low"},{"title":"幽蓝复仇者号","content":"阿尔杰·威尔逊（塔罗会\"倒吊人\"）统领的幽灵船，原属风暴教会背景，是他在海上讨生活与情报交易的座舰。幽蓝复仇者号兼具实战战力与隐秘机动性，是倒吊人连接塔罗会与海上势力的纽带。主持要点：写此船突出\"海上的冷面筹码\"——它载着的不是货物，而是阿尔杰对愚者与利益的双重忠诚。","category":"道具","tags":["幽蓝复仇者号","阿尔杰","幽灵船","风暴教会"],"alwaysInclude":false,"priority":"low"},{"title":"未来号","content":"塔罗会\"隐者\"嘉德丽雅统领星星海盗团的旗舰，承载着被\"隐匿贤者\"知识追逐的隐秘与逃亡。未来号是海上高阶非凡者的移动据点，航行于苏尼亚海与殖民地之间。主持要点：写未来号突出\"被知识追猎的船\"——它驶向的每一步，都可能是逃离疯狂或坠入其中的边界。","category":"道具","tags":["未来号","嘉德丽雅","海盗团","隐者"],"alwaysInclude":false,"priority":"low"},{"title":"黎明号","content":"四大海盗之王之一\"神秘女王\"贝尔纳黛·古斯塔夫的旗舰，亦是原因蒂斯皇女探寻父亲罗塞尔晚年隐秘的流动堡垒。黎明号兼具高贵与神秘，是玩家触碰罗塞尔谜团与海盗王层面的高端入口。主持要点：写黎明号突出\"王室余晖的航迹\"——甲板上的每一件陈设，都可能牵连穿越者大帝未竟的真相。","category":"道具","tags":["黎明号","贝尔纳黛","神秘女王","罗塞尔"],"alwaysInclude":false,"priority":"low"},{"title":"纸人","content":"占卜家途径（小丑、魔术师）常用的替身道具，以灵性附着的纸扎人形承受致命攻击、转移伤害或制造分身假象。纸人替身是克莱恩\"苟\"字诀的核心保命手段之一，配合火焰与诈死形成招牌战术。主持要点：写纸人突出\"用一张纸换一条命\"的机巧——它是占卜家诡诈美学的具象，也是玩家在生死关最该备齐的廉价底牌。","category":"道具","tags":["纸人","替身","占卜家","保命"],"alwaysInclude":false,"priority":"medium"},{"title":"灵性粉末","content":"占卜与仪式常用的灵性材料，撒布后可显影环境中的灵性痕迹、辅助灵摆与占卜棒问询。它与占卜铜币等配合使用，是占卜家低序列的入门耗材。主持要点：写灵性粉末突出\"让不可见显形\"——细微的银灰落处，潜藏的情绪、死亡与波动便无所遁形，是玩家破小案的第一把钥匙。","category":"道具","tags":["灵性粉末","占卜","材料","灵性视觉"],"alwaysInclude":false,"priority":"low"},{"title":"占卜铜币与灵摆","content":"占卜家最基础的问询工具：以灵性附着的铜币投掷、或以灵摆悬停，借象征呈现吉凶与方位。答案从来不是直给，而是画面、数字与倾向，需以灵性之眼解读。主持要点：写铜币与灵摆突出\"问而不答、示而不言\"的神秘学流程——占卜是向灵界借一道微光，不是向神求一份答案。","category":"道具","tags":["占卜铜币","灵摆","占卜家","工具"],"alwaysInclude":false,"priority":"medium"},{"title":"符文","content":"仪式魔法中构筑\"接口\"的符号系统，以特定方位、材质与古语刻写，用以向灵界或存在借力。符文是献祭、封印与防护仪式的骨架，刻错或方位偏斜即招反噬。主持要点：写符文突出\"程序即力量\"——每一道笔画都是与更高存在的契约草拟，草率者必被契约反噬。","category":"道具","tags":["符文","仪式","符号","借力"],"alwaysInclude":false,"priority":"medium"},{"title":"圣水","content":"经教会祝圣的水，用于净化灵界污染、驱散低阶邪祟与安定现场，是值夜者处理灵异案件的标准配置。圣水的效力随祝圣者位格与用量变化，面对高层污染则力有不逮。主持要点：写圣水突出\"廉价而必要的防线\"——它未必能斩妖，却能为你争取撤离与呼叫支援的那几秒。","category":"道具","tags":["圣水","净化","教会","驱邪"],"alwaysInclude":false,"priority":"low"},{"title":"非凡生物材料","content":"魔药配制与仪式所需的主辅材料，多取自非凡生物的血肉、器官与特性析出物（如眼珠、鳞片等）。这些材料价格高昂、真伪难辨，是黑市与狩猎线最抢手的硬通货，处理不当即被污染。主持要点：写非凡生物材料突出\"以命换材\"的链条——每一份材料背后，都站着一头被猎杀的怪物或一位陨落的非凡者。","category":"物品","tags":["非凡生物材料","魔药","主材","黑市"],"alwaysInclude":false,"priority":"medium"},{"title":"魔药配方","content":"记载各序列魔药配方与晋升仪式的知识载体，是教会最高机密，黑市偶有残缺版流通且价格高昂。完整配方需经教会演示调配过程才稳妥，残缺或篡改版轻则无效、重则致命。主持要点：写魔药配方突出\"知识即生死\"——一份配方既是晋升的门票，也是试探你是否有资格触碰力量的试金石。","category":"物品","tags":["魔药配方","序列","知识","晋升"],"alwaysInclude":false,"priority":"medium"},{"title":"秘偶","content":"秘偶大师（占卜家途径序列5）以灵性丝线操控的人偶傀儡，可由尸体或非凡者制成，承载部分意识与能力，是\"收尸制偶\"与距离操控的核心。秘偶既可替主受过，也可布建远程眼线与战力。主持要点：写秘偶突出\"另一个你\"的诡谲——当你习惯用偶身行走，真正的自己反而成了最易被遗忘的那一个。","category":"物品","tags":["秘偶","秘偶大师","人偶","操控"],"alwaysInclude":false,"priority":"medium"},{"title":"心魇蜡烛","content":"一种用以施加心理暗示、制造心魔与精神控制的神秘蜡烛，曾在吸血鬼埃姆林身上被用作心理暗示的工具。烛火可引导目标沉入潜意识、改写认知，是观众与心理炼金一脉常用的软性武器。主持要点：写心魇蜡烛突出\"火焰里的低语\"——它不伤身，却让你自己成为自己的敌人，是精神类手段的温柔一刀。","category":"道具","tags":["心魇蜡烛","暗示","心理","控制"],"alwaysInclude":false,"priority":"low"},{"title":"概率之骰","content":"命运途径唯一性的具象化器物（与\"命运天使\"乌洛琉斯、\"命运之轮\"途径相关），能干涉概率与幸运的流转。它曾由生命学派\"命运议会\"议长威尔·昂赛汀持有，是命运层面博弈的关键棋子。主持要点：写概率之骰突出\"骰子的另一面是世界\"——一次掷出，改写的不是赌注，而是因果本身。","category":"物品","tags":["概率之骰","命运途径","唯一性","概率"],"alwaysInclude":false,"priority":"medium"},{"title":"灵性直觉","content":"非凡者对危险的本能预感与对灵性波动的天然敏锐，是占卜家、观众等途径低序列即具备的保命天赋。它常以\"心头一跳\"\"莫名的忌惮\"呈现，无法言明却往往先于理性示警。主持要点：写灵性直觉突出\"身体的占卜\"——当理智还在分析，你的脊背已经替你做出了逃走的决策。","category":"技能","tags":["灵性直觉","预感","危险","保命"],"alwaysInclude":false,"priority":"medium"},{"title":"秘偶操控","content":"秘偶大师以灵性丝线远距离操控人偶傀儡的技艺，可借偶身观察、战斗、替死，乃至将活人\"秘偶化\"以延续其存在。操控的偶越多、越精细，对主体的灵性与意志消耗越大。主持要点：写秘偶操控突出\"以丝为线、以偶为身\"的诡谲——当你习惯隔着丝线生活，真实的血肉之躯反倒成了累赘。","category":"技能","tags":["秘偶操控","灵性丝线","人偶","距离操控"],"alwaysInclude":false,"priority":"medium"},{"title":"灵性丝线","content":"连接非凡者与其操控对象（人偶、灵体、契约物）的灵性纽带，是秘偶大师、收尸人等途径操控类能力的载体。丝线可延伸、可切断，被更高存在标记或反向追索时，持有者会暴露自身。主持要点：写灵性丝线突出\"看不见的提线\"——你以为在操控偶，也许另一端的丝线正被某位天使轻轻捏在指间。","category":"技能","tags":["灵性丝线","秘偶","纽带","操控"],"alwaysInclude":false,"priority":"medium"},{"title":"人偶制作","content":"将尸体或非凡者制成可操控人偶的技艺，是秘偶大师\"收尸制偶\"的环节，需以灵性丝线与特定仪式固化意识残片。制作的人偶可承载部分能力与记忆，是远程战力与眼线的来源。主持要点：写人偶制作突出\"最后的用途\"——一位逝去的非凡者，往往以一具偶的形态继续存在于操控者的棋局里。","category":"技能","tags":["人偶制作","秘偶","收尸制偶","仪式"],"alwaysInclude":false,"priority":"low"},{"title":"梦境潜入","content":"黑夜途径梦魇、观众途径梦境行者等可潜入他人梦境、以梦杀人或窥探潜意识的技艺。梦境是现实规则的薄弱处，潜入者可在其中施加暗示、布设陷阱，亦可能被梦主的反噬困住。主持要点：写梦境潜入突出\"醒不来的那一夜\"——你在别人的梦里既是宾客，也可能成了永远走不出门的囚徒。","category":"技能","tags":["梦境","梦魇","潜入","暗示"],"alwaysInclude":false,"priority":"medium"},{"title":"刺杀技艺","content":"刺客途径（魔女途径序列9）的基础技艺，强调潜行、一击致命与利用环境与心理盲区。低序列刺客以敏捷与诡诈见长，随序列提升逐渐转向以欢愉、痛苦转化的力量。主持要点：写刺杀突出\"影子里的那一刀\"——刺客的可怕不在力量，而在你发现危险时，刀锋已在颈侧。","category":"技能","tags":["刺杀","刺客途径","潜行","一击致命"],"alwaysInclude":false,"priority":"medium"},{"title":"真实面具","content":"与刺客/魔女一脉相关的拟态技艺，可暂时改变外在气质、身份特征与他人的观感，使自己在人群中\"成为另一个人\"而不易被测谎或识破。它不同于无面人的形体易容，更偏向气质与认知层面的伪装。主持要点：写真实面具突出\"让人相信你就是你扮演的人\"——最高明的伪装，是让旁观者主动替你圆谎。","category":"技能","tags":["真实面具","伪装","刺客","认知"],"alwaysInclude":false,"priority":"low"},{"title":"精神穿刺","content":"观众、心理医生等精神系途径的攻击技艺，以灵性直刺目标意识，造成精神崩溃、记忆断层或短暂失控，是\"读心\"能力的战斗化延伸。高位者一击可令敌人在清醒中瓦解自我。主持要点：写精神穿刺突出\"无声的崩坏\"——没有伤口， victim却已不记得自己是谁，是观众途径最锋利的内敛之刃。","category":"技能","tags":["精神穿刺","观众","精神攻击","读心"],"alwaysInclude":false,"priority":"medium"},{"title":"污染净化","content":"以圣水、圣膏、太阳途径圣光或无暗十字等手段清除灵界污染、安定失控现场的处理技艺。净化需流程完整，否则污染残留会反噬施术者或蔓延。它是值夜者与教会处理非凡事件的收尾标配。主持要点：写净化突出\"把疯狂擦干净\"的艰难——你清得越急，越容易被那点疯狂蹭到手上，流程一步都不能省。","category":"技能","tags":["污染净化","圣水","圣光","收尾"],"alwaysInclude":false,"priority":"medium"},{"title":"契约与律令","content":"律师途径（黑皇帝途径序列9）与仲裁人途径相关的技艺，擅长以语言、契约与律令构建约束——律师精于利用规则漏洞与契约绑定，仲裁人则能直接施加\"枷锁\"般的秩序裁决。二者皆以\"言出法随\"的规则之力见长。主持要点：写契约与律令突出\"话就是锁\"——一句措辞，足以把对手钉死在无法违背的条款里。","category":"技能","tags":["契约","律令","律师途径","仲裁人"],"alwaysInclude":false,"priority":"medium"},{"title":"秩序裁决","content":"仲裁人途径（审判者途径）的核心技艺，可对目标施加秩序层面的\"枷锁\"与裁决——剥夺其某种能力、强制其服从判定，乃至以律令法师之姿临时改写局部规则。它是官方秩序非凡者维护稳定的利器。主持要点：写秩序裁决突出\"以法为名的正义之刃\"——当裁决落下，反抗本身即成为对秩序的违背。","category":"技能","tags":["秩序裁决","仲裁人","审判者","枷锁"],"alwaysInclude":false,"priority":"medium"},{"title":"纸人替身","content":"小丑、魔术师以灵性附着纸人承受攻击、制造分身的保命技艺，是占卜家途径\"苟\"字诀的标志性手段。替身可在关键时刻替主身挡下致命一击或误导敌人，配合火焰与诈死形成招牌战术。主持要点：写纸人替身突出\"用一张纸换一条命\"的机巧美学——它廉价、可量产，却是新手非凡者最该学会的退路。","category":"技能","tags":["纸人替身","小丑","保命","占卜家"],"alwaysInclude":false,"priority":"medium"},{"title":"火焰戏法","content":"魔术师（占卜家途径序列7）掌握的十种戏法之一，可于掌心或指定处喷吐火焰、引爆目标，是占卜家低序列少有的直接攻击手段。戏法讲究\"骗术\"本质——以幻乱真、以巧破力。主持要点：写火焰戏法突出\"表演即战斗\"——观众以为的戏法，在敌人身上燃成了真实的灼痕。","category":"技能","tags":["火焰戏法","魔术师","占卜家","攻击"],"alwaysInclude":false,"priority":"low"},{"title":"无面人易容","content":"无面人（占卜家途径序列6）可改变容貌、身形、声线与气质的易容技艺，是\"成为他人\"的极致，配合扮演法可长期潜伏而不被识破。易容越彻底，对自我认知的侵蚀越深。主持要点：写无面人易容突出\"面具长进了肉里\"——当你换了太多张脸，最初的自己反而成了最难扮演的那一个。","category":"技能","tags":["无面人","易容","占卜家","潜伏"],"alwaysInclude":false,"priority":"medium"},{"title":"寄生","content":"偷盗者途径（错误途径）的技艺，可将自身或某种存在\"寄生\"于他者体内，窃取其能力、身份与命运，阿蒙即以此遍布分身。寄生是\"偷盗者\"权柄的微观体现，亦是时之虫运作的方式。主持要点：写寄生突出\"住进你身体里的另一个意识\"——你以为在做决定，其实那道念头来自寄生者轻推的一下。","category":"技能","tags":["寄生","偷盗者","阿蒙","窃取"],"alwaysInclude":false,"priority":"medium"},{"title":"偷盗与欺诈","content":"偷盗者途径序列9\"偷盗者\"起家的核心技艺，擅长窃取财物、信息与微小的权柄，并以欺诈掩盖行迹。它是\"错误\"权柄的幼态——从偷一个钱包，到偷一段命运，本质一脉相承。主持要点：写偷盗与欺诈突出\"贼的逻辑\"——最高明的贼，连\"被偷\"这件事都会从你记忆里一并顺走。","category":"技能","tags":["偷盗","欺诈","偷盗者途径","错误"],"alwaysInclude":false,"priority":"medium"},{"title":"概率干涉","content":"怪物途径（命运之轮途径）相关的技艺，可微调幸运与厄运的流向——幸运儿逢凶化吉，厄运法师则把灾祸引向敌身。它自带极强的随机性，是命运层面\"混乱即规则\"的体现。主持要点：写概率干涉突出\"骰子早就被做过手脚\"——你以为的巧合，不过是某人轻轻拨动了因果的权重。","category":"技能","tags":["概率干涉","怪物途径","命运之轮","幸运"],"alwaysInclude":false,"priority":"low"},{"title":"占星术","content":"学徒途径（门途径）序列7\"占星人\"及窥秘人一脉的技艺，借星象推演命运、方位与远方之变，是连接星界与现实的观测手段。占星须规避星空的注视，否则反被污染。主持要点：写占星突出\"仰望星空的代价\"——你每读出一颗星的暗示，星空也多看了你一眼，看多了，便再也洗不掉那道注视。","category":"技能","tags":["占星术","学徒途径","星界","命运"],"alwaysInclude":false,"priority":"medium"},{"title":"记录与复制","content":"学徒途径（门途径）序列6\"记录官\"的核心技艺，可记录并临时复刻其他途径、其他非凡者的能力为己用，是\"门\"权柄对多样性规则的容纳。记录越多，越接近\"万法皆可借\"的旅法师境界。主持要点：写记录与复制突出\"借来的力量，记得归还\"——复刻有时限，过期之后的空洞，只有你自己知道。","category":"技能","tags":["记录","复制","学徒途径","门"],"alwaysInclude":false,"priority":"medium"},{"title":"灵体放逐","content":"黑夜途径（不眠者途径）高位者如守夜人、恐惧主教可施展的技艺，将邪祟、灵体与异常存在从现世放逐回灵界或幽界，是镇压灵异的主力手段。放逐需以阴影与黑暗为媒介，过度使用会招来更高存在的回望。主持要点：写灵体放逐突出\"把不该在的东西送回去\"——门一关，寂静落下，可门后的东西也记住了你的气息。","category":"技能","tags":["灵体放逐","黑夜途径","守夜人","镇压"],"alwaysInclude":false,"priority":"medium"},{"title":"圣光净化","content":"太阳途径（歌颂者途径）的招牌技艺，以神圣光焰驱散黑暗、净化亡灵与污染、治愈伤势，是克制死灵与邪祟的规则级力量。高位无暗者、正义行者可立下不可违背的光之契约。主持要点：写圣光净化突出\"光本身的绝对性\"——在它的照耀下，污秽无处藏身，可施光者亦被光灼伤自身。","category":"技能","tags":["圣光净化","太阳途径","歌颂者","治愈"],"alwaysInclude":false,"priority":"medium"},{"title":"风暴召唤","content":"暴君途径（水手途径）的核心技艺，低序列即能感风唤浪，高位海王、天灾可召雷引电、掀起灭世级天灾。它是海洋与天气规则的操控，水战近乎无解。主持要点：写风暴召唤突出\"海与天的怒意\"——你唤来的不只是风浪，更是暴君权柄对凡间秩序的睥睨。","category":"技能","tags":["风暴召唤","暴君途径","水手","天灾"],"alwaysInclude":false,"priority":"medium"},{"title":"亡灵召唤","content":"收尸人途径（死神途径）的技艺，可沟通、召唤与役使亡灵，低序列感知死亡与低语，高位不死者、摆渡人可令死者复行、操纵死亡规则。它是死神权柄在现世的延伸，亦伴随被亡者反噬的风险。主持要点：写亡灵召唤突出\"与死者讨价还价\"——你唤起的每一个亡魂，都带着未竟的怨，迟早要你偿还。","category":"技能","tags":["亡灵召唤","收尸人途径","死神","死亡"],"alwaysInclude":false,"priority":"medium"},{"title":"药师炼金","content":"药师途径（月亮途径序列9）与耕种者途径相关的基础技艺，擅长调配药剂、改造血肉与催生生命，是血族与大地母神一脉的看家本领。它介于治疗、改造与创造之间，亦是魔药体系平民化的缩影。主持要点：写药师炼金突出\"瓶中的生命\"——每一剂药都是对血肉规则的一次小小僭越，用错了方向，便成了怪物。","category":"技能","tags":["药师炼金","药师途径","药剂","血肉"],"alwaysInclude":false,"priority":"low"},{"title":"灵性遮蔽","content":"以仪式、符号或灰雾之力遮蔽自身灵性痕迹、防止被高序列占卜与定位的防护技艺，是出行与行动前的标准准备。遮蔽不完整则形同虚设，被标记者将无处遁形。主持要点：写灵性遮蔽突出\"在众神注视下隐身\"的紧张——你布的每一道屏蔽，都是为了不被某双早已落下的眼睛看见。","category":"技能","tags":["灵性遮蔽","防护","反占卜","仪式"],"alwaysInclude":false,"priority":"medium"},{"title":"献祭与祈祷回应","content":"向存在（神、天使、灵界生物）献上祭品以换取回应的技艺，回应者不可控，可能来得不是你要的那位。祈祷亦是愚者信仰等\"凡人造神\"闭环的引擎——回应积累出信仰。主持要点：写献祭与祈祷突出\"敲门的人未必是你想请的客\"——你献上的代价越重，门后走出的存在越可能不是你预期的那个。","category":"技能","tags":["献祭","祈祷","回应","信仰"],"alwaysInclude":false,"priority":"medium"},{"title":"灵界生物召唤","content":"借仪式从灵界唤来原住民或灵体生物为己所用的技艺，可用于侦察、护卫或取材，但灵界生物形态诡异、难以约束，召唤不当会被反噬或引来更高存在的注意。主持要点：写灵界生物召唤突出\"从疯海里捞上来的活物\"——它听不懂你的人话，只认得你献上的那份象征。","category":"技能","tags":["灵界生物","召唤","灵界","侦察"],"alwaysInclude":false,"priority":"low"},{"title":"读心与暗示","content":"观众途径序列9\"观众\"起家的核心技艺，可读取他人情绪、捕捉微表情与潜意识的破绽，并以暗示悄然引导其想法。它是\"旁观者\"洞察人心的起点，亦是高序列空想成真的根基。主持要点：写读心与暗示突出\"看穿不等于看透\"——你读得到情绪，却读不到对方同样在读取你的那份冷静。","category":"技能","tags":["读心","暗示","观众途径","情绪"],"alwaysInclude":false,"priority":"medium"},{"title":"催眠","content":"观众途径催眠师等可施行的技艺，以语言、节奏与灵性引导令目标进入易被植入指令的催眠状态，用于问讯、疗愈或战斗控制。深层催眠可改写记忆与认知。主持要点：写催眠突出\"被编排的清醒\"——被催眠者以为自己在做选择，其实每一步都踩在施术者铺好的节拍上。","category":"技能","tags":["催眠","观众途径","暗示","控制"],"alwaysInclude":false,"priority":"low"},{"title":"入梦杀人","content":"黑夜途径梦魇（序列7）的招牌技艺，潜入目标梦境后以梦中之死波及现实，使人在沉睡中真正死去，是夜战与暗杀的无声利刃。入梦者亦可能被梦主困住或反噬。主持要点：写入梦杀人突出\"最安详的死法，最毛骨悚然的凶手\"——受害者临终前，或许正做着一生最好的那个梦。","category":"技能","tags":["入梦杀人","梦魇","黑夜途径","暗杀"],"alwaysInclude":false,"priority":"medium"},{"title":"非凡体系三层结构：源质·唯一性·非凡特性","content":"诡秘世界的非凡力量自下而上有三层骨架。最底层是非凡特性：每条途径各序列对应的「权柄碎片」，死亡后析出、可制作魔药。中间层是唯一性：每条途径序列0专属的核心特性，同途径同一时间仅存一份。最顶层是源质：九大源质是比唯一性更高一阶的世界级权柄容器，每条途径都锚定在某源质之上（如占卜家途径锚定源堡）。序列0真神需集齐唯一性加三份序列1非凡特性；而源质是诸旧日权柄的根基。规则要点：源质容纳唯一性，唯一性聚合非凡特性，三层逐级收束——这是「同途径只能有一位序列0」「特性守恒与聚合」一切规律的源头。凡人视角阶段，这三层仅作传闻与档案残页，逐段投放，严禁提前解谜。","category":"设定","tags":["源质","唯一性","非凡特性","体系结构"],"alwaysInclude":false,"priority":"top"},{"title":"神话生物形态与高序列的人性保持","content":"序列4及以上称为半神，序列2、1为天使，序列0为真神；晋升越高，灵魂与体魄越向「神话生物形态」异化——不再以纯粹人形存在，而是以规则、象征、天体般的形态显化。这带来两点铁律：其一，高序列对低序列有天然的威压与不可直视性，凡人窥视即受污染；其二，神话生物化会吞噬人性，失去锚的半神将彻底疯狂。规则要点：半神需以锚（信徒信仰、亲情、执念）稳定人性；序列0真神更须依靠足够锚维持理智与存在。主持要点：写高序列出场走「不可名状的威压」路线，少写实多写其降临带来的规则扭曲与旁观者的精神震颤。","category":"设定","tags":["神话生物","半神","人性","威压"],"alwaysInclude":false,"priority":"medium"},{"title":"天使位阶：序列2/1与神之使徒","content":"天使是序列2与序列1的存在，是诸神麾下执掌神话与规则的从神，注视凡人即可降下祝福或污染。天使其上各有来历：部分为古神从神（如黑夜女神的厄运女神阿曼妮西斯）、部分为远古太阳神座下天使之王（如空想天使亚当、时天使阿蒙、纯白天使奥赛库斯、风天使列奥德罗、智天使赫拉伯根）。天使亦有自己的疯狂与宿命，多借化身或代理人行动。规则要点：天使级博弈是第五纪暗线的真正操盘层；玩家至多触及其边缘代理人，面对面即越界。主持要点：天使以「痕迹、棋局、降临一瞬」呈现，其可怕在于布局而非战力。","category":"设定","tags":["天使","序列2","序列1","天使之王"],"alwaysInclude":false,"priority":"medium"},{"title":"九大源质与二十二途径映射","content":"最初造物主分裂出九大源质，二十二条神之途径在地球聚拢，每条途径锚定于某源质（源质容纳对应唯一性）。已知的源质—途径聚合分组如：源堡对应占卜家、学徒、偷盗者三途径（福生玄黄天尊侧）；混沌海对应空想家、黑暗、黄昏巨人等（上帝侧）；永暗之河对应黑夜途径；灾祸之城、知识荒野、光之钥、失序之国、暗影世界、母巢等各归其途径。规则要点：同组源质的途径相邻、可互换且高位互相吸引（聚合定律的动力学根源）；跨组强行晋升会神性暴走。主持要点：源质分组在凡人视角仅作传闻，逐段投放，严禁提前解谜。","category":"设定","tags":["九大源质","二十二途径","分组","聚合"],"alwaysInclude":false,"priority":"top"},{"title":"最初造物主分裂与九大源质诞生","content":"第一纪混沌纪元，最初造物主从混沌中苏醒又陷入疯狂与分裂。祂从宇宙深处的三位外神身上撕裂部分，彻底分裂出九大源质：混沌海、源堡、永暗之河、灾祸之城、知识荒野、光之钥、失序之国、暗影世界、母巢。与此同时，堕落母神失去母巢、月亮、母亲，混沌之子失去失序之国、黑皇帝、审判者，欲望母树失去暗影世界、深渊、被缚者。部分受碎片影响的人类与动物成为巨人、精灵、血族、巨龙、魔狼等超凡种族。天尊与上帝两大分裂人格借旧时代布局占据上风，各自容纳复数源质，因聚合本能互相争斗而双双陨落，为后续纪元埋下根脉。","category":"设定","tags":["最初造物主","分裂","九大源质","天尊上帝"],"alwaysInclude":false,"priority":"top"},{"title":"灵界·星界·现实三层世界结构","content":"诡秘世界的空间分三层叠加。现实世界是凡人栖居的表层；灵界是精神与象征的海洋，与现实重叠却遵循另一套几何与法则，盘踞着灵界生物、历史残留的碎片场景与被高序列存在占据的领域；星界位于更外层，诸神神国多移至星界以填补最初屏障的裂缝。三层通过灵性、星灵体与仪式沟通。规则要点：其一，注视是双向的，你凝视灵界星空，亦被凝视；其二，高序列可标记凡人灵性，被标记者无处遁形；其三，灵界与星界行走须遮蔽自身。主持要点：灵界描写走「象征与几何错乱」路线，星界写神国与屏障的苍茫，少写实多写不合常理的构图。","category":"设定","tags":["灵界","星界","现实","三层世界"],"alwaysInclude":false,"priority":"medium"},{"title":"星灵体与占星法则","content":"星灵体是凡人与灵界、星空沟通的桥梁，也是占星类非凡者借以观测命运与远程感知的媒介。占星家通过星灵体连接星界，窥探目标轨迹、预判吉凶，但星空本身危险——直视星空会招致污染，窥秘人途径明言「星空是伟大的又是危险的」。规则要点：占星与观测皆需遮蔽与代价，过度窥探高层次存在会被反向标记；星界中诸神神国与旧日残留交错，是远程降临与信息战的战场。主持要点：占星戏写出「借道星灵体的程序感与窥探的代价」，占星结果保持象征性而非直给答案。","category":"设定","tags":["星灵体","占星","星空","观测"],"alwaysInclude":false,"priority":"medium"},{"title":"历史孔隙与历史投影","content":"灵界深处留存着历史的孔隙——过去事件的精神投影与残片场景，高序列非凡者可短暂回溯至古代历史片段、借古之力（如占卜家途径的古代学者）。历史投影并非真实重演，而是象征层面的残留，可被观测、被借力，却不可逆改。规则要点：历史孔隙是「古代学者」「旅法师」等能力的根基，也是追索被抹去历史（如第三纪弑神真相）的线索源；白银城保存的残史即此类投影的具象。主持要点：写历史回溯戏突出「似真似幻、触碰即逝」的疏离感，借古之力要有代价与限度。","category":"设定","tags":["历史孔隙","历史投影","回溯","灵界"],"alwaysInclude":false,"priority":"medium"},{"title":"污染来源分级","content":"诡秘世界的污染按来源分三级，层级越高越不可逆。低层污染来自未消化魔药与低序列失控，表现为灵性躁动与肢体异变，多可经净化缓解。中层污染来自同途径高位存在的意志入侵，表现为听到某个存在的声音、思维被渗透，需以锚与仪式对抗。高层污染来自旧日呓语与星空直视，会直接改写认知与现实，接触即有被同化风险。规则要点：教会以圣水、符号、祷言处理低层污染现场；中层以上须上报高层并长期监控；玩家持有带污染封印物、占卜禁忌对象都会累积相应层级污染。描写用低语、记忆篡改、肢体异变递进呈现。","category":"设定","tags":["污染","分级","低层","高层"],"alwaysInclude":false,"priority":"medium"},{"title":"非凡者人数控制与序列登记","content":"七神教会严密控制非凡者人数与层级。低序列者可经教会审核晋升并获配方与主材；序列5以上即视为半神级战略威慑，须登记、受监控，其存在与行动被各教会高层掌握。野生成途径者（黑市魔药晋升）被视为隐患，遭清剿或招安。规则要点：教会慷慨分享中低序列配方是为了培育信仰之锚与可控战力，而高序列只供成品魔药以防争夺锚；序列登记使得「失踪的半神」本身就是情报。主持要点：玩家若为野途径者，会被官方追查身份；若为教会成员，晋升与任务皆走流程审批，力量始终带着体制的冷感。","category":"设定","tags":["人数控制","序列登记","半神","监控"],"alwaysInclude":false,"priority":"medium"},{"title":"外神与星空的层级关系","content":"外神是宇宙深处星空的更古老者，位格高于旧日。最初造物主分裂时曾从三位外神身上撕裂部分融入自身，可见其高。旧日多被视作「屏障之内的高位」，而外神虎视于屏障之外，伺机渗透——星空污染、直视星空的禁忌皆源于此。部分旧日（如堕落母神）因与屏障外同源，兼具外神侧属性。规则要点：屏障破损是终局危机的核心，外神入侵是旧日复苏之上更深的威胁；凡人视角的故事止步于「知道名字」，玩家角色最高只触及旧日层面的边缘。主持要点：外神只宜作远景与污染源头，具象登场须保持不可名状的克制。","category":"设定","tags":["外神","星空","屏障","层级"],"alwaysInclude":false,"priority":"medium"},{"title":"旧日·堕落母神","content":"堕落母神是较早诞生的旧日，最初造物主于第二日诞下祂，现实因此有了支撑，灵界与星界分离、命运长河开始流淌。祂失去母巢、月亮、母亲三份源质，与大地母神、月亮途径渊源极深，亦被视为与外神同源、具外神侧属性。堕落母神是诸多「母亲」「月亮」「魔女」相关权柄的古老源头，其意志渗透常表现为滋生的血肉、扭曲的孕育与不可名状的低语。规则要点：作为旧日名单的首要存在，祂在凡人剧情中只作远景与污染源头，接触即有被同化风险。主持要点：描写其痕迹用「过度丰饶、血肉畸变」的意象，保持不可名状。","category":"设定","tags":["旧日","堕落母神","母巢","外神侧"],"alwaysInclude":false,"priority":"medium"},{"title":"旧日·混沌之子","content":"混沌之子于堕落母神之后诞生，创造了秩序，而秩序自带阴影——这一悖论使其成为「失序」与「秩序」双重权柄的古老源头，失去失序之国、黑皇帝、审判者三份源质。混沌之子曾通过自杀将意识（灯神）在地球的黑皇帝上复活，后被天尊封印为0-05许愿神灯。其残留部分在屏障外化为「不定之雾」。规则要点：混沌之子是黑皇帝、审判者途径的古老根脉，与第四纪诸皇的合法性暗线相连。主持要点：写其相关痕迹（如神灯中的灯神）突出「秩序与疯狂一体两面」的悖论感。","category":"设定","tags":["旧日","混沌之子","失序之国","灯神"],"alwaysInclude":false,"priority":"medium"},{"title":"旧日·命运编织者","content":"命运编织者是最初与堕落母神交合诞下的长女（第三日），万物的命运自此交织，不再绝对混乱，有了相对规律与可预见的未来。祂是命运权柄的古老源头，宿命之环、超星主宰等后续旧日均在其之后诞生。命运编织者相关的途径与能力多涉及预言、编织与改写命运（如偷盗者途径的命运木马、时之虫）。规则要点：命运类非凡者窥探命运即有被其意志触及的风险。主持要点：写命运戏突出「线已织就、挣扎亦是其中一环」的宿命感，而非廉价预言。","category":"设定","tags":["旧日","命运编织者","命运","预言"],"alwaysInclude":false,"priority":"medium"},{"title":"旧日·宿命之环","content":"宿命之环是最初与堕落母神所生、继命运编织者之后的旧日，执掌循环的宿命权柄。其与命运编织者同属命运一脉，却更强调「无可逃脱的轮回与闭环」。宿命之环相关的非凡痕迹常表现为重复的灾劫、无法打破的因果圈。规则要点：作为旧日名单成员，其名本身就带污染，凡人知之即有被卷入宿命循环之险。主持要点：将其作为终局远景与宿命主题的象征，写「逃不出的环」意象，保持克制。","category":"设定","tags":["旧日","宿命之环","宿命","循环"],"alwaysInclude":false,"priority":"medium"},{"title":"旧日·超星主宰","content":"超星主宰是继命运编织者、宿命之环之后诞生的旧日，执掌星空的权柄。在第二纪早期，太阳本是超星主宰，但因屏障影响光照无法进入，世界一度黑暗。超星主宰与星界、星光、天体运转渊源极深，是占星与星空污染的古老源头之一。规则要点：其存在解释了「星空伟大又危险」——直视星空即可能触及超星主宰层次的注视。主持要点：写星空戏以超星主宰为远景威压，星象异变、天体错位皆可是其痕迹。","category":"设定","tags":["旧日","超星主宰","星空","星界"],"alwaysInclude":false,"priority":"medium"},{"title":"旧日·高维俯视者","content":"高维俯视者是旧日名单中的高位存在，其视角的「高维」意味着超越常规空间与认知的注视——被其俯视者如同纸面图案，一切隐秘与维度皆摊开于前。高维俯视者相关的权柄涉及观测、透视与维度压制。规则要点：作为旧日，其注视即污染，凡人层面只作传闻。主持要点：写其痕迹用「被看不见的眼睛看穿一切伪装」的不安感，保持不可名状。","category":"设定","tags":["旧日","高维俯视者","注视","维度"],"alwaysInclude":false,"priority":"medium"},{"title":"旧日·不熄的呓语","content":"不熄的呓语是旧日名单中的存在，其权柄表现为永不止息的精神低语——这种呓语正是高序列污染、旧日复苏入侵凡人理智的主要载体之一。被不熄的呓语触及者，会持续听到无法辨认来源的言语，逐渐丧失自我。规则要点：它是「污染」概念的具象源头之一，与星空、旧日复苏的终局危机相连。主持要点：写污染侵袭用「耳边永不停歇的陌生低语」意象，让疯狂有声音。","category":"设定","tags":["旧日","不熄的呓语","低语","污染"],"alwaysInclude":false,"priority":"medium"},{"title":"旧日·原初饥饿","content":"原初饥饿是旧日名单中的存在，执掌吞噬与饥饿的权柄。其痕迹表现为无底的渴求、吞噬一切的意志，与深渊、被缚者等途径的「饥饿」特质同源。原初饥饿的序列1特性「混沌胃液」曾污染0-61旧日之盒（学徒途径旅法师），可见其对外渗透之深。规则要点：作为旧日，其名带污染，凡人触之即有被吞噬之险。主持要点：写其痕迹用「永远吃不饱的空虚与吞噬欲」意象，保持克制与远景。","category":"设定","tags":["旧日","原初饥饿","吞噬","饥饿"],"alwaysInclude":false,"priority":"medium"},{"title":"旧日·衰败君王","content":"衰败君王是旧日名单中的存在，执掌腐朽、衰败与终结的权柄。其相关痕迹表现为万物不可逆的凋零、文明的衰朽与时间的尽头。衰败君王与死神、被缚者等「终结」类权柄有渊源。规则要点：作为旧日，其名本身即带终结性的污染，凡人层面只作传闻。主持要点：写其远景用「一切终将腐朽」的苍凉意象，作为终局危机的深层背景之一。","category":"设定","tags":["旧日","衰败君王","衰败","终结"],"alwaysInclude":false,"priority":"medium"},{"title":"旧日·欲望母树","content":"欲望母树于堕落母神之后诞生，带来了生灵，也带来了恶与欲——是欲望、诱惑与繁衍权柄的古老源头。祂失去暗影世界、深渊、被缚者三份源质，与异种、深渊、被缚者等途径渊源极深。欲望母树相关的污染常表现为膨胀的欲望、诱惑的陷阱与不可控的繁衍。规则要点：作为旧日，其痕迹多见于隐秘组织的诱惑仪式与被缚者途径的异变。主持要点：写其痕迹用「欲望无限膨胀、终至毁灭」的意象，保持不可名状。","category":"设定","tags":["旧日","欲望母树","欲望","诱惑"],"alwaysInclude":false,"priority":"medium"},{"title":"西大陆与源质封印","content":"天尊与上帝陨落前，天尊将除源堡与混沌海之外的其余源质封印于西大陆，并设下灰雾屏障，唯有旧日层次方能开启——初代精灵与西大陆人因此被隔绝于西大陆之外。这一封印是地球屏障的重要组成，也是终局层面旧日争夺的焦点。规则要点：西大陆在第五纪是「谜之大陆」，与源质封印、屏障存续直接相关；其开启意味着旧日级灾难。主持要点：西大陆前期只作传闻与航海者的禁忌话题，切勿让玩家轻易抵达，保持其神秘与危险。","category":"设定","tags":["西大陆","源质封印","天尊","屏障"],"alwaysInclude":false,"priority":"medium"},{"title":"风暴之主教会（海上信仰）","content":"风暴之主教会尊奉风暴之主列奥德罗（暴君途径，原远古太阳神座下风天使），尊名空之王、海之皇、天灾君主、风暴之神，神像黑甲踏浪持三叉戟。其信仰以海上与沿海列强为根基，海祭传统深厚，风暴教会非凡者多走水手—暴君一脉，作风剽悍。规则要点：风暴之主与永恒烈阳、知识与智慧之神彼此敌视（罗塞尔日记所录），教派政治中属强硬派；其海上权柄使其成为殖民地与航线争夺的关键。主持要点：写风暴教会突出「海与天灾」的暴烈质感，与黑夜女神的静谧形成对照。","category":"势力","tags":["风暴之主教会","列奥德罗","海上","暴君"],"alwaysInclude":false,"priority":"high"},{"title":"永恒烈阳教会与代罚者","content":"永恒烈阳教会尊奉永恒烈阳奥赛库斯（原远古太阳神座下纯白天使），尊名永恒烈阳、不灭之光、秩序化身、契约之神、商业守护者。其武装代罚者以太阳途径光明与净化、誓约之力见长，作风强硬、纪律严明。规则要点：永恒烈阳与风暴之主、知识与智慧之神互相敌视，却同属针对黑夜女神与战神的对立阵营；其「契约之神、商业守护」属性使其与世俗经济深度绑定。主持要点：写代罚者突出光照与审判的冷硬感，其净化仪式与契约权柄是规则级力量。","category":"势力","tags":["永恒烈阳教会","代罚者","奥赛库斯","契约"],"alwaysInclude":false,"priority":"high"},{"title":"战神教会与惩罚军团（弗萨克）","content":"战神教会尊奉战神巴德海尔（黄昏巨人途径，原巨人王的从神晨曦之神），是弗萨克帝国的国教。其武装惩罚军团以战士—战神一脉的战斗特质著称，崇尚荣誉与战争，作风彪悍。规则要点：战神教会与黑夜女神教会水火不容（罗塞尔日记所录），是北大陆两大对立教派之一；弗萨克帝国国民带有巨人血脉，尚武好战。主持要点：写战神教会与惩罚军团突出「荣誉、战争、巨人血勇」的刚硬气质，与鲁恩的阴柔守夜形成阵营张力。","category":"势力","tags":["战神教会","惩罚军团","弗萨克","巴德海尔"],"alwaysInclude":false,"priority":"high"},{"title":"知识与智慧之神教会（白塔）","content":"知识与智慧之神教会尊奉知识与智慧之神赫拉伯根（白塔途径，原空想之龙的从神智慧之龙），以知识、学院与图书馆为根基。其信仰与伦堡等国相连，教会办有学术机构，非凡者走读者—白塔一脉，速读、记忆与知识检索见长。规则要点：知识与智慧之神与永恒烈阳、风暴之主互相敌视，却与黑夜、战神阵营对立；其「知识即权柄」决定了教会偏重教育与情报。主持要点：写该教会突出书卷、学院与「懂的多便能做的多」的智性冷感。","category":"势力","tags":["知识与智慧之神教会","赫拉伯根","白塔","学院"],"alwaysInclude":false,"priority":"high"},{"title":"大地母神教会（母亲途径）","content":"大地母神教会尊奉大地母神莉莉丝（母亲途径，原巨人王时代的丰收女神，吸血鬼始祖），圣徽以麦穗、鲜花、泉水簇拥婴儿，象征丰饶与孕育。其信仰以费内波特王国为根基，非凡者走耕种者—母亲一脉，主掌生命、丰产与治愈。规则要点：大地母神在第四纪末反水、与黑夜女神联手击杀战神，是七神关系中的变数；其与吸血鬼、月亮途径渊源极深。主持要点：写该教会突出「土地、孕育、母性」的温厚下暗藏古老血统的复杂感。","category":"势力","tags":["大地母神教会","莉莉丝","母亲途径","费内波特"],"alwaysInclude":false,"priority":"high"},{"title":"蒸汽与机械之神教会（万机之神）","content":"蒸汽与机械之神教会尊奉蒸汽与机械之神（通识者途径，又称工匠之神、万机之神），尊名本质的化身、工匠的守护者、技术的光辉。其教会曾获第五纪首份公开神谕，与因蒂斯帝国深度绑定，是工业与科技的守护者。武装机械之心擅机关、枪械、蒸汽动力与封印物操作，另有风纪官负责稽查教内外非凡罪案。规则要点：工匠之神诞生较晚（第四纪工匠成神），势力偏弱但技术感最强；其科技是第五纪质感的来源，每件器械都带负面效应。主持要点：写蒸汽教会突出流程、审批与器械的冷感。","category":"势力","tags":["蒸汽与机械之神教会","工匠之神","机械之心","工业"],"alwaysInclude":false,"priority":"high"},{"title":"玫瑰学派（母神侧学术结社）","content":"玫瑰学派是南大陆与费内波特一带的隐秘学术结社，与大地母神、母亲途径渊源深厚，主张通过「繁衍与欲望的调和」理解生命与神秘。学派内部派系复杂，部分走向堕落、与欲望母树污染牵连，部分保持学术中立。规则要点：玫瑰学派是第五纪台面下重要的隐秘组织之一，与生命学派、淳朴者存在理念与人员交错；其「玫瑰」象征生命与诱惑的双重性。主持要点：写玫瑰学派突出「以爱欲与生命为修行」的暧昧与危险，避免写成单纯邪教。","category":"势力","tags":["玫瑰学派","大地母神","母神侧","学术结社"],"alwaysInclude":false,"priority":"medium"},{"title":"淳朴者（玫瑰学派分支）","content":"淳朴者是玫瑰学派衍生的分支或同脉组织，理念偏向回归自然、质朴与本真的生命状态，与草原游牧及南大陆土著信仰有交集。其成员多以「淳朴」自居，反对过度文明与欲望异化，修行贴近母亲途径的自然权柄。规则要点：淳朴者与玫瑰学派主体若即若离，立场在隐秘组织与民间信仰之间摇摆；其存在丰富了南大陆与草原的超凡生态。主持要点：写淳朴者突出「返璞、自然、与土地共生」的质朴气质，与都市教会的繁复形成对照。","category":"势力","tags":["淳朴者","玫瑰学派","自然","南大陆"],"alwaysInclude":false,"priority":"medium"},{"title":"心理炼金会（隐秘之主侧）","content":"心理炼金会是隐秘之主侧的隐秘组织，以「心灵炼金」为名行人体实验与精神操控之实，渗透贵族沙龙与心理学界。其成员多为观众—空想家一脉，擅长读心、暗示与编织现实。规则要点：心理炼金会是第五纪台面下最危险的隐秘组织之一，与塔罗会长期博弈、后被逐步策反瓦解；其实验狂人特质使其成为「人体实验」案的最佳火种。主持要点：写心理炼金会突出「优雅外表下的冷酷实验」，贵族沙龙里的微笑与背后的手术刀形成反差。","category":"势力","tags":["心理炼金会","隐秘之主","实验","观众"],"alwaysInclude":false,"priority":"high"},{"title":"生命学派（学术结社）","content":"生命学派是源起神秘的学术结社，专注生命、灵性与演化之研究，与母亲、月亮等途径牵连，亦正亦邪。学派成员多为学者型非凡者，游走于教会与隐秘组织之间，既追求知识也常卷入争斗。规则要点：生命学派持有如概率之骰（怪物途径唯一性）等高位非凡物品，是多方争夺的对象；其与玫瑰学派、淳朴者在生命理念上交错。主持要点：写生命学派突出「求知不问立场」的学术冷感与派系倾轧。","category":"势力","tags":["生命学派","学术","生命","结社"],"alwaysInclude":false,"priority":"medium"},{"title":"灵教团（南大陆死神遗脉）","content":"灵教团是南大陆的隐秘组织，奉死神（冥皇萨林格尔）遗脉与亡灵权柄为信仰，与死神教会、拜朗帝国废墟一脉相连。其成员多走收尸人—死神一脉，操弄亡灵、门户与幽界。规则要点：灵教团是南大陆战乱与超凡事件频发的推手之一，与玫瑰学派、极光会等在南大陆角力；死神陨落制造的狂暴海隔断了南北大陆，使南大陆秩序更脆弱。主持要点：写灵教团突出「死亦有序、亡灵低语」的阴森与南大陆的乱世感。","category":"势力","tags":["灵教团","死神","南大陆","亡灵"],"alwaysInclude":false,"priority":"medium"},{"title":"拜亚姆与死神教会遗脉","content":"拜亚姆是罗思德群岛的核心城市，南大陆与殖民航线的枢纽，与死神教会、拜朗帝国遗脉及灵教团纠缠不清。死神萨林格尔建立的拜朗帝国虽已崩解，其信仰与权柄残脉仍在拜亚姆一带流转。规则要点：拜亚姆是出海线与隐秘组织的交汇点，海盗、私掠、殖民与死神遗脉在此交织；鲁恩等列强的殖民网络将其卷入大棋局。主持要点：写拜亚姆突出「殖民港口的喧嚣与死神低语并存」的异域乱局。","category":"势力","tags":["拜亚姆","死神教会","罗思德群岛","南大陆"],"alwaysInclude":false,"priority":"medium"},{"title":"罗塞尔教团（藏第二块石板之古老组织）","content":"罗塞尔教团是罗塞尔大帝时代遗留的古老组织网络，与「第二块亵渎石板藏于某个古老组织」的警示直接相关。其成员多为罗塞尔理念的追随者与守护者，横跨因蒂斯军政与神秘学界。规则要点：罗塞尔教团是各方争夺第二块石板的关键节点，贝尔纳黛等罗塞尔血脉与之牵连；其存在使罗塞尔日记的真相成为长线伏笔。主持要点：写罗塞尔教团突出「守护与秘密」的双重性，其据点往往藏有改变棋局的密钥。","category":"势力","tags":["罗塞尔教团","第二块亵渎石板","罗塞尔","古老组织"],"alwaysInclude":false,"priority":"high"},{"title":"夜幕使徒与夜之隐修会","content":"夜幕使徒（夜之隐修会相关）是侍奉黑夜侧隐秘存在的组织，与黑夜女神教会的正统若即若离，部分分支甚至牵涉异端。夜之隐修会是更古老的隐秘结社，崇拜夜的混沌面，莱昂纳德等人物身上便带有其相关秘密。规则要点：夜之隐修会与教会正统的张力是廷根小队暗线的源头之一；其「夜」的权柄介于守夜与混沌之间。主持要点：写夜幕使徒突出「隐于夜色、身份成谜」的暧昧，与值夜者的光明守夜形成暗面映照。","category":"势力","tags":["夜幕使徒","夜之隐修会","黑夜侧","隐秘"],"alwaysInclude":false,"priority":"medium"},{"title":"秘密教团（拜旧日者）","content":"秘密教团泛指那些直接崇拜旧日或外神、试图引其降临的疯子型隐秘组织，与极光会、魔女教派等同属异端阵营。其成员多被旧日呓语侵蚀，以献祭与仪式呼应上位存在，是灵性污染的高危源头。规则要点：秘密教团与教会长期暗战，是「降临时刻」类大事件的主要策动者；其疯狂使任何接触都极具风险。主持要点：写秘密教团只写其痕迹与后果——畸形信徒、被改写的现实、不可名状的祭坛，不写其全貌。","category":"势力","tags":["秘密教团","旧日","外神","异端"],"alwaysInclude":false,"priority":"medium"},{"title":"所罗门帝国（黑皇帝政权）","content":"所罗门帝国是第四纪众神纪元最早的强力政权，由所罗门在真实造物主与救赎蔷薇支持下成为黑皇帝所建（112—396年），后黑皇帝陨落；510年黑皇帝凭借黑皇帝途径特殊性复活归来，建立所罗门第二帝国（510—1047）。黑皇帝途径序列0具「规则与复活」权柄，使所罗门成为不死般的统治者。规则要点：所罗门帝国是第四纪权力游戏的起点，其覆灭与复活直接引发后续三帝国鼎立与四皇之战；支持所罗门的贵族在四皇之战后被七神支持的四大贵族追杀。主持要点：写所罗门线突出「黑皇帝的规则铁律与不死执念」。","category":"势力","tags":["所罗门帝国","黑皇帝","所罗门","第四纪"],"alwaysInclude":false,"priority":"high"},{"title":"图铎—特伦索斯特联合帝国","content":"图铎—特伦索斯特联合帝国是第四纪中期的双执政官政权（396—510年），由亚利斯塔·图铎与特伦索斯特在六神支持下反叛所罗门后建立，二人同为黑皇帝途径天使，共掌北大陆。后因黑皇帝复活归来、二人面临失去序列1特性之险，分别转途径：特伦索斯特转审判者建特伦索斯特帝国（夜皇），图铎转红祭司建图铎帝国（血皇帝）。规则要点：联合帝国的分裂催生了四皇格局，是北大陆诸国（鲁恩、奥拉维夫等）贵族谱系的源头。主持要点：写联合帝国突出「双执政官的权柄交接与背叛伏笔」。","category":"势力","tags":["图铎","特伦索斯特","联合帝国","双执政官"],"alwaysInclude":false,"priority":"high"},{"title":"四皇与四皇之战各方","content":"第四纪末的「四皇」指南北大陆四足鼎立的四位序列0皇帝：黑皇帝所罗门（所罗门第二帝国）、血皇帝亚利斯塔·图铎（图铎帝国，红祭司）、夜皇特伦索斯特（特伦索斯特帝国，审判者）、冥皇萨林格尔（拜朗帝国死神）。四皇互相掣肘、摩擦不断，1047—1052年四皇之战爆发，黑、血、夜三皇依次陨落，冥皇攫取最大好处。规则要点：四皇之战后七神支持特伦索斯特四大贵族（艾因霍恩、奥古斯都、索伦、卡斯蒂亚）瓜分北大陆，奠定第五纪四国格局；冥皇虽胜却埋下苍白之灾的祸根。主持要点：写四皇突出「神明亦如凡人争雄」的史诗感。","category":"势力","tags":["四皇","黑皇帝","血皇帝","夜皇","冥皇"],"alwaysInclude":false,"priority":"high"},{"title":"隐秘组织总览：夜之隐修会等","content":"第五纪台面下的隐秘组织千头万绪，按渊源可归类：异端崇拜类（极光会、魔女教派、秘密教团，拜真实造物主或旧日）；学术结社类（心理炼金会、生命学派、摩斯苦修会、玫瑰学派、淳朴者）；遗脉类（灵教团、拜亚姆死神遗脉、罗塞尔教团）；夜之侧（夜之隐修会、夜幕使徒）。规则要点：隐秘组织与七大教会千年暗战，低序列冲突在民间进行，高序列出手即组织战争；各组织间亦互相渗透利用。主持要点：让玩家隶属或触碰其中一方边缘，是引入大事件最顺滑的钩子，但要守住「高层冷战」的默契。","category":"势力","tags":["隐秘组织","极光会","魔女教派","总览"],"alwaysInclude":false,"priority":"high"},{"title":"贝克兰德上层沙龙与贵族神秘学圈","content":"贝克兰德的上层社会流行沙龙与神秘学话题，贵族、学者、军官在华丽客厅里交换情报、追逐禁忌知识，心理炼金会等隐秘组织借此渗透。这一圈子是教会政治、隐秘组织与王室阴谋的交汇层。规则要点：塔罗会成员奥黛丽即出身此类沙龙，其「正义」身份正是此圈的缩影；贵族的好奇心既是线索源也是陷阱。主持要点：写沙龙戏突出「体面下的暗流」——一杯红茶里搅动着魔药配方与背叛，用浮华衬非凡。","category":"势力","tags":["贝克兰德","沙龙","贵族","神秘学圈"],"alwaysInclude":false,"priority":"medium"},{"title":"费内波特王国（大地母神国）","content":"费内波特王国位于北大陆，是大地母神教会的核心信仰国，国民多奉母亲途径的丰饶与孕育之信仰。其内政长期受大地母神教会深度影响，曾经历背誓之战（738—743年），战后王国内部仅余大地母神教会独大。规则要点：费内波特与鲁恩、因蒂斯等列强互为邻敌，其农业与生命权柄使其在列强博弈中偏「守成」；大地母神在第四纪末的反水使其地位微妙。主持要点：写费内波特突出「土地与母性」的温厚下暗藏古老血统与教会干政。","category":"地理","tags":["费内波特","大地母神","北大陆","王国"],"alwaysInclude":false,"priority":"medium"},{"title":"弗萨克帝国（战神之国）","content":"弗萨克帝国位于北大陆北境，是战神教会（惩罚军团）的国度，国民带有巨人血脉，尚武好战、国势彪悍。古弗萨克语是第四纪人类通用语，为当代诸语言的源头，源于巨人语。规则要点：弗萨克与鲁恩为宿敌，是克莱恩时代世界大战的主要对手；其战神教会的荣誉战争气质塑造了帝国的扩张性。主持要点：写弗萨克突出「巨人之血、冰原与军鼓」的刚硬，与鲁恩的阴柔雾都形成阵营对照。","category":"地理","tags":["弗萨克","战神","巨人血脉","北大陆"],"alwaysInclude":false,"priority":"medium"},{"title":"伦堡（知识与智慧之神侧）","content":"伦堡是位于北大陆的国家，与知识与智慧之神教会（白塔）渊源深厚，国民偏重学术、语言与治理，罗塞尔时代曾被纳入因蒂斯的保护圈。其语言与文字传统使伦堡成为情报与文书的枢纽。规则要点：伦堡在列强博弈中常处缓冲与附庸位置，其白塔信仰决定了偏智性的国力结构。主持要点：写伦堡突出「书卷、外交与语言」的智性冷感，区别于邻国的尚武或尚商。","category":"地理","tags":["伦堡","知识与智慧之神","北大陆","缓冲国"],"alwaysInclude":false,"priority":"low"},{"title":"塞卡玛霍恩（塞加尔）","content":"塞卡玛霍恩（塞加尔）是北大陆的国家之一，在第四纪后的列强格局中与鲁恩、因蒂斯、弗萨克、伦堡、费内波特并列，受七神教会与各国博弈牵制。规则要点：作为北大陆中等列强，其立场常在几大阵营间摇摆，是外交与间谍活动的温床。主持要点：写塞加尔突出「夹缝中的小国」处境，其首都与外交圈常为暗线交易的舞台。","category":"地理","tags":["塞卡玛霍恩","塞加尔","北大陆","列强"],"alwaysInclude":false,"priority":"low"},{"title":"奥拉维夫","content":"奥拉维夫是北大陆的国家之一，其贵族谱系可追溯至四皇之战后七神支持的特伦索斯特四大贵族（艾因霍恩、奥古斯都、索伦、卡斯蒂亚）瓜分北大陆的格局。规则要点：奥拉维夫与鲁恩等国的王室、教会势力盘根错节，是北大陆权力版图的组成块。主持要点：写奥拉维夫突出其「旧贵族谱系与当代宪政」的交错，作为北大陆政治生态的样本。","category":"地理","tags":["奥拉维夫","北大陆","贵族谱系","列强"],"alwaysInclude":false,"priority":"low"},{"title":"鲁恩王国（黑夜女神国）","content":"鲁恩王国是北大陆最强大的国家之一，以黑夜女神教会为国教，实行君主立宪，国力涵盖工业、殖民与海军。其疆域含廷根、贝克兰德等核心城市，是克莱恩故事的主舞台。规则要点：鲁恩与弗萨克为宿敌、与因蒂斯竞逐殖民，黑夜女神教会的势力渗透军政市井；其君主立宪下的议会、报纸与情报网构成雾都政治的肌理。主持要点：写鲁恩突出「雾、煤气灯、绅士礼帽与帝国野心」的蒸汽帝国质感。","category":"地理","tags":["鲁恩","黑夜女神","君主立宪","北大陆"],"alwaysInclude":false,"priority":"medium"},{"title":"因蒂斯帝国（蒸汽与机械之神侧）","content":"因蒂斯是南向的强国（法兰西风味），罗塞尔大帝的发迹之地，与蒸汽与机械之神教会深度绑定。罗塞尔于此推动工业革命、改共和后又称帝国，白枫宫为其权力象征。原因蒂斯王族索伦家族参与弑帝。规则要点：因蒂斯在罗塞尔后成为工业与科技强国，与鲁恩竞逐殖民与海权；其工匠之神信仰塑造了技术立国的气质。主持要点：写因蒂斯突出「共和与帝国更迭、工业轰鸣与白枫宫血迹」的法兰西式波澜。","category":"地理","tags":["因蒂斯","蒸汽与机械之神","罗塞尔","南大陆"],"alwaysInclude":false,"priority":"medium"},{"title":"北大陆势力格局总览","content":"第五纪北大陆由七神教会与四至数个大国的格局主导：鲁恩（黑夜女神）、弗萨克（战神）、因蒂斯（蒸汽与机械之神）、费内波特（大地母神）为四大信仰—国家耦合体，伦堡（知识与智慧之神）、塞卡玛霍恩、奥拉维夫等国为缓冲与附庸。七神彼此结盟又敌对：永恒烈阳、风暴之主、知识与智慧之神互相敌视；黑夜女神与战神水火不容。规则要点：这种「教会—国家」双重耦合使任何大事件都牵一发动全身；列强博弈在大战中总爆发。主持要点：写北大陆突出「势力如棋盘、信仰即国界」的复杂张力。","category":"势力","tags":["北大陆","势力格局","七神","列强"],"alwaysInclude":false,"priority":"high"},{"title":"草原游牧势力","content":"北大陆内陆草原地带盘踞着游牧民族势力，与定居列强的教会政治若即若离，其信仰与习俗多贴近自然、战神或母亲途径的质朴权柄，淳朴者等组织与之有交集。草原势力以骑射、迁徙与部落联盟为特征，是列强扩张难以彻底征服的变量。规则要点：草原在第五纪是北大陆权力版图的边缘活棋，其超凡生态以自然与战争权柄为主。主持要点：写草原突出「长风、马群与部落萨满」的苍茫，与都市教会的繁复形成对照。","category":"势力","tags":["草原","游牧","北大陆","部落"],"alwaysInclude":false,"priority":"low"},{"title":"殖民帝国与海外殖民地","content":"第五纪列强竞相海外殖民，鲁恩、因蒂斯、弗萨克等将权柄延伸至南大陆、罗思德群岛与诸海域，殖民网络与苏尼亚海等航线构成出海线。殖民地既是原料与魔药材料的来源，也是隐秘组织、海盗与教会角力的外延。规则要点：殖民扩张使非凡事件从北大陆蔓延至全球，出海成为序列晋升材料的经典来源；殖民地的秩序远比本土脆弱。主持要点：写出海戏先写「港口、帆影与异域低语」，殖民地的混乱正是非凡者的机遇场。","category":"地理","tags":["殖民","海外","殖民地","出海线"],"alwaysInclude":false,"priority":"medium"},{"title":"苏尼亚海海盗与海盗将军","content":"苏尼亚海及诸海域盘踞着海盗势力，海盗将军是其中位高权重者，多走水手—暴君或与死神、异种相关的途径，劫掠商路、与隐秘组织交易。海盗是出海线与殖民地秩序的最大破坏者，也是魔药材料与封印物的流动黑市。规则要点：黄金梦想号等传奇海盗船、海盗将军的悬赏是海上剧情的经典钩子；其与风暴教会、列强的私掠形成微妙平衡。主持要点：写海盗突出「自由、血腥与海风的咸腥」，但每位将军背后都牵着上位存在的线。","category":"势力","tags":["苏尼亚海","海盗","海盗将军","海上"],"alwaysInclude":false,"priority":"medium"},{"title":"黄金梦想号与出海线","content":"黄金梦想号是海上著名的海盗船之一，活跃于苏尼亚海与殖民航线，承载出海线的大量剧情（猎杀海盗、追寻材料、遭遇隐秘组织）。其航行串联起港口城市、殖民孤岛与神弃之地的边缘。规则要点：出海线是克莱恩中期（旅行家卷）的主舞台，黄金梦想号式的船只既是机遇也是绞索；船上的非凡者与封印物是海上博弈的筹码。主持要点：写出海戏以「船、海图与未知彼岸的低语」为基调，让海洋成为另一种灵界。","category":"势力","tags":["黄金梦想号","出海","海盗船","航线"],"alwaysInclude":false,"priority":"medium"},{"title":"教会学院与非凡教育","content":"七大教会办有神学院与学术机构（如知识与智慧之神教会的白塔式学院、黑夜女神教会的教义与仪式训练），承担非凡知识的系统性传授与非凡者筛选。中低序列者可经教会学院或师徒制习得配方、材料与仪式。规则要点：教会教育是配方共享的渠道，却也服务于「培育信仰之锚」的隐秘目的；野途径者因缺教育而更易失控。主持要点：写学院戏突出「知识即权柄、亦为枷锁」——学得的每份知识都绑定对教会的忠诚。","category":"设定","tags":["教会学院","非凡教育","白塔","配方"],"alwaysInclude":false,"priority":"low"},{"title":"第二纪·五大古神与种族阵营","content":"第二纪黑暗纪元是超凡种族觉醒、古神现世的时代。八大古神先后登场：巨人王奥尔米尔（黄昏巨人）、精灵王苏尼亚索列姆（暴君）、空想之龙安格尔威德（空想家）、不死鸟始祖格蕾嘉莉（死神）、吸血鬼始祖莉莉丝（月亮/母亲）、毁灭魔狼弗雷格拉（黑暗）、异种王克瓦希图恩（被缚者）、恶魔君王法布提（深渊）。其后泛人类阵营（人类、巨人、精灵、血族）与非人阵营（恶魔、魔狼、异种、巨龙）对立。因背叛，血族、异种王、魔狼先后陨落，阵营重组。规则要点：第二纪的阵营旧账是后世古神遗产、地底遗迹动机的深层来源；正神教会与精灵族对本纪历史各执一词，是「历史由胜利者书写」的第一样本。","category":"年表","tags":["第二纪","古神","八大古神","种族阵营"],"alwaysInclude":false,"priority":"high"},{"title":"第三纪·光辉年代与远古太阳神统治","content":"第三纪在官方叙事中称光辉纪元，真实历史则揭其为灾变纪元的前半。光辉年代由远古太阳神统治，光照诸国，是旧日之后世界难得的秩序时代。太阳神座下天使之王（空想天使亚当、时天使阿蒙、纯白天使奥赛库斯、风天使列奥德罗、智天使赫拉伯根、红天使梅迪奇、命运天使乌洛琉斯、暗天使萨斯利尔）分掌权柄。规则要点：光辉年代是「神迹行走大地」的黄金期，也是此后一切弑神阴谋的底图；白银城保存着未被抹去的光辉记忆。主持要点：写光辉年代突出「全知全能之光的虚假安宁」，为后续崩塌蓄势。","category":"年表","tags":["第三纪","光辉年代","远古太阳神","天使之王"],"alwaysInclude":false,"priority":"high"},{"title":"第三纪·大灾变与救赎蔷薇弑神","content":"第三纪的转折源于堕落——远古太阳神座下天使之王被引诱背叛，酿成大灾变，真实造物主（太阳神人性部分）现世，神弃之地与其他大陆联系被割裂。真相骨架是：救赎蔷薇组织设计弑神，杀死远古太阳神；其身躯被纯白、智、风三位天使之王分食，三者借非凡特性晋升为真神（永恒烈阳、知识与智慧之神、风暴之主）；太阳神的神性在亚当身上苏醒，人性化为真实造物主，成为千年阴谋暗线。规则要点：太阳神之死是万恶与万光之源，此后诸神合法性、教会世仇、亚当布局全回溯于此。主持要点：写大灾变突出「信仰崩塌的连锁」——光熄之后，神与人的关系永久改变。","category":"年表","tags":["第三纪","大灾变","救赎蔷薇","弑神"],"alwaysInclude":false,"priority":"top"},{"title":"第四纪·纷争年代（0—112）","content":"第四纪众神纪元始于纷争年代（0—112年），诸国混战、神灵尚未完全退居幕后。此期是第三纪弑神余波与新生王朝的磨合阶段，所罗门在真实造物主与救赎蔷薇支持下崛起，为黑皇帝政权的建立铺路。规则要点：纷争年代是「神迹仍频繁显现」的过渡，其后所罗门帝国的建立标志众神纪元进入帝国时代。主持要点：写纷争年代突出「无主的权力真空与神之棋子的厮杀」。","category":"年表","tags":["第四纪","纷争年代","0—112","众神纪元"],"alwaysInclude":false,"priority":"medium"},{"title":"第四纪·所罗门帝国年代（112—396）","content":"所罗门在支持者拥戴下成为黑皇帝，建立所罗门帝国（112—396年），凭黑皇帝途径「规则与复活」权柄长期统治北大陆，与真实造物主、救赎蔷薇结盟。其后黑皇帝陨落，帝国崩解，为联合帝国的反叛让路。规则要点：所罗门帝国是众神纪元第一个强力神权帝国，其黑皇帝特性使「复活」成为后续千年纠葛的核心；支持所罗门的贵族在日后被追杀。主持要点：写所罗门年代突出「以规则为律令、以复活为执念」的黑铁皇权。","category":"年表","tags":["第四纪","所罗门帝国","112—396","黑皇帝"],"alwaysInclude":false,"priority":"medium"},{"title":"第四纪·图铎—特伦索斯特联合帝国（396—510）","content":"亚利斯塔·图铎与特伦索斯特在六神支持下反叛所罗门，建立图铎—特伦索斯特联合帝国（396—510年），二人共为黑皇帝途径天使、双执政官共治北大陆。此期是众神纪元中段的相对稳定期，却因黑皇帝复活而归分崩。规则要点：联合帝国的双执政架构与黑皇帝途径的「唯一性」冲突（同途径不可二神）埋下分裂伏笔，直接催生三帝国鼎立。主持要点：写联合帝国突出「双头鹰式的权柄平衡与暗流」。","category":"年表","tags":["第四纪","联合帝国","396—510","双执政官"],"alwaysInclude":false,"priority":"medium"},{"title":"第四纪·黑皇帝复活与三帝国鼎立（510—1047）","content":"黑皇帝所罗门凭借途径特殊性复活归来（510年），建立所罗门第二帝国，与图铎、特伦索斯特形成三帝国鼎立（510—1047年）。为应对失去序列1特性之险，特伦索斯特在六神支持下转审判者途径建特伦索斯特帝国（夜皇），图铎在亚当、阿蒙等帮助下强行转红祭司建图铎帝国（血皇帝，半疯）。同期工匠之神登临神位。规则要点：三帝国鼎立是四皇格局的前奏，途径转换的「相邻/不相邻」规则在此集中体现（审判者为相邻、红祭司为不相邻致疯）。主持要点：写鼎立期突出「神明亦怕失权、不惜改途」的博弈残酷。","category":"年表","tags":["第四纪","黑皇帝复活","三帝国鼎立","510—1047"],"alwaysInclude":false,"priority":"high"},{"title":"四皇之战（1047—1052）","content":"1047年四皇之战爆发，黑皇帝、血皇帝、夜皇、冥皇四位序列0皇帝在五年内依次陨落——血皇帝先陨、黑皇帝再陨、夜皇陨落并封印真实造物主体。冥皇萨林格尔攫取最大好处（获取红祭司唯一性），却也因强行容纳唯一性渐趋疯狂。战后七神支持特伦索斯特四大贵族（艾因霍恩、奥古斯都、索伦、卡斯蒂亚）瓜分北大陆、覆灭皇室、追杀所罗门与图铎余党，奠定第五纪四国格局。规则要点：四皇之战是第四纪的终幕，神明如凡人般互相绞杀，是「序列0亦会死」的铁证。主持要点：写四皇之战以史诗笔法写神陨，突出权柄析出的震动。","category":"年表","tags":["第四纪","四皇之战","1047—1052","神陨"],"alwaysInclude":false,"priority":"high"},{"title":"七神之争（1053—1210）","content":"四皇之战后，原本联盟的七神彼此为敌，进入七神之争（1053—1210年）。诸神借各自的信仰国家互相攻伐，北大陆陷入长期神权冷战与局部战争，直到苍白年代前夕。规则要点：七神之争解释了第五纪初期列强敌对的根源——国家边界即信仰边界；也是「教会不是铁板一块」的历史注脚。主持要点：写七神之争突出「神之战传导为人的战争」，信仰成为最锋利的刀。","category":"年表","tags":["第四纪","七神之争","1053—1210","神权冷战"],"alwaysInclude":false,"priority":"medium"},{"title":"苍白年代（1210—1233）与苍白之灾","content":"七神之争后进入苍白年代（1210—1233年）。末期，冥皇萨林格尔依靠永暗之河强行容纳红祭司唯一性、试图开创旧日途径，却陷入疯狂，与原初魔女奇克合力在北大陆发动「苍白之灾」。七神联手挫败之：冥皇萨林格尔陨落、原初魔女被重创，死神陨落更制造了隔断南北大陆的狂暴海。同期最初屏障出现裂缝，七神将神国移至星界填补。规则要点：苍白之灾是第四纪的终幕惨剧，也是南北大陆割裂的直接原因。主持要点：写苍白之灾以「亡灵与苍白笼罩大地」的末日意象，突出神战的无情。","category":"年表","tags":["第四纪","苍白年代","1210—1233","苍白之灾"],"alwaysInclude":false,"priority":"high"},{"title":"罗塞尔时代（1143—1198）","content":"罗塞尔·古斯塔夫（黄涛）是第二位从源堡苏醒的穿越者，1143年2月中旬苏醒于因蒂斯。他发明蒸汽机、改良帆船，开启工业革命；1173年联手工匠之神教会推翻因蒂斯王国、任共和国首任执政官；1192年底称帝；1198年被永恒烈阳教会、索伦家族等与贵族刺杀于白枫宫，死前散布二十二张亵渎之牌。规则要点：罗塞尔时代是第五纪黑铁纪元的转折，工业与神秘学双重革命重塑世界，其日记与亵渎之牌成为后世各方争夺的圣杯。主持要点：写罗塞尔时代突出「穿越者的雄心与孤独」，其遗产贯穿全书。","category":"年表","tags":["第五纪","罗塞尔时代","1143—1198","工业革命"],"alwaysInclude":false,"priority":"high"},{"title":"第五纪·黑铁纪元分期总览","content":"第五纪称黑铁纪元，即故事「当下」，对应十八至十九世纪蒸汽文明。纪元内分期：初期与战争年代，北大陆在四皇遗产上洗牌，鲁恩、因蒂斯、弗萨克、伦堡、塞卡玛霍恩等国边界与教会格局定型；罗塞尔时代为转折；其后贝克兰德雾都时代（煤气灯、地铁、蒸汽机械与报纸舆论并存，人口爆炸、雾霭蔽日）；克莱恩时代（1349年周明瑞穿越起）卷入世界大战与诸神棋局；终局步入神弃之世。规则要点：黑铁纪元的质感是「蒸汽与神秘共生」。主持要点：写场景先写雾、灯、报纸与礼帽，再让非凡者侧身而行。","category":"年表","tags":["第五纪","黑铁纪元","分期","蒸汽文明"],"alwaysInclude":false,"priority":"medium"},{"title":"贝克兰德雾都时代（克莱恩前中期）","content":"贝克兰德雾都时代是第五纪黑铁纪元的中段，以鲁恩之都贝克兰德为代表：煤气灯、地铁、蒸汽机械与报纸舆论并存，人口爆炸、雾霭蔽日。此期非凡事件密度远超地方城市，价值更高的魔药配方、更大的隐秘组织网、更深的教会政治在此交汇。规则要点：这是克莱恩化名夏洛克·莫里亚蒂开侦探社、塔罗会壮大、晋升无面人—秘偶大师的主舞台；贝克兰德大雾霾等惨剧即发生于此。主持要点：写雾都时代突出「浮华与深渊一体两面」，用市井衬非凡。","category":"年表","tags":["第五纪","贝克兰德","雾都时代","克莱恩"],"alwaysInclude":false,"priority":"medium"},{"title":"廷根事件·真实造物主降临（1349）","content":"1349年克莱恩穿越不久，廷根发生真实造物主降临事件：叛徒因斯·赞格威尔为晋升半神，策划邪神子嗣污染全城，企图借真实造物主降临攫取权柄。值夜者小队与之死战，队长邓恩·史密斯与老尼尔等牺牲，克莱恩被杀后凭源堡复活、伪造死亡离镇。规则要点：廷根是全书情感锚点，小队之殇是悲剧核心；真实造物主与极光会在此显露獠牙。主持要点：玩家可身处其侧、受波及、留名外围，但邓恩与老尼尔的牺牲按原著执行，不得改写。","category":"年表","tags":["第五纪","廷根事件","真实造物主","1349"],"alwaysInclude":false,"priority":"high"},{"title":"世界大战（鲁恩vs弗萨克）","content":"克莱恩时代的世界大战是第五纪列强矛盾的终极爆发，以鲁恩与弗萨克为主敌，诸国依信仰阵营选边，半神与天使级战力正面碰撞，普通人在炮火与诡秘中浮沉。战争既是国家争霸，也是诸神借代理人清算世仇的舞台。规则要点：大战期间神战（如战神之死）悄然进行，非凡之上的博弈透过战争显形；平民的苦难是这一节点的沉重底色。主持要点：写大战先写征兵、物价与报纸号外，再让非凡战力在战线侧身，惨烈如实而不猎奇。","category":"年表","tags":["第五纪","世界大战","鲁恩","弗萨克"],"alwaysInclude":false,"priority":"high"},{"title":"第五纪神战·战神之死","content":"克莱恩时代的大战中，战神巴德海尔联合大地母神进攻黑夜女神，关键时刻大地母神反水，战神陨落——其序列0黄昏巨人权柄析出，成为诸方争夺的焦点，也标志七神格局的重组。此战是第五纪少有的真神级陨落，震动北大陆。规则要点：战神之死解释了第五纪后期列强与教会力量对比的剧变，也是「同途径唯一性」博弈的实例。主持要点：写神战以「神国之崩与权柄坠地」的宏大写神陨，凡人视角只见天象异变与半神厮杀。","category":"年表","tags":["第五纪","神战","战神之死","巴德海尔"],"alwaysInclude":false,"priority":"high"},{"title":"克莱恩时代时间线总览（1349—）","content":"克莱恩时代自1349年周明瑞穿越成廷根的克莱恩·莫雷蒂起：转运仪式意外激活源堡→假扮愚者创立塔罗会→值夜者廷根历练→廷根小队之殇与假死离镇→调任贝克兰德、化名夏洛克·莫里亚蒂开侦探社、晋升小丑至无面人→贝克兰德大雾霾亲历→化名格尔曼·斯帕罗出海、猎杀海盗、晋升秘偶大师→深入神弃之地收德里克入会→遭遇时天使阿蒙、晋升诡法师→卷入诸神棋局与世界大战→最终登临序列0愚者。规则要点：玩家嵌于这条时间线，大事件时序与人物命运按原著，玩家只改自己份内。主持要点：以克莱恩命运线为「大势锚」，玩家在其侧书写自己的篇章。","category":"年表","tags":["第五纪","克莱恩时代","1349","时间线"],"alwaysInclude":false,"priority":"high"},{"title":"克莱恩登临序列0愚者","content":"克莱恩沿占卜家途径自序列9逐级攀升，终以凡人之躯登临序列0愚者，融合相邻途径权柄成就半旧日「诡秘之主」。其登神的关键是以自身为锚，对抗上古意识复苏与外神入侵，为人类守住生机。规则要点：愚者信仰的「凡人造神」闭环在此完成——克莱恩既是神也是自己信仰的第一位信徒；其登临是原著终局的核心转折。主持要点：写登神突出「孤独的锚与诡秘的权柄合一」，玩家可旁观或承其业，但不得改写原人物结局。","category":"年表","tags":["第五纪","克莱恩","序列0愚者","登神"],"alwaysInclude":false,"priority":"high"},{"title":"神弃之世与终局对抗天尊·旧日","content":"终局步入神弃之世：最初屏障破损、旧日复苏与外神渗透加剧，天尊（福生玄黄天尊）的上古意识亦图夺回源堡与灰雾。克莱恩以诡秘之主之姿，联合各方对抗天尊复苏、旧日争夺与外神入侵，为人类守住生机后陷入沉睡。规则要点：这是全书的终极危机层，旧日、外神、天尊三条线收束；凡人视角的故事在此抵达序列之上的边界。主持要点：写终局保持「不可名状的克制」——天尊与旧日只作远景、呓语与污染，绝不让玩家正面对线。","category":"年表","tags":["终局","神弃之世","天尊","旧日复苏"],"alwaysInclude":false,"priority":"high"},{"title":"源堡之争与阿蒙的追猎","content":"源堡是占卜家途径的源质，亦为灰雾之上的权柄核心，是阿蒙（错误途径天使王）千年觊觎的目标——其本质欲望是窃取源堡与灰雾权柄、向旧日攀升。阿蒙以「时之虫」「分身」与「扮演」潜伏于历史与现实，多次追猎克莱恩。规则要点：源堡之争是贯穿全书的高层暗线，阿蒙的可怕在于「你无法证明你是你」；其痕迹与后果远多于全貌。主持要点：写阿蒙只写其痕迹与后果——错位的身份、被偷走的存在，不写其全貌。","category":"年表","tags":["源堡之争","阿蒙","追猎","错误途径"],"alwaysInclude":false,"priority":"medium"},{"title":"诡秘之主终局·外神入侵与屏障","content":"全书终局的更深层威胁是外神入侵：最初屏障因破损而裂缝频生，宇宙深处的外神伺机渗透，星空污染加剧。七神曾将神国移至星界填补裂缝，而克莱恩以诡秘之主之姿成为屏障存续的关键锚点。规则要点：外神入侵是旧日复苏之上的终极危机，亦是「星空伟大又危险」的终极注脚；其具象须保持不可名状。主持要点：写终局外神以「屏障将碎、星空凝视」的末日压迫感，凡人只觉异象，真相藏于高层。","category":"年表","tags":["终局","外神入侵","屏障","星空"],"alwaysInclude":false,"priority":"high"},{"title":"门途径全序列（学徒）","content":"门途径对应塔罗牌「门」，序列0为「门」，属源堡阵营，主打空间、旅行与传送，是学徒非凡者的本命路线。已知低序列为：序列9学徒——灵性感知与初步空间亲和；序列8戏法大师——戏法般的位移与操控；序列7占星人——借星灵体观测与远程感知；序列5旅行家——跨空间行走；序列4秘法师——折叠空间、辟出秘境；序列3旅法师——自由穿梭灵界与现实；序列2星之匙——执掌空间之钥。机制要点：门途径与偷盗者、占卜家同属源堡组，相邻可互吃魔药但不优；高序列被星空污染困扰（如0-61旧日之盒带星空污染）。扮演核心是成为「行走于门后的旅人」，敬畏空间的不可知。中段序列名称按教会机密逐层揭示，升级时给足代价。","category":"规则","tags":["门途径","学徒","全序列","源堡"],"alwaysInclude":false,"priority":"high"},{"title":"魔女途径全序列（刺客）","content":"魔女途径对应塔罗牌「魔女」，序列0为「原初魔女」，属欲望母树侧（暗影世界、深渊、被缚者分组），主打刺杀、诱惑与灾祸。已知低序列为：序列9刺客——隐袭与一击必杀；序列8教唆者——煽动与误导；序列7女巫——诅咒与变形；序列6欢愉——以欲望为刃、魅惑与折磨。机制要点：魔女途径高层多为女性化权柄（原初魔女奇克即第四纪登临的魔女真神），能力兼具「诱惑与毁灭」双重性，污染常表现为欲望膨胀与身份异化；与异种、深渊途径相邻。扮演核心是成为「以美丽与灾祸同行的存在」。中段序列名称（密巫等）按教会机密逐层揭示。","category":"规则","tags":["魔女途径","刺客","原初魔女","全序列"],"alwaysInclude":false,"priority":"high"},{"title":"战神途径全序列（战士/黄昏巨人）","content":"战神途径对应塔罗牌「战神」（黄昏巨人），序列0为「战神」（黄昏巨人），属混沌海组，主打战争、荣耀与巨人血勇，是弗萨克战神教会的正统途径。已知低序列为序列9战士——强化体魄与战技；其上逐步获得荣耀、征服与战争规则权柄，序列4以上为半神级（荣耀者、征服者等），序列0执掌战争与黄昏权柄。机制要点：战神与黑夜、太阳等途径同属混沌海组，序列3以上可互换；其权柄「战争」是规则级，战场即其领域。扮演核心是成为「荣耀的战士」，消化靠守护与征伐的契合。中段序列名称按教会机密逐层揭示。","category":"规则","tags":["战神途径","战士","黄昏巨人","全序列"],"alwaysInclude":false,"priority":"high"},{"title":"母亲途径全序列（耕种者）","content":"母亲途径对应塔罗牌「母亲」，序列0为「母亲」（大地母神莉莉丝），属母巢组（暗影世界、深渊、被缚者分组之对侧），主打生命、丰产与治愈，是大地母神教会的正统途径。已知低序列为：序列9耕种者——与土地和作物亲和；序列8采药人——辨识与调和灵性植物；序列7丰收祭司——祈求丰产、主持孕育仪式。机制要点：母亲途径与月亮、死神等生命—终结权柄邻近，高层执掌「孕育与丰饶」的规则；其治愈与生命权柄使教会具温厚底色，却暗藏吸血鬼始祖的血统复杂。扮演核心是成为「大地的哺育者」。中段序列名称按教会机密逐层揭示。","category":"规则","tags":["母亲途径","耕种者","大地母神","全序列"],"alwaysInclude":false,"priority":"high"},{"title":"月亮途径全序列（药师）","content":"月亮途径对应塔罗牌「月亮」，序列0为「月亮」，与母亲、大地母神渊源极深（黑夜女神亦兼掌部分月亮权柄），主打药剂、驯化与月亮辉光。已知低序列为：序列9药师——调配治疗与增益药剂；序列8驯兽师——感应与驯化兽群。机制要点：月亮途径高层执掌「召唤与月光」权柄，与吸血鬼（莉莉丝一脉）的月亮特性同源；吉达斯曾因月亮是「召唤」权柄而被视为威胁被杀死，可见其高危。扮演核心是成为「调和生命与月辉的医者」。中段序列名称按教会机密逐层揭示，升级时给足代价。","category":"规则","tags":["月亮途径","药师","月亮","全序列"],"alwaysInclude":false,"priority":"high"},{"title":"黑皇帝途径全序列（律师）","content":"黑皇帝途径对应塔罗牌「黑皇帝」，序列0为「黑皇帝」，属混沌之子侧（失序之国、黑皇帝、审判者分组），主打规则、律令与复活，是所罗门帝国的正统途径。已知低序列为序列9律师——以言辞与契约影响现实。机制要点：黑皇帝途径的序列0具「规则即律令、违者受罚」与「可复活」双重权柄，使所罗门成为不死般的统治者；同途径只能有一位序列0，故黑皇帝复活即引发诸皇混战。与审判者途径相邻（特伦索斯特转审判者为相邻转途）。扮演核心是成为「制定规则之人」，消化靠秩序与律令的掌控。中段序列名称按教会机密逐层揭示。","category":"规则","tags":["黑皇帝途径","律师","所罗门","全序列"],"alwaysInclude":false,"priority":"high"},{"title":"审判者途径全序列（仲裁人）","content":"审判者途径对应塔罗牌「审判者」，序列0为「审判者」，属混沌之子侧（失序之国、黑皇帝、审判者分组），主打秩序、裁决与律法，是特伦索斯特帝国（夜皇）的正统途径。已知低序列为：序列9仲裁人——调解与裁决；序列8治安官——维护秩序、执法；序列7审讯者——拷问与逼供；序列6法官——依律判决、具强制力；其上为半神与序列0审判者。机制要点：审判者与黑皇帝相邻（夜皇转审判者为相邻转途），其权柄「裁决」是规则级；0-02特伦索斯特黄铜书即受失序之国污染的审判者唯一性。扮演核心是成为「公正的裁决者」，消化靠秩序与正义的契合。","category":"规则","tags":["审判者途径","仲裁人","夜皇","全序列"],"alwaysInclude":false,"priority":"high"},{"title":"隐者途径全序列（秘祈人）","content":"隐者途径对应塔罗牌「隐者」，序列0为「隐者」，属知识荒野组，主打隐秘知识、窥秘与灵性指引。已知低序列为序列9秘祈人——祈求与沟通隐秘存在、获取片段知识。机制要点：隐者途径与窥秘人等邻近，高层执掌「隐秘与知识」的权柄，多游走于教会与隐秘组织边缘；其能力危险在于「知晓不该知晓者」即被污染。扮演核心是成为「探索隐秘而不迷失的求道者」，消化靠对知识的克制与敬畏。中段序列名称（如窥秘人相关高阶）按教会机密逐层揭示，升级时给足代价。","category":"规则","tags":["隐者途径","秘祈人","隐者","全序列"],"alwaysInclude":false,"priority":"medium"},{"title":"命运之轮途径全序列（怪物）","content":"命运之轮途径对应塔罗牌「命运之轮」，序列0为「命运之轮」，属命运编织者侧，主打命运、概率与预言。已知低序列为序列9怪物——以「直觉」感知吉凶、被命运拨弄。机制要点：命运之轮途径与偷盗者（命运木马、时之虫）同源命运权柄，高层可编织与改写命运；概率之骰（怪物途径唯一性）即其序列0唯一性载体，现归生命学派。扮演核心是成为「顺应或拨动命运之轮者」，消化靠对宿命的理解。中段序列名称按教会机密逐层揭示，升级时给足代价。","category":"规则","tags":["命运之轮途径","怪物","命运","全序列"],"alwaysInclude":false,"priority":"medium"},{"title":"倒吊人途径全序列（异种）","content":"倒吊人途径对应塔罗牌「倒吊人」，序列0为「倒吊人」，属欲望母树侧（暗影世界、深渊、被缚者分组），主打异变、折磨与被缚。已知低序列为序列9异种——身体异变、获得非人特质。机制要点：倒吊人途径源于异种王克瓦希图恩（被缚者组），与深渊、被缚者相邻，能力多带「畸变与痛苦」色彩；暗天使萨斯利尔（倒吊人2+0）即此途径的高位存在。扮演核心是成为「承受并驾驭异变者」，消化靠对痛苦的超越。中段序列名称按教会机密逐层揭示。","category":"规则","tags":["倒吊人途径","异种","全序列","被缚者组"],"alwaysInclude":false,"priority":"medium"},{"title":"被缚之神途径全序列（囚犯）","content":"被缚之神途径对应塔罗牌「被缚者」，序列0为「被缚之神」，属欲望母树侧（暗影世界、深渊、被缚者分组），主打束缚、释放与混沌。已知低序列为序列9囚犯——突破束缚、获得力量却受困。机制要点：被缚之神途径与倒吊人、深渊相邻，高层执掌「束缚与释放」的悖论权柄；恶魔君王法布提曾掌握部分被缚者途径，异种王克瓦希图恩亦涉被缚者。扮演核心是成为「挣脱与承受束缚的辩证者」，消化靠对自由的认知。中段序列名称按教会机密逐层揭示。","category":"规则","tags":["被缚之神途径","囚犯","全序列","被缚者"],"alwaysInclude":false,"priority":"medium"},{"title":"魔药调配与晋升仪式流程","content":"晋升是庄重的工作流程：先依配方集齐主辅材料（主材与序列严格对应、多取自非凡生物器官；辅材调和毒性），在遮蔽环境下依序加入、搅拌、激发，完成魔药；饮下后即刻进入「消化期」，须以扮演法活成序列名、化解特性冲突。高阶晋升更需举行仪式：以符文、祭品、咒文（古赫密斯语等）构筑接口，向对应权柄或源质借力，引来注视与考验。规则要点：流程不可省略，出错即失控或反噬；仪式必留痕迹，事后须清理或遮蔽。主持要点：写晋升与调配戏写出「程序感与压迫感」，每一步都算数，给足代价。","category":"设定","tags":["魔药调配","晋升仪式","流程","扮演"],"alwaysInclude":false,"priority":"medium"},{"title":"古赫密斯语与咒文体系","content":"古赫密斯语是诡秘世界最古老的神秘学语言，诸多咒文、仪式与封印物铭文皆以其书写——念错即反噬，念对则撬动权柄。咒文体系与塔罗牌、星象、符文互为表里，是高序列能力（如空想家编织现实、审判者颁布律令）的「语法」。规则要点：语言即权柄的接口，教会与隐秘组织皆以古赫密斯语为秘传；现代通用语（鲁恩语、弗萨克语等）则用于世俗。主持要点：写咒文戏突出「古老语言的不可轻渎」——音节落地，现实随之改变。","category":"设定","tags":["古赫密斯语","咒文","神秘学语言","仪式"],"alwaysInclude":false,"priority":"low"},{"title":"符文与象征体系","content":"符文与象征是诡秘世界构筑仪式、封印与能力的「几何语言」——特定符号与方位对应特定权柄与存在，组合即成接口。塔罗牌（二十二张大阿卡那）更是途径与序列的终极象征图谱，愚者、门、倒吊人等牌名即序列0权柄。规则要点：象征体系让「不可言说者」得以被操作，但也因直指高位存在而自带污染风险；封印物的铭文、仪式的法阵皆赖此。主持要点：写仪式与封印突出符号的「冷峻几何感」，让象征本身成为恐怖与力量的来源。","category":"设定","tags":["符文","象征","塔罗牌","仪式"],"alwaysInclude":false,"priority":"low"},{"title":"非凡者的世俗掩护身份","content":"七神教会要求非凡者对普通人保密，故官方非凡者多有世俗掩护：值夜者挂职黑荆棘安保公司，代罚者、机械之心渗入军警与工厂，牧师、修女以教职掩真身。野途径者则常以私家侦探、记者、水手、古董商、医生等身份活动（克莱恩即化名侦探夏洛克·莫里亚蒂、出海者格尔曼·斯帕罗）。规则要点：掩护身份是非凡者行走世俗的必需品，也是「双重生活」张力的来源；身份暴露即引教会追查。主持要点：写非凡者先写其世俗皮囊，再让非凡从生活缝隙里渗出，距离感即神秘感。","category":"设定","tags":["掩护身份","保密","世俗","双重生活"],"alwaysInclude":false,"priority":"medium"},{"title":"圣堂与封印物库房","content":"各教会建有圣堂，地底库房专门封印0级与1级封印物，由主教与高层守护，受多重仪式与屏蔽保护。0级封印物须封印于圣堂地底、不可打听不可窥探；1级由教区总部中央教堂保存一到两件，其余上交圣堂；2级各城市中央教堂存三到五件；3级由值夜者小队等基层持有。规则要点：圣堂是教会权力的物理核心，也是各方窃取与争夺的焦点；封印物库房的安全等级直接反映教会实力。主持要点：写圣堂突出「沉于地底、被沉默守护」的禁忌感，每一次开库都是险棋。","category":"设定","tags":["圣堂","封印物库房","教会","封印"],"alwaysInclude":false,"priority":"medium"},{"title":"非凡材料与生物器官市场","content":"魔药主材多取自非凡生物的血肉器官（如特定序列对应的眼珠、心脏、鳞片等），形成隐秘的材料市场。黑市、出海线与狩猎场是非凡材料的主要来源，价格高昂且真伪难辨——一份低序列配方可抵平民数年工钱。规则要点：材料的稀缺与危险驱动了猎杀、走私与黑市交易，是「非凡无捷径」的经济侧写；野途径者为材料常铤而走险。主持要点：写材料戏先写「来路不明的器官与天价」，再让其牵出狩猎、背叛与追杀的连锁。","category":"设定","tags":["非凡材料","生物器官","黑市","魔药"],"alwaysInclude":false,"priority":"medium"},{"title":"神谕与教会回应代价","content":"诸神真实存在并会回应祈祷，但回应有代价——神谕多晦涩象征、需解读者参悟，且过度祈祷与索取会消耗信徒的信仰之锚、招致注视污染。教会以固定仪式向上祈求，回应经化身或代理人完成，绝非零成本的许愿机。规则要点：这一铁律决定了「祈祷不是许愿机」，也解释了教会为何严格控制晋升与仪式；玩家求助神明须付出等价代价。主持要点：写神谕戏突出「遥不可及的回应与暗藏的价码」，保持神性的疏离与威严。","category":"设定","tags":["神谕","祈祷","回应代价","锚"],"alwaysInclude":false,"priority":"medium"},{"title":"半神门槛与神性侵蚀","content":"序列4是非凡者跨入半神（半神半人、神话生物）的门槛，自此神性渐强、人性被吞噬，发生质变、近乎神灵。序列4至序列1统称天使层级，需以锚稳定人性、对抗神性侵蚀；失去锚者将彻底疯狂或概念化。规则要点：半神门槛是「凡人与神明」的分水岭，也是聚合定律发力的起点——高位特性无意识吸引低序列者靠近。主持要点：写半神出场突出「已非完全之人」的疏离与威压，其人性残存处正是戏剧张力所在。","category":"设定","tags":["半神","序列4","神性侵蚀","门槛"],"alwaysInclude":false,"priority":"high"},{"title":"序列相邻途径互换规则","content":"二十二途径按源质分组，同组相邻途径可在序列4及以上互相替代、互换魔药而不劣化（如黑夜与战争、死亡同属永暗之河组；通识者与窥秘人同组；黑皇帝与审判者相邻；红祭司与黑皇帝不相邻致疯）。不相邻途径强行互吃魔药会神性暴走、几近必死。规则要点：相邻互换是高位博弈的弹性空间，也是「转途径」剧情（如图铎转红祭司而半疯、特伦索斯特转审判者）的机制根基。主持要点：写转途径戏突出「相邻则生、不相邻则疯」的残酷法则，给足代价。","category":"规则","tags":["相邻途径","互换","转途径","源质分组"],"alwaysInclude":false,"priority":"high"},{"title":"二十二途径与旧日聚合分组","content":"二十二途径依九大源质聚为若干聚合组，同组途径相邻、高位互相吸引（聚合定律的动力学根源）。已知分组如：源堡组（占卜家、学徒、偷盗者，天尊侧）；混沌海组（空想家、黑暗、黄昏巨人，上帝侧）；永暗之河组（黑夜、死亡、战争）；灾祸之城组（红祭司等）；知识荒野组（白塔、隐者）；失序之国组（黑皇帝、审判者）；暗影世界组（魔女、深渊、被缚者、倒吊人，欲望母树侧）；母巢组（母亲、月亮）。规则要点：分组决定相邻互换与聚合猎杀的动力学；跨组强行晋升会神性暴走。主持要点：此分组在凡人视角仅作传闻，逐段投放。","category":"设定","tags":["二十二途径","聚合分组","源质","相邻"],"alwaysInclude":false,"priority":"top"}];
  for (var i = 0; i < add.length; i++) {
    var t = String(add[i].title || "").trim(); var dup = false;
    for (var j = 0; j < a.length; j++) { if (String(a[j].title || "").trim() === t) { dup = true; break; } }
    if (!dup) a.push(add[i]);
  }
  window.__KB_EXT_OK__ = true;
})();
